import { X } from "lucide-react"
import { useAppTranslation } from "@/i18n/TranslationContext"

/**
 * ModalHeader Component
 * 
 * A reusable modal header component that displays a title and close button.
 * Used in all modal dialogs across MCP, Modes, Rules, and Commands tabs.
 * 
 * Features:
 * - Title text on the left
 * - Close button (X icon) on the right
 * - Border bottom for visual separation
 * - Consistent padding and spacing
 * - Hover effects on close button
 * - Accessibility support with aria-label
 * 
 * @example
 * ```tsx
 * <ModalHeader
 *   title="Edit Mode"
 *   onClose={() => setIsOpen(false)}
 * />
 * ```
 */

interface ModalHeaderProps {
	/** Modal title text (required) */
	title: string
	/** Close button click handler (required) */
	onClose: () => void
	/** Optional subtitle or additional content below title */
	subtitle?: React.ReactNode
	/** Additional CSS classes for customization */
	className?: string
}

export const ModalHeader: React.FC<ModalHeaderProps> = ({ title, onClose, subtitle, className = "" }) => {
	const { t } = useAppTranslation()

	return (
		<div className={`flex items-center justify-between p-3 ${className}`}>
			<div className="flex-1">
				<div className="text-[16px] font-semibold">{title}</div>
				{subtitle && (
					<div className="text-sm text-vscode-descriptionForeground mt-1">
						{subtitle}
					</div>
				)}
			</div>
			<button
				onClick={onClose}
				className="text-vscode-descriptionForeground hover:text-vscode-foreground transition-colors cursor-pointer ml-2"
				aria-label={t("common:actions.close")}
			>
				<X size={20} />
			</button>
		</div>
	)
}

