import * as React from "react"
import { vscode } from "@src/utils/vscode"
import { useExtensionState } from "@/context/ExtensionStateContext"
import { ExtensionStateBinding } from "../BindingTypes"

interface ExtensionStateWrapperProps<TComponentProps extends Record<string, any>> {
	/** The component to render */
	component: React.ComponentType<TComponentProps & { value: any; setValue: (value: any) => void }>
	/** Binding configuration */
	binding: ExtensionStateBinding
	/** Component-specific props (excluding binding) */
	props?: TComponentProps
}

/**
 * Generic wrapper component that manages extension state binding
 * Accepts binding and props as separate parameters to match JSON schema structure
 *
 * @example
 * <ExtensionStateWrapper
 *   component={Toggle}
 *   binding={{ type: "extensionState", stateProp: "...", messageType: "..." }}
 *   props={{ noContainer: true, icon: <Icon /> }}
 * />
 */
function ExtensionStateWrapper<TComponentProps extends Record<string, any>>({
	component: Component,
	binding,
	props = {} as TComponentProps,
}: ExtensionStateWrapperProps<TComponentProps>) {
	const extensionState = useExtensionState()
	const stateValue = (extensionState as any)[binding.stateProp]

	const setValue = React.useCallback(
		(value: any) => {
			// ibm_change: Use updateSettings message format instead of individual message types
			// This ensures all settings go through the same handler and persist correctly
			vscode.postMessage({
				type: "updateSettings",
				updatedSettings: {
					[binding.stateProp]: value,
				},
			})
		},
		[binding.stateProp],
	)

	return <Component {...(props as any)} value={stateValue} setValue={setValue} />
}

export default ExtensionStateWrapper

