import React from "react"
import { BookOpen } from "lucide-react"
import { IncidentReporter } from "@carbon/icons-react"
import { Package } from "@roo/package"
import { useAppTranslation } from "@/i18n/TranslationContext"
import { VSCodeLink } from "@vscode/webview-ui-toolkit/react"
import { useBuildDocLink } from "@/utils/docLinks"
import { vscode } from "@/utils/vscode"

const SettingsSidebarFooter: React.FC = () => {
	const buildDocLink = useBuildDocLink()
	const { t } = useAppTranslation()

	const handleReportIssue = () => {
		vscode.postMessage({
			type: "executeCommand",
			commands: ["bob-code.reportIssue"],
		})
	}

	return (
		<div className="flex flex-col px-1 py-2 mt-6 border-t gap-1 border-vscode-descriptionForeground text-sm text-vscode-descriptionForeground opacity-60">
			<div className="px-2 mb-1">
				<div>{t("ibmSettings:sidebar.footer.version", { version: Package.version })}</div>
			</div>
			<VSCodeLink href={buildDocLink()}>
				<div className="flex items-center gap-2 text-vscode-descriptionForeground hover:text-vscode-textLink-foreground hover:no-underline ml-2">
					<BookOpen className="w-4 h-4" />
					<span>{t("ibmSettings:sidebar.footer.docs")}</span>
				</div>
			</VSCodeLink>
			<button
				onClick={handleReportIssue}
				className="flex items-center gap-2 text-vscode-descriptionForeground hover:underline hover:text-vscode-textLink-foreground px-2 py-1 cursor-pointer text-[13px]">
				<IncidentReporter size={16} />
				<span>{t("ibmSettings:sidebar.footer.reportIssue")}</span>
			</button>
		</div>
	)
}

export default SettingsSidebarFooter

