import { useEffect } from "react"

/**
 * useMarketplaceFilterReset Hook
 * 
 * Shared hook that resets filter to "all" when marketplace is disabled
 * and a marketplace-specific filter is selected.
 */
export function useMarketplaceFilterReset<T extends string>(
	isMarketplaceEnabled: boolean,
	filterType: T,
	setFilterType: (filter: T) => void,
	marketplaceFilters: T[]
) {
	useEffect(() => {
		if (!isMarketplaceEnabled && marketplaceFilters.includes(filterType)) {
			setFilterType("all" as T)
		}
	}, [isMarketplaceEnabled, filterType, setFilterType, marketplaceFilters])
}

