import { useEffect, useState, useCallback } from "react"
import { vscode } from "@/utils/vscode"
import { getNestedValue } from "@/ibm/utils/getNestedValue"

/**
 * Custom hook to manage VSCode settings
 * Provides a way to read and write VSCode settings with automatic updates
 * when the setting changes externally
 *
 * @param settingKey - The VSCode setting key (e.g., "ibm-bob-config.CodeCompletionMode")
 * @param defaultValue - Default value if setting is not found
 * @returns A tuple of [value, setValue] similar to useState
 */
export function useVSCodeSetting<T = any>(settingKey: string, defaultValue: T): [T, (value: T) => void] {
	const [value, setValue] = useState<T>(defaultValue)

	// Request the current setting value when component mounts or settingKey changes
	useEffect(() => {
		vscode.postMessage({
			type: "getVSCodeSetting",
			setting: settingKey,
		})
	}, [settingKey])

	// Listen for setting updates from the extension
	useEffect(() => {
		const messageHandler = (event: MessageEvent) => {
			const message = event.data
			if (message.type === "vsCodeSetting" && message.setting === settingKey) {
				setValue(message.value ?? defaultValue)
			}

			// Handle bulk format (full settings object)
			else if (message.type === "vsCodeSetting" && message.settings) {
				const newValue = getNestedValue(message.settings, settingKey)
				if (newValue !== undefined) {
					setValue(newValue)
				}
			}
		}

		window.addEventListener("message", messageHandler)
		return () => window.removeEventListener("message", messageHandler)
	}, [settingKey, defaultValue])

	// Function to update the setting
	const updateSetting = useCallback(
		(newValue: T) => {
			setValue(newValue)
			vscode.postMessage({
				type: "updateVSCodeSetting",
				setting: settingKey,
				value: newValue as any,
			})
		},
		[settingKey],
	)

	return [value, updateSetting]
}

