import React, { useMemo } from "react"

interface HighlightedTextProps {
	/** The text to display */
	text: string
	/** Character positions to highlight (0-indexed) */
	positions: number[]
	/** CSS class for highlighted characters */
	highlightClassName?: string
	/** Additional CSS class for the container span */
	className?: string
}

interface TextSegment {
	text: string
	isHighlighted: boolean
}

interface PositionRange {
	start: number
	end: number
}

/**
 * Groups an array of sorted positions into ranges of consecutive positions.
 * e.g., [0, 1, 2, 5, 6] → [{start: 0, end: 2}, {start: 5, end: 6}]
 */
function groupConsecutivePositions(sortedPositions: number[]): PositionRange[] {
	if (sortedPositions.length === 0) {
		return []
	}

	const ranges: PositionRange[] = []
	let rangeStart = sortedPositions[0]
	let rangeEnd = sortedPositions[0]

	for (let i = 1; i < sortedPositions.length; i++) {
		const currentPos = sortedPositions[i]

		if (currentPos === rangeEnd + 1) {
			// Extend current range
			rangeEnd = currentPos
		} else {
			// Save completed range and start a new one
			ranges.push({ start: rangeStart, end: rangeEnd })
			rangeStart = currentPos
			rangeEnd = currentPos
		}
	}

	// Don't forget the last range
	ranges.push({ start: rangeStart, end: rangeEnd })

	return ranges
}

/**
 * Builds text segments from highlight ranges.
 * Alternates between non-highlighted and highlighted segments.
 */
function buildTextSegments(text: string, highlightRanges: PositionRange[]): TextSegment[] {
	const segments: TextSegment[] = []
	let cursor = 0

	for (const range of highlightRanges) {
		// Add non-highlighted text before this range (if any)
		if (range.start > cursor) {
			segments.push({
				text: text.substring(cursor, range.start),
				isHighlighted: false,
			})
		}

		// Add highlighted text for this range
		segments.push({
			text: text.substring(range.start, range.end + 1),
			isHighlighted: true,
		})

		cursor = range.end + 1
	}

	// Add remaining non-highlighted text after last range
	if (cursor < text.length) {
		segments.push({
			text: text.substring(cursor),
			isHighlighted: false,
		})
	}

	return segments
}

const DEFAULT_HIGHLIGHT_CLASS =
	"bg-vscode-editor-findMatchHighlightBackground text-vscode-editor-findMatchHighlightForeground rounded-sm px-0.5 -mx-0.5"

/**
 * Renders text with specific character positions highlighted.
 * This is a React-safe alternative to dangerouslySetInnerHTML.
 *
 * @example
 * <HighlightedText
 *   text="Search settings"
 *   positions={[0, 1, 2]}
 *   highlightClassName="bg-vscode-editor-findMatchHighlightBackground"
 * />
 * // Renders: <span><mark>Sea</mark>rch settings</span>
 */
export const HighlightedText: React.FC<HighlightedTextProps> = ({
	text,
	positions,
	highlightClassName = DEFAULT_HIGHLIGHT_CLASS,
	className = "",
}) => {
	const elements = useMemo(() => {
		if (!positions || positions.length === 0) {
			return [text]
		}

		const sortedPositions = [...positions].sort((a, b) => a - b)
		const highlightRanges = groupConsecutivePositions(sortedPositions)
		const segments = buildTextSegments(text, highlightRanges)

		return segments.map((segment, index) =>
			segment.isHighlighted ? (
				<mark key={index} className={highlightClassName}>
					{segment.text}
				</mark>
			) : (
				<React.Fragment key={index}>{segment.text}</React.Fragment>
			),
		)
	}, [text, positions, highlightClassName])

	return <span className={className}>{elements}</span>
}

/**
 * Utility function to check if there are any highlight positions
 */
export function hasHighlights(positions: number[] | undefined): boolean {
	return positions !== undefined && positions.length > 0
}

