import * as React from "react"
import { Input } from "@/components/ui"

export interface NumberInputProps {
	/** Current input value */
	value: number
	/** Callback when input value changes */
	setValue: (value: number) => void
	/** Minimum allowed value */
	min?: number
	/** Maximum allowed value */
	max?: number
	/** Step value for the input */
	step?: number
	/** Placeholder text */
	placeholder?: string
	/** Special value handling function */
	valueHandler?: (value: string) => number | undefined
	/** Whether the component is disabled */
	disabled?: boolean
	/** CSS class name to apply to the component */
	className?: string
	/** Test ID for the component */
	testId?: string
}

/**
 * Pure NumberInput component for settings
 * Receives value and setValue props from wrapper components
 * This component is state-agnostic and can be used with any state management approach
 */
const NumberInput: React.FC<NumberInputProps> = ({
	value,
	setValue,
	min,
	max,
	step,
	placeholder,
	disabled = false,
	testId,
	className,
	valueHandler,
}) => {
	// Handle input change
	const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
		const inputValue = e.target.value

		// Use custom value handler if provided
		if (valueHandler) {
			const processedValue = valueHandler(inputValue)
			if (processedValue !== undefined) {
				setValue(processedValue)
			}
			return
		}

		// Default handling for number inputs
		const newValue = parseInt(inputValue, 10)
		if (!isNaN(newValue)) {
			// Check min/max constraints
			if ((min === undefined || newValue >= min) && (max === undefined || newValue <= max)) {
				setValue(newValue)
			}
		}
	}

	return (
		<div className="flex items-center gap-2">
			<Input
				type="number"
				className={`w-14 h-6 bg-vscode-input-background text-vscode-input-foreground px-1 rounded text-sm ${className || ""}`}
				value={value}
				min={min}
				max={max}
				step={step}
				placeholder={placeholder}
				disabled={disabled}
				onChange={handleChange}
				data-testid={testId}
			/>
		</div>
	)
}

export default NumberInput

