import { DEFAULT_MODES, type ModeConfig, MarketplaceItem } from "@roo-code/types"
import { getGroupName } from "@roo/modes"
import { isBuiltInMode, ModeItem } from "./hooks/useModes"
import { TOOL_GROUPS } from "@roo/tools"

/**
 * Translation function type matching the signature from TranslationContext
 */
export type TranslateFunction = (key: string, options?: Record<string, any>) => string

/**
 * Get the translated label for a tool group.
 * Falls back to capitalized group name if translation is not found.
 *
 * @param group - The tool group name (e.g., "read", "edit", "browser")
 * @param t - Translation function from useAppTranslation
 * @returns Translated label or capitalized group name as fallback
 *
 * @example
 * ```ts
 * const label = getToolGroupLabel("read", t)
 * // Returns: "Read Files" (translated) or "Read" (fallback)
 * ```
 */
export function getToolGroupLabel(group: string, t: TranslateFunction): string {
	// ibm_change_start: Show generic label for unknown tool groups (e.g., from apiExtension)
	// Check if this is a known tool group
	const isKnownGroup = group in TOOL_GROUPS
	
	if (!isKnownGroup) {
		// Unknown group from external source (e.g., apiExtension) - show generic label
		return t('ibmSettings:modes.details.tool_groups.external_source')
	}
	// ibm_change_end
	
	// For known groups, use translation or capitalized fallback
	const translationKey = `ibmSettings:modes.details.tool_groups.${group}`
	const translated = t(translationKey)
	return translated === translationKey ? group.charAt(0).toUpperCase() + group.slice(1) : translated
}

/**
 * Find the default mode configuration from DEFAULT_MODES by slug.
 * Used to compare built-in modes with their default values.
 * 
 * @param slug - The mode slug to search for
 * @returns The default ModeConfig if found, undefined otherwise
 * 
 * @example
 * ```ts
 * const defaultMode = getDefaultModeConfig("code")
 * if (defaultMode) {
 *   console.log(defaultMode.description)
 * }
 * ```
 */
export function getDefaultModeConfig(slug: string): ModeConfig | undefined {
	return DEFAULT_MODES.find((m: ModeConfig) => m.slug === slug)
}

/**
 * Compare a mode's current values with its default configuration.
 * Returns an object indicating which fields have been modified from defaults.
 * Used to show reset buttons for modified fields in the UI.
 * 
 * @param mode - The current mode to compare
 * @param defaultMode - The default mode configuration (optional, will be looked up if not provided)
 * @returns Object with boolean flags for each field indicating if it's modified
 * 
 * @example
 * ```ts
 * const modifications = compareWithDefaults(mode, defaultMode)
 * if (modifications.isDescriptionModified) {
 *   // Show reset button for description
 * }
 * ```
 */
export function compareWithDefaults(
	mode: ModeItem,
	defaultMode?: ModeConfig
): {
	isDescriptionModified: boolean
	isRoleDefinitionModified: boolean
	isWhenToUseModified: boolean
	isCustomInstructionsModified: boolean
} {
	// If no default mode provided, try to find it
	const defaults = defaultMode || (isBuiltInMode(mode)? getDefaultModeConfig(mode.data.slug) : undefined)

	// If no defaults found, nothing is modified
	if (!defaults) {
		return {
			isDescriptionModified: false,
			isRoleDefinitionModified: false,
			isWhenToUseModified: false,
			isCustomInstructionsModified: false,
		}
	}

	return {
		isDescriptionModified: (mode.data.description || "") !== (defaults.description || ""),
		isRoleDefinitionModified: (mode.data.roleDefinition || "") !== (defaults.roleDefinition || ""),
		isWhenToUseModified: (mode.data.whenToUse || "") !== (defaults.whenToUse || ""),
		isCustomInstructionsModified: (mode.data.customInstructions || "") !== (defaults.customInstructions || ""),
	}
}

/**
 * Find a marketplace item by its ID.
 * Used to locate the original marketplace item for installation or other operations.
 * 
 * @param modeId - The marketplace item ID to search for
 * @param marketplaceItems - Array of marketplace items to search in
 * @returns The MarketplaceItem if found, undefined otherwise
 * 
 * @example
 * ```ts
 * const item = findMarketplaceItem(mode.metaData?.id, marketplaceItems)
 * if (item) {
 *   // Open install modal with item
 * }
 * ```
 */
export function findMarketplaceItem(
	modeId: string | undefined,
	marketplaceItems: MarketplaceItem[] | undefined
): MarketplaceItem | undefined {
	if (!modeId || !marketplaceItems) {
		return undefined
	}
	return marketplaceItems.find((item) => item.id === modeId && item.type === "mode")
}

/**
 * Extract and normalize tool groups from a mode's configuration.
 * Handles both string and tuple formats for group definitions.
 * 
 * @param mode - The mode to extract tool groups from
 * @returns Array of normalized tool group names
 * 
 * @example
 * ```ts
 * const groups = getToolGroups(mode)
 * // Returns: ["read", "edit", "browser"]
 * ```
 */
export function getToolGroups(mode: ModeItem): string[] {
	if (!mode.data?.groups) {
		return []
	}
	return mode.data.groups.map((group) => getGroupName(group))
}

