import React from "react"
import { useAppTranslation } from "@/i18n/TranslationContext"
import { Button, StandardTooltip } from "@/components/ui"
import { ModeItem } from "./hooks/useModes"
import { ItemTile } from "../../components/common"
import { useMarketplaceEnabled } from "./hooks/useMarketplaceEnabled" // ibm_change
import { getModeBadges } from "./utils/modeBadges" // ibm_change

interface ModeTileProps {
	modeItem: ModeItem
	onClick?: () => void
	onInstall?: (modeId: string) => void
}

/**
 * ModeTile Component
 * 
 * Displays a single mode tile with icon, name, description, and status indicators.
 * Shows type (Built-in/Custom/Marketplace) and scope (Global/Project) badges.
 * For marketplace modes: shows Install button if not installed, or Installed indicator if installed.
 * All edit/delete/uninstall actions are handled in the Mode Details View (Task 4).
 */
export const ModeTile: React.FC<ModeTileProps> = ({
	modeItem,
	onClick,
	onInstall,
}) => {
	const { t } = useAppTranslation()
	// ibm_change: Check if marketplace is enabled
	const isMarketplaceEnabled = useMarketplaceEnabled()

	// Get mode properties
	const name = modeItem.data.name
	const description = modeItem.data.description
	const author = modeItem?.metaData?.author
	const isMarketplaceItem = modeItem.type === 'marketplace'
	const isInstalled = modeItem?.metaData?.isInstalled
	const isApiRegistered = modeItem.type === 'apiRegistered'
	const sourceName = modeItem.sourceInfo?.sourceName
	
	// ibm_change: Use badge utility instead of inline functions
	const { statusText } = getModeBadges(modeItem, t, isMarketplaceEnabled)

	// Handle install button click
	const handleInstall = (e: React.MouseEvent) => {
		e.stopPropagation()
		if (isMarketplaceItem&& onInstall && modeItem?.metaData?.id) {
			onInstall(modeItem.metaData.id)
		}
	}

	// Build action slot (Install button for marketplace modes)
	const getActionSlot = () => {
		// ibm_change: Only show install button if marketplace is enabled
		if (isMarketplaceItem && !isInstalled && isMarketplaceEnabled) {
			return (
				<StandardTooltip content={t("ibmSettings:modes.actions.install_mode")}>
					<Button
						variant="outline"
						size='sm'
						onClick={handleInstall}
					>
						{t("ibmSettings:modes.install")}
					</Button>
				</StandardTooltip>
			)
		}
		return undefined
	}

	// Build metadata (author line or source attribution)
	const getMetadata = () => {
		if (isApiRegistered && sourceName) {
			return `${t("ibmSettings:modes.from_source")} ${sourceName}`
		}
		if (author) {
			return `${t("ibmSettings:shared.by_author")} ${author}`
		}
		return undefined
	}

	return (
		<ItemTile
			title={name}
			description={description}
			metadata={getMetadata()}
			statusText={statusText}
			actionSlot={getActionSlot()}
			onClick={onClick || (() => {})} // Always provide onClick to maintain role="button" and tabIndex
		/>
	)
}

