import React, { useEffect } from 'react'
import { ModalHeader } from './ModalHeader'
import { ModalFooter } from './ModalFooter'
import { useEscapeKey } from '@/hooks/useEscapeKey'

/**
 * ItemEditModal Component
 * 
 * A reusable modal wrapper component that composes ModalHeader and ModalFooter
 * with a scrollable body area. Used for all edit/create dialogs across MCP,
 * Modes, Rules, and Commands tabs.
 * 
 * Features:
 * - Modal overlay with backdrop
 * - Centered modal container with max width/height constraints
 * - Composed ModalHeader and ModalFooter components
 * - Scrollable body area for form content
 * - ESC key handling to close modal
 * - Body scroll prevention when modal is open
 * - Clicking overlay does NOT close modal (only close button or ESC)
 * 
 * @example
 * ```tsx
 * <ItemEditModal
 *   isOpen={isOpen}
 *   title="Edit Mode"
 *   onClose={() => setIsOpen(false)}
 *   footer={
 *     <>
 *       <Button variant="ghost" onClick={onCancel}>Cancel</Button>
 *       <Button onClick={onSave}>Save</Button>
 *     </>
 *   }
 * >
 *   <div className="space-y-6">
 *     {/* Form fields go here *\/}
 *   </div>
 * </ItemEditModal>
 * ```
 * 
 * Design Reference: Edit Mode modal (Figma 476-8985)
 * Source Reference: EditModeModal.tsx (lines 1-328)
 */

interface ItemEditModalProps {
	/** Modal open state (required) */
	isOpen: boolean
	/** Modal title (required) */
	title: string
	/** Close handler (required) */
	onClose: () => void
	/** Form content (required) */
	children: React.ReactNode
	/** Footer buttons (required) */
	footer: React.ReactNode
	/** Optional subtitle or additional content below title */
	subtitle?: React.ReactNode
	/** Additional CSS classes for customization */
	className?: string
}

export const ItemEditModal: React.FC<ItemEditModalProps> = ({
	isOpen,
	title,
	onClose,
	children,
	footer,
	subtitle,
	className = '',
}) => {
	// Handle ESC key to close modal
	useEscapeKey(isOpen, onClose)

	// Prevent body scroll when modal is open
	useEffect(() => {
		if (isOpen) {
			document.body.style.overflow = 'hidden'
		} else {
			document.body.style.overflow = ''
		}

		return () => {
			document.body.style.overflow = ''
		}
	}, [isOpen])

	// Don't render if not open
	if (!isOpen) {
		return null
	}

	return (
		<div
			className="fixed inset-0 flex items-center justify-center z-50"
			data-testid="modal-overlay"
		>
			{/* Backdrop overlay with opacity */}
			<div className="absolute inset-0 bg-vscode-sideBar-background opacity-50" />
			
			{/* Modal container - sits above backdrop */}
			<div
				className={`relative bg-vscode-editor-background rounded-lg max-w-[900px] w-full flex flex-col max-h-[95vh] border border-vscode-panel-border ${className}`.trim()}
				onClick={(e) => e.stopPropagation()}
				data-testid="modal-container"
			>
				{/* Modal Header */}
				<ModalHeader title={title} onClose={onClose} subtitle={subtitle} />

				{/* Modal Body - Scrollable Content Area */}
				<div className="flex-1 overflow-y-auto p-2" data-testid="modal-body">
					{children}
				</div>

				{/* Modal Footer */}
				<ModalFooter>
					{footer}
				</ModalFooter>
			</div>
		</div>
	)
}

