import { useState, useCallback } from 'react'

/**
 * Return type for the useModal hook
 * @template T - Type of data associated with the modal (defaults to void)
 */
export interface UseModalReturn<T = void> {
	/** Whether the modal is currently open */
	isOpen: boolean
	/** Optional data associated with the modal */
	data: T | null
	/** Open the modal with optional data */
	open: (data?: T) => void
	/** Close the modal and clear data */
	close: () => void
}

/**
 * A reusable hook for managing modal state with optional associated data.
 * Provides consistent modal open/close behavior and reduces boilerplate.
 *
 * @template T - Type of data to associate with the modal (defaults to void for simple modals)
 * @returns Object containing modal state and control functions
 *
 * @example
 * Simple modal without data:
 * ```tsx
 * const deleteModal = useModal()
 * 
 * // Open modal
 * <button onClick={deleteModal.open}>Delete</button>
 * 
 * // Render modal
 * {deleteModal.isOpen && (
 *   <ConfirmDialog onClose={deleteModal.close} />
 * )}
 * ```
 *
 * @example
 * Modal with associated data:
 * ```tsx
 * const installModal = useModal<MarketplaceItem>()
 * 
 * // Open modal with data
 * <button onClick={() => installModal.open(item)}>Install</button>
 * 
 * // Render modal with data
 * {installModal.isOpen && installModal.data && (
 *   <InstallModal item={installModal.data} onClose={installModal.close} />
 * )}
 * ```
 *
 * @example
 * Multiple modals in one component:
 * ```tsx
 * const deleteModal = useModal()
 * const editModal = useModal<ModeItem>()
 * const installModal = useModal<MarketplaceItem>()
 * 
 * // Each modal has independent state
 * ```
 */
export function useModal<T = void>(): UseModalReturn<T> {
	const [isOpen, setIsOpen] = useState(false)
	const [data, setData] = useState<T | null>(null)

	const open = useCallback((modalData?: T) => {
		setIsOpen(true)
		setData(modalData ?? null)
	}, [])

	const close = useCallback(() => {
		setIsOpen(false)
		setData(null)
	}, [])

	return {
		isOpen,
		data,
		open,
		close,
	}
}

