import React from "react"
import { useAppTranslation } from "@/i18n/TranslationContext"
import { vscode } from "@src/utils/vscode"
import { useBuildDocLink } from "@/utils/docLinks"

/**
 * Custom component for the Tools section header description
 * Displays introductory text, warning text with documentation link,
 * and the "Auto-Approve" header
 */
const ToolsHeaderDescription: React.FC = () => {
	const buildDocLink = useBuildDocLink()
	const { t } = useAppTranslation()

	return (
		<>
			<div>{t("ibmSettings:tools.introText")}</div>
			<div className="mt-2">
				{t("ibmSettings:tools.warningText")}{" "}
				<a
					href="#"
					className="text-blue-500 hover:underline"
					onClick={() => vscode.postMessage({ type: "openExternal", url: buildDocLink() })}>
					{t("ibmSettings:tools.docsLink")}
				</a>
			</div>
			<div className="flex w-full justify-end -mb-1 text-sm font-medium mt-4">
				{t("ibmSettings:tools.autoApprove.title")}
			</div>
		</>
	)
}

export default ToolsHeaderDescription

