import * as React from "react"
import { SettingsTabDefinition } from "../SettingsDefinition"
import SectionRenderer from "./SectionRenderer"

/**
 * Props for the TabRenderer component
 */
interface TabRendererProps {
	/** The tab definition to render */
	definition: SettingsTabDefinition
	/** Set of matched setting IDs when search is active (null when not searching) */
	matchedSettingIds?: Set<string> | null
	/** Whether search mode is active */
	isSearchActive?: boolean
}

/**
 * Renders a settings tab based on a JSON definition
 */
const TabRenderer: React.FC<TabRendererProps> = ({ definition, matchedSettingIds, isSearchActive }) => {
	const { sections } = definition

	return sections.map((section, index) => (
		<SectionRenderer
			key={index}
			definition={section}
			sectionIndex={index}
			matchedSettingIds={matchedSettingIds}
			isSearchActive={isSearchActive}
		/>
	))
}

export default TabRenderer

