// If any of these settings should appear in the VS Code config,
// then also define them in src/package.json, under "bob-code"
export type CodeCompletionMode = "off" | "autocomplete" | "nextEdit"
export const VALID_CODE_COMPLETION_MODES: readonly CodeCompletionMode[] = ["off", "autocomplete", "nextEdit"] as const

export type LlmAttrMode = "git-notes" | "comments" | "disabled"

export const IBM_BOB_CONFIG_KEY = "ibm-bob-config" as const
export const IBM_BOB_CONFIG_LOG_LEVEL_KEY = `${IBM_BOB_CONFIG_KEY}.logLevel` as const
export const IBM_BOB_CONFIG_BOB_TIPS_KEY = `${IBM_BOB_CONFIG_KEY}.findings.bobTips.enabled` as const
export const IBM_BOB_CONFIG_SEMGREP_KEY = `${IBM_BOB_CONFIG_KEY}.findings.semgrep.enabled` as const
export const IBM_BOB_CONFIG_SECRETS_KEY = `${IBM_BOB_CONFIG_KEY}.findings.secrets.enabled` as const
export const IBM_BOB_CONFIG_CODE_COMPLETION_MODE_KEY = `${IBM_BOB_CONFIG_KEY}.codeCompletionMode` as const
export const IBM_BOB_CONFIG_COMMIT_PROMPT_KEY = `${IBM_BOB_CONFIG_KEY}.review.commitPrompt.enabled` as const
export const IBM_BOB_CONFIG_COMMAND_SECURITY_MODE_KEY = `${IBM_BOB_CONFIG_KEY}.commandSecurityMode` as const
export const IBM_BOB_CONFIG_REVIEW_EXCLUSIONS = `${IBM_BOB_CONFIG_KEY}.review.exclusions` as const
export const IBM_BOB_CONFIG_LLM_ATTRIBUTION_MODE_KEY = `${IBM_BOB_CONFIG_KEY}.llmAttributionMode`

export interface BobSourceUserConfig {
	id: string
	allowed_tools: string[]
}
export type LogLevel = "debug" | "info" | "warn" | "error"

export interface BobFindingsUserConfig {
	bobTips: {
		enabled: boolean
	}
	semgrep: {
		enabled: boolean
	}
	secrets: {
		enabled: boolean
	}
}

export interface BobReviewUserConfig {
	commitPrompt: {
		enabled: boolean
	}
	exclusions: string[]
}

/**
 * Command security mode options:
 * - "off": No security checking (default)
 * - "autoApprovalOnly": Only check auto-approved commands
 * - "allCommands": Check all commands before execution
 */
export type CommandSecurityMode = "off" | "autoApprovalOnly" | "allCommands"
export const VALID_COMMAND_SECURITY_MODES: readonly CommandSecurityMode[] = ["off", "autoApprovalOnly", "allCommands"] as const

export interface BobConfig {
	// enableTabAutocomplete: boolean;
	logLevel: LogLevel
	codeCompletionMode: CodeCompletionMode
	commandSecurityMode: CommandSecurityMode
	findings: BobFindingsUserConfig
	review: BobReviewUserConfig
	sources: BobSourceUserConfig[]
}
