import * as React from "react"
import { useAppTranslation } from "@/i18n/TranslationContext"
import { Button, type ButtonProps } from "@/components/ui/button"
import { vscode } from "@/utils/vscode"

/**
 * Props for the CommandButton component
 */
export interface CommandButtonProps extends ButtonProps {
	/** The command to execute */
	command?: string
	/** Optional command arguments */
	commandArgs?: any[]
	/** Optional additional commands to execute */
	additionalCommands?: string[]
	/** Translation key for the button label */
	labelKey: string
	/** Message type to send (defaults to "executeCommand") */
	messageType?: string
	/** Message property name (defaults to "commands") */
	messageProperty?: string
}

/**
 * Generic button component for executing VSCode commands
 * This component doesn't need state binding as it only executes commands
 */
const CommandButton: React.FC<CommandButtonProps> = ({
	command,
	commandArgs = [],
	additionalCommands = [],
	labelKey,
	messageType = "executeCommand",
	messageProperty = "commands",
	...buttonProps
}) => {
	const { t } = useAppTranslation()

	const handleClick = () => {
		const commands = [command, ...additionalCommands].filter(Boolean)
		vscode.postMessage({
			type: messageType as any,
			[messageProperty]: commands,
			commandArgs,
		})
	}

	return (
		<Button onClick={handleClick} {...buttonProps}>
			{t(labelKey)}
		</Button>
	)
}

export default CommandButton

