import { useState, useEffect } from "react"
import { useExtensionState } from "@/context/ExtensionStateContext"
import { DEFAULT_MODES, ModeConfig } from "@roo-code/types"
import { logger } from "@/ibm/utils/logger"
import * as yaml from "yaml"
import { useMarketplaceEnabled } from "./useMarketplaceEnabled" // ibm_change
import { useMarketplaceFetch } from "../../../hooks/useMarketplaceFetch" // ibm_change

export interface ModeMetadata {
	isInstalled?: boolean | undefined
	id?: string | undefined
	author?: string | undefined
	tags?: string[] | undefined
}

// ibm_change_start: Add apiRegistered mode type for modes registered via BobSource API
export type ModeType = "custom" | "marketplace" | "builtIn" | "apiRegistered"

// Source information for API-registered modes
export interface ModeSourceInfo {
	sourceId: string // The ID from BobSource.getId()
	sourceName: string // The human-readable name from BobSource.name
}

// Original mode values for reset functionality
export interface ModeOriginalValues {
	description?: string
	roleDefinition: string
	whenToUse?: string
	customInstructions?: string
	groups: ModeConfig['groups'] // Use the same type as ModeConfig.groups
}

export type ModeItem = {
	type: ModeType
	data: ModeConfig
	metaData?: ModeMetadata
	// Source information for API-registered modes
	sourceInfo?: ModeSourceInfo
	// Original values for reset functionality (for apiRegistered and builtIn modes)
	originalValues?: ModeOriginalValues
}
// ibm_change_end

/**
 * Custom hook to manage and provide access to all modes (built-in, custom, and marketplace)
 * Automatically refreshes when extension state changes
 */
export const useModes = () => {
	const { customModes: modes, marketplaceItems, marketplaceInstalledMetadata, customModePrompts } = useExtensionState()
	const [allModes, setAllModes] = useState<ModeItem[]>([])
	const [builtInModes, setBuiltInModes] = useState<ModeItem[]>([])
	const [marketplaceModes, setMarketplaceModes] = useState<ModeItem[]>([])
	const [customModes, setCustomModes] = useState<ModeItem[]>([])

	// ibm_change: Check marketplace-enabled feature flag using custom hook
	const isMarketplaceEnabled = useMarketplaceEnabled()

	// ibm_change: Use common marketplace fetch hook
	const {
		initialMarketplaceItemsLoaded,
		marketplaceFetchError,
		isMarketplaceNetworkError,
		retryMarketplaceFetch
	} = useMarketplaceFetch(isMarketplaceEnabled, "Modes")

	useEffect(() => {
		// Apply customModePrompts overrides to built-in modes
		const builtIn: ModeItem[] = DEFAULT_MODES.map(m => {
			const customPrompt = customModePrompts?.[m.slug]
			return {
				type: 'builtIn',
				data: {
					...m,
					// Override with custom prompts if they exist
					...(customPrompt?.description !== undefined && { description: customPrompt.description }),
					...(customPrompt?.roleDefinition !== undefined && { roleDefinition: customPrompt.roleDefinition }),
					...(customPrompt?.whenToUse !== undefined && { whenToUse: customPrompt.whenToUse }),
					...(customPrompt?.customInstructions !== undefined && { customInstructions: customPrompt.customInstructions }),
				},
				// Store original values for reset functionality
				originalValues: {
					description: m.description,
					roleDefinition: m.roleDefinition,
					whenToUse: m.whenToUse,
					customInstructions: m.customInstructions,
					groups: m.groups,
				}
			}
		})
		
		// ibm_change_start: Identify API-registered modes from the modes array
		// API-registered modes have sourceId and sourceName fields
		const apiRegistered: ModeItem[] = []
		const customOrMarketplace: ModeConfig[] = []
		
		modes.forEach(m => {
			// Check if this mode has source metadata (sourceId and sourceName)
			// This indicates it's an API-registered mode from a BobSource
			if (m.sourceId && m.sourceName) {
				// Apply customModePrompts overrides (same pattern as built-in modes)
				const customPrompt = customModePrompts?.[m.slug]
				const dataWithOverrides = {
					...m,
					// Override with custom prompts if they exist
					...(customPrompt?.description !== undefined && { description: customPrompt.description }),
					...(customPrompt?.roleDefinition !== undefined && { roleDefinition: customPrompt.roleDefinition }),
					...(customPrompt?.whenToUse !== undefined && { whenToUse: customPrompt.whenToUse }),
					...(customPrompt?.customInstructions !== undefined && { customInstructions: customPrompt.customInstructions }),
				}
				
				apiRegistered.push({
					type: 'apiRegistered',
					data: dataWithOverrides,
					sourceInfo: {
						sourceId: m.sourceId,
						sourceName: m.sourceName,
					},
					// Store original registry values for reset functionality (same as built-in modes use DEFAULT_MODES)
					originalValues: {
						description: m.description,
						roleDefinition: m.roleDefinition,
						whenToUse: m.whenToUse,
						customInstructions: m.customInstructions,
						groups: m.groups,
					}
				})
			} else {
				// Not API-registered, will be categorized as custom or marketplace
				customOrMarketplace.push(m)
			}
		})
		// ibm_change_end
		
		// Combine built-in and API-registered modes for the built-in section
		setBuiltInModes([...builtIn, ...apiRegistered])

		// ibm_change_start: Process marketplace modes using customOrMarketplace array (only if marketplace is enabled)
		const marketplace: ModeItem[] = isMarketplaceEnabled ? (marketplaceItems?.flatMap(m => {
			if (m.type !== 'mode' || !m.id || !m.content) {
				return []
			}
			let data: ModeConfig
			let originalValues: ModeOriginalValues | undefined
			try {
				// Parse the YAML content from marketplace
				const parsed = yaml.parse(m.content) as Partial<ModeConfig>

				// Validate and construct ModeConfig with required fields
				if (!parsed || typeof parsed !== 'object') {
					throw new Error('Invalid YAML content')
				}

				// Store original values from marketplace YAML (before any user modifications)
				originalValues = {
					description: parsed.description,
					roleDefinition: parsed.roleDefinition || '',
					whenToUse: parsed.whenToUse,
					customInstructions: parsed.customInstructions,
					groups: parsed.groups || [],
				}

				// If installed, use content from customOrMarketplace; otherwise use parsed YAML
				const slug = parsed.slug || m.id
				const installedMode = customOrMarketplace.find(mode => mode.slug === slug)
				if (installedMode) {
					// Use installed mode content with source from installation location
					data = installedMode
				} else {
					// Use parsed YAML content for uninstalled modes
					data = {
						slug: slug,
						name: parsed.name || m.name,
						roleDefinition: parsed.roleDefinition || '',
						groups: parsed.groups || [],
						// Optional fields from ModeConfig schema
						...(parsed.whenToUse && { whenToUse: parsed.whenToUse }),
						...(parsed.description && { description: parsed.description }),
						...(parsed.customInstructions && { customInstructions: parsed.customInstructions })
					}
				}
			} catch (error) {
				logger.error('[Modes]: Failed to parse marketplace content', error)
				return []
			}
			if (!data.slug || !data.name || !data.roleDefinition) {
				logger.error('[Modes]: Marketplace item missing key properties', data)
				return []
			}
			const metadata: ModeMetadata = {
				// For modes, check installation using the slug (not item.id) since modes are stored by slug
				isInstalled: marketplaceInstalledMetadata?.global[data.slug] || marketplaceInstalledMetadata?.project[data.slug] ? true : false
			}
			if (m.id) {
				metadata.id = m.id
			}
			if (m.author) {
				metadata.author = m.author
			}
			if (m.tags) {
				metadata.tags = m.tags
			}

			return [{
				type: 'marketplace',
				data,
				metaData: metadata,
				// Store original values for reset functionality (from marketplace YAML)
				originalValues
			}]
		}) || []) : []

		setMarketplaceModes(marketplace)

		// Custom modes are those in customOrMarketplace that aren't in marketplace
		const user: ModeItem[] = customOrMarketplace.flatMap(m => {
			if (marketplace.find(item => item.data.slug === m.slug)) {
				return []
			}
			return [{
				type: 'custom',
				data: m
			}]
		}) || []

		setCustomModes(user)

		// Combine all modes: built-in (including API-registered), custom, and marketplace (only if enabled)
		setAllModes([...builtIn, ...apiRegistered, ...user, ...(isMarketplaceEnabled ? marketplace : [])])
		// ibm_change_end
	}, [modes, marketplaceItems, marketplaceInstalledMetadata, customModePrompts, isMarketplaceEnabled])

	return {
		allModes,
		builtInModes,
		marketplaceModes,
		customModes,
		initialMarketplaceItemsLoaded,
		marketplaceFetchError, // ibm_change: Export error state
		isMarketplaceNetworkError, // ibm_change: Export marketplace network error flag
		retryMarketplaceFetch, // ibm_change: Export retry function
		marketplaceItems // Return marketplaceItems for use in handleInstall
	}
}

/**
 * Helper function to find a specific mode by slug from the modes list
 * Useful for refreshing a selected mode after updates
 */
export const findModeBySlug = (allModes: ModeItem[], slug: string): ModeItem | undefined => {
	return allModes.find(mode => mode.data.slug === slug)
}

// Made with Bob
// ibm_change_start: Type guards for mode categories
/**
 * Check if a mode is API-registered (from a BobSource)
 */
export const isApiRegisteredMode = (mode: ModeItem): boolean => {
	return mode.type === 'apiRegistered'
}

/**
 * Check if a mode is built-in (shipped with Bob)
 */
export const isBuiltInMode = (mode: ModeItem): boolean => {
	return mode.type === 'builtIn'
}

/**
 * Check if a mode is custom (user-created)
 */
export const isCustomMode = (mode: ModeItem): boolean => {
	return mode.type === 'custom'
}

/**
 * Check if a mode is from marketplace
 */
export const isMarketplaceMode = (mode: ModeItem): boolean => {
	return mode.type === 'marketplace'
}

/**
 * Check if a mode can be deleted (only custom and marketplace modes)
 */
export const canDeleteMode = (mode: ModeItem): boolean => {
	return mode.type === 'custom'
}

/**
 * Check if a mode can be reset to defaults (built-in and API-registered modes)
 */
export const canResetMode = (mode: ModeItem): boolean => {
	return (mode.type === 'builtIn' || mode.type === 'apiRegistered') && !!mode.originalValues
}

/**
 * Check if a mode's slug and name are editable (only custom modes)
 */
export const canEditModeIdentity = (mode: ModeItem): boolean => {
	return mode.type === 'custom'
}
// ibm_change_end
