import { ArrowLeft } from "lucide-react"
import { ReactNode } from "react"
import { Button } from "@/components/ui"
import { useAppTranslation } from "@/i18n/TranslationContext"

/**
 * OverviewHeader Component
 *
 * A reusable header component for detail views with back button, title, and action buttons.
 * Used in MCP, Mode, Rule, and Command detail views.
 *
 * @example
 * ```tsx
 * <OverviewHeader
 *   title="My Mode"
 *   onBack={() => navigate('back')}
 *   actions={
 *     <>
 *       <Button variant="ghost" size="icon"><Edit className="h-4 w-4" /></Button>
 *       <Button variant="ghost" size="icon"><Trash className="h-4 w-4" /></Button>
 *     </>
 *   }
 * />
 * ```
 */

interface OverviewHeaderProps {
	/** Header title (required) */
	title: string
	/** Back button handler (required) */
	onBack: () => void
	/** Action buttons slot */
	actions?: ReactNode
	/** Additional CSS classes */
	className?: string
}

export function OverviewHeader({ title, onBack, actions, className = "" }: OverviewHeaderProps) {
	const { t } = useAppTranslation()
	const backButtonTitle = t("common:actions.go_back")

	return (
		<div className={`flex items-center justify-between gap-4 ${className}`}>
			{/* Left: Back Button and Title */}
			<div className="flex items-center gap-3">
				<Button
					variant="ghost"
					size="icon"
					onClick={onBack}
					className="flex-shrink-0"
					title={backButtonTitle}
					aria-label={backButtonTitle}
				>
					<ArrowLeft className="h-4 w-4" />
				</Button>
				<h2 className="text-base font-normal text-vscode-foreground">{title}</h2>
			</div>

			{/* Right: Action Buttons */}
			{actions && <div className="flex items-center gap-1 flex-shrink-0">{actions}</div>}
		</div>
	)
}

