import { useRef, useEffect, useState } from "react"

interface UseScrollbarOnScrollOptions {
	/** Time in milliseconds to wait before hiding scrollbar after scrolling stops */
	hideDelay?: number
}

/**
 * Custom hook that manages scrollbar visibility - only shows during active scrolling
 * 
 * @param options - Configuration options
 * @returns Object containing ref to attach to scrollable element and className to apply
 * 
 * @example
 * ```tsx
 * const { scrollRef, scrollbarClassName } = useScrollbarOnScroll()
 * 
 * return (
 *   <div ref={scrollRef} className={`overflow-y-auto ${scrollbarClassName}`}>
 *     Content here
 *   </div>
 * )
 * ```
 */
export function useScrollbarOnScroll(options: UseScrollbarOnScrollOptions = {}) {
	const { hideDelay = 1000 } = options
	
	const scrollRef = useRef<HTMLDivElement>(null)
	const [isScrolling, setIsScrolling] = useState(false)
	const scrollTimeoutRef = useRef<NodeJS.Timeout>()

	useEffect(() => {
		const handleScroll = () => {
			setIsScrolling(true)
			
			// Clear existing timeout
			if (scrollTimeoutRef.current) {
				clearTimeout(scrollTimeoutRef.current)
			}
			
			// Hide scrollbar after scrolling stops
			scrollTimeoutRef.current = setTimeout(() => {
				setIsScrolling(false)
			}, hideDelay)
		}

		const scrollElement = scrollRef.current
		if (scrollElement) {
			scrollElement.addEventListener('scroll', handleScroll)
		}

		return () => {
			if (scrollElement) {
				scrollElement.removeEventListener('scroll', handleScroll)
			}
			if (scrollTimeoutRef.current) {
				clearTimeout(scrollTimeoutRef.current)
			}
		}
	}, [hideDelay])

	const scrollbarClassName = `scrollbar-on-scroll ${isScrolling ? 'is-scrolling' : ''}`

	return {
		scrollRef,
		scrollbarClassName,
		isScrolling,
	}
}

