import { useState, useEffect, useMemo, useCallback } from "react"
import { isApiRegisteredMode, isCustomMode, isMarketplaceMode, ModeItem } from "./useModes"
import { validateSlug, validateModeName, validateRoleDefinition } from "../modeValidation"
import { getDefaultModeConfig, getToolGroups } from "../modeUtils"
import { TranslateFunction } from "../modeUtils"
import { scopeType } from "../../../components/common/ScopeSelector"

/**
 * Form state interface containing all editable fields for a mode
 */
export interface ModeFormState {
	// Common fields (both built-in and custom modes)
	description: string
	roleDefinition: string
	whenToUse: string
	customInstructions: string

	// Custom mode specific fields
	slug: string
	name: string
	tags: string // Comma-separated string representation of tags array
	scope: scopeType
	selectedTools: string[]

	// Validation errors
	slugError: string
	nameError: string
	roleDefinitionError: string
}

/**
 * Return type for the useModeForm hook
 */
export interface UseModeFormReturn {
	// Form state
	formState: ModeFormState

	// Field update handlers
	setDescription: (value: string) => void
	setRoleDefinition: (value: string) => void
	setWhenToUse: (value: string) => void
	setCustomInstructions: (value: string) => void
	setSlug: (value: string) => void
	setName: (value: string) => void
	setTags: (value: string) => void
	setScope: (value: scopeType) => void
	setSelectedTools: (value: string[]) => void
	handleToolToggle: (tool: string, checked: boolean) => void

	// Validation
	slugError: string
	nameError: string
	roleDefinitionError: string
	setSlugError: (error: string) => void
	setNameError: (error: string) => void
	setRoleDefinitionError: (error: string) => void

	// Modification tracking (for built-in modes)
	isDescriptionModified: boolean
	isRoleDefinitionModified: boolean
	isWhenToUseModified: boolean
	isCustomInstructionsModified: boolean

	// Reset handlers (for built-in modes)
	handleResetDescription: () => void
	handleResetRoleDefinition: () => void
	handleResetWhenToUse: () => void
	handleResetCustomInstructions: () => void

	// Scope tracking
	originalScope: scopeType
	scopeChanged: boolean

	// Form operations
	resetForm: () => void
	getFormChanges: () => Partial<ModeItem>
	isFormValid: (allModes?: ModeItem[]) => boolean
}

/**
 * Custom hook to manage complex form state for mode editing.
 * Centralizes all form state management, validation, and modification tracking.
 *
 * @param initialMode - The mode to initialize the form with
 * @param t - Translation function for validation error messages
 * @returns Form state, handlers, and utility functions
 *
 * @example
 * ```tsx
 * const {
 *   formState,
 *   setDescription,
 *   isDescriptionModified,
 *   handleResetDescription,
 *   getFormChanges,
 *   isFormValid
 * } = useModeForm(mode, t)
 * ```
 */
export function useModeForm(initialMode: ModeItem, t: TranslateFunction): UseModeFormReturn {
	// Initialize form state from mode data
	const [description, setDescription] = useState(initialMode.data.description || "")
	const [roleDefinition, setRoleDefinition] = useState(initialMode.data.roleDefinition || "")
	const [whenToUse, setWhenToUse] = useState(initialMode.data.whenToUse || "")
	const [customInstructions, setCustomInstructions] = useState(initialMode.data.customInstructions || "")

	// Custom mode specific fields
	const [slug, setSlug] = useState(initialMode.data.slug || "")
	const [name, setName] = useState(initialMode.data.name || "")
	const [tags, setTags] = useState(() => {
		// Convert tags array to comma-separated string for input
		if (Array.isArray(initialMode.metaData?.tags)) {
			return initialMode.metaData.tags.join(", ")
		}
		return initialMode.metaData?.tags || ""
	})
	const [scope, setScope] = useState<scopeType>(initialMode.data.source || "global")
	const [selectedTools, setSelectedTools] = useState<string[]>(() => {
		return getToolGroups(initialMode)
	})

	// Validation errors
	const [slugError, setSlugError] = useState("")
	const [nameError, setNameError] = useState("")
	const [roleDefinitionError, setRoleDefinitionError] = useState("")

	// Track original scope to detect changes
	const originalScope = initialMode.data.source || "global"
	const scopeChanged = scope !== originalScope

	// ibm_change_start: Get default values from DEFAULT_MODES for built-in modes or originalValues for API-registered/marketplace modes
	const defaultMode = useMemo(() => {
		// For API-registered and marketplace modes, use originalValues if available
		if ((isMarketplaceMode(initialMode) || isApiRegisteredMode(initialMode)) && initialMode.originalValues) {
			return initialMode.originalValues
		}
		// For built-in modes, use DEFAULT_MODES
		return getDefaultModeConfig(initialMode.data.slug)
	}, [initialMode])

	// Check if field values differ from defaults (for built-in, API-registered, and marketplace modes)
	const isDescriptionModified = useMemo(() => {
		return description !== (defaultMode?.description || "")
	}, [description, defaultMode])

	const isRoleDefinitionModified = useMemo(() => {
		return roleDefinition !== (defaultMode?.roleDefinition || "")
	}, [roleDefinition, defaultMode])

	const isWhenToUseModified = useMemo(() => {
		return whenToUse !== (defaultMode?.whenToUse || "")
	}, [whenToUse, defaultMode])

	const isCustomInstructionsModified = useMemo(() => {
		return customInstructions !== (defaultMode?.customInstructions || "")
	}, [customInstructions, defaultMode])

	// Reset handlers for built-in, API-registered, and marketplace modes
	const handleResetDescription = useCallback(() => {
		setDescription(defaultMode?.description || "")
	}, [defaultMode])

	const handleResetRoleDefinition = useCallback(() => {
		setRoleDefinition(defaultMode?.roleDefinition || "")
	}, [defaultMode])

	const handleResetWhenToUse = useCallback(() => {
		setWhenToUse(defaultMode?.whenToUse || "")
	}, [defaultMode])

	const handleResetCustomInstructions = useCallback(() => {
		setCustomInstructions(defaultMode?.customInstructions || "")
	}, [defaultMode])
	// ibm_change_end

	// Tool toggle handler
	const handleToolToggle = useCallback((tool: string, checked: boolean) => {
		if (checked) {
			setSelectedTools((prev) => [...prev, tool])
		} else {
			setSelectedTools((prev) => prev.filter((t) => t !== tool))
		}
	}, [])

	/**
	 * Reset form to initial mode values
	 */
	const resetForm = useCallback(() => {
		setDescription(initialMode.data.description || "")
		setRoleDefinition(initialMode.data.roleDefinition || "")
		setWhenToUse(initialMode.data.whenToUse || "")
		setCustomInstructions(initialMode.data.customInstructions || "")
		setSlug(initialMode.data.slug || "")
		setName(initialMode.data.name || "")
		// Convert tags array to comma-separated string
		setTags(() => {
			if (Array.isArray(initialMode.metaData?.tags)) {
				return initialMode.metaData.tags.join(", ")
			}
			return initialMode.metaData?.tags || ""
		})
		setScope(initialMode.data.source || "global")
		setSelectedTools(getToolGroups(initialMode))
		setSlugError("")
		setNameError("")
		setRoleDefinitionError("")
	}, [initialMode])

	/**
	 * Get only the modified fields as a partial ModeItem.
	 * Creates an updated mode object with new values.
	 *
	 * @returns Partial ModeItem with updated values
	 */
	const getFormChanges = useCallback((): Partial<ModeItem> => {
		const updatedMode: ModeItem = {
			...initialMode,
			data: {
				...initialMode.data,
				description,
				roleDefinition,
				whenToUse,
				customInstructions,
				// Custom mode specific fields
				...(isCustomMode(initialMode) && {
					slug,
					name,
					groups: selectedTools.map((tool) => tool as any),
				}),
				...((isCustomMode(initialMode) || isMarketplaceMode(initialMode)) && {
					source: scope,
				}),
			},
			metaData: {
				...initialMode.metaData,
				// Custom mode specific metadata
				...(isCustomMode(initialMode) && {
					// Convert comma-separated tags string to array
					tags: tags.trim()
						? tags
								.split(",")
								.map((tag) => tag.trim())
								.filter((tag) => tag.length > 0)
						: [],
				}),
			},
		}
		return updatedMode
	}, [
		initialMode,
		description,
		roleDefinition,
		whenToUse,
		customInstructions,
		slug,
		name,
		scope,
		selectedTools,
		tags,
	])

	/**
	 * Validate the form and return whether it's valid.
	 * For custom modes, validates slug, name, and roleDefinition.
	 * For all modes, validates roleDefinition.
	 * Sets error states for invalid fields.
	 *
	 * @param allModes - Array of all modes for uniqueness validation
	 * @returns true if form is valid, false otherwise
	 */
	const isFormValid = useCallback(
		(allModes?: ModeItem[]): boolean => {
			let hasError = false

			// Validate for custom modes
			if (isCustomMode(initialMode)) {
				// Validate slug
				const existingSlugs = allModes?.map((m) => m.data.slug) || []
				const slugValidation = validateSlug(slug, existingSlugs, initialMode.data.slug, t)
				if (!slugValidation.isValid) {
					setSlugError(slugValidation.error || "")
					hasError = true
				} else {
					setSlugError("")
				}

				// Validate name
				const nameValidation = validateModeName(name, t)
				if (!nameValidation.isValid) {
					setNameError(nameValidation.error || "")
					hasError = true
				} else {
					setNameError("")
				}
			}

			// Validate roleDefinition for all modes
			const roleDefinitionValidation = validateRoleDefinition(roleDefinition, t)
			if (!roleDefinitionValidation.isValid) {
				setRoleDefinitionError(roleDefinitionValidation.error || "")
				hasError = true
			} else {
				setRoleDefinitionError("")
			}

			return !hasError
		},
		[initialMode, slug, name, roleDefinition, t]
	)

	// Reset form when mode changes
	useEffect(() => {
		resetForm()
	}, [resetForm])

	// Combine all state into formState object
	const formState: ModeFormState = {
		description,
		roleDefinition,
		whenToUse,
		customInstructions,
		slug,
		name,
		tags,
		scope,
		selectedTools,
		slugError,
		nameError,
		roleDefinitionError,
	}

	return {
		formState,
		setDescription,
		setRoleDefinition,
		setWhenToUse,
		setCustomInstructions,
		setSlug,
		setName,
		setTags,
		setScope,
		setSelectedTools,
		handleToolToggle,
		slugError,
		nameError,
		roleDefinitionError,
		setSlugError,
		setNameError,
		setRoleDefinitionError,
		isDescriptionModified,
		isRoleDefinitionModified,
		isWhenToUseModified,
		isCustomInstructionsModified,
		handleResetDescription,
		handleResetRoleDefinition,
		handleResetWhenToUse,
		handleResetCustomInstructions,
		originalScope,
		scopeChanged,
		resetForm,
		getFormChanges,
		isFormValid,
	}
}

