import { ModeItem } from "./hooks/useModes"
import { type ModeConfig } from "@roo-code/types"
import { TranslateFunction } from "./modeUtils"

/**
 * Regular expression pattern for validating mode slugs.
 * Allows only alphanumeric characters and hyphens.
 * Slugs must start and end with alphanumeric characters.
 */
const SLUG_PATTERN = /^[a-zA-Z0-9]+(-[a-zA-Z0-9]+)*$/

/**
 * Validation result interface for individual field validation
 */
export interface ValidationResult {
	isValid: boolean
	error?: string
}

/**
 * Comprehensive validation results for all mode configuration fields
 */
export interface ModeConfigValidationResult {
	isValid: boolean
	slugError?: string
	nameError?: string
	descriptionError?: string
	roleDefinitionError?: string
	whenToUseError?: string
	customInstructionsError?: string
}

/**
 * Validate a mode slug for format, required field, and uniqueness.
 * 
 * Validation rules:
 * - Must not be empty
 * - Must contain only alphanumeric characters and hyphens
 * - Must be unique among all modes (except when editing the current mode)
 * 
 * @param slug - The slug to validate
 * @param existingSlugs - Array of existing slugs to check uniqueness against
 * @param currentSlug - The current slug (when editing) to exclude from uniqueness check
 * @param t - Translation function for error messages
 * @returns ValidationResult with isValid flag and optional error message
 * 
 * @example
 * ```ts
 * const result = validateSlug("my-mode", ["code", "architect"], undefined, t)
 * if (!result.isValid) {
 *   console.error(result.error)
 * }
 * ```
 */
export function validateSlug(
	slug: string,
	existingSlugs: string[],
	currentSlug: string | undefined,
	t: TranslateFunction
): ValidationResult {
	// Check if slug is empty
	if (!slug.trim()) {
		return {
			isValid: false,
			error: t("ibmSettings:modes.edit_modal.slug_required"),
		}
	}

	// Check slug format (alphanumeric and hyphens only)
	if (!SLUG_PATTERN.test(slug)) {
		return {
			isValid: false,
			error: t("ibmSettings:modes.edit_modal.slug_invalid_format"),
		}
	}

	// Check uniqueness (exclude current slug when editing)
	const isDuplicate = existingSlugs.some((existingSlug) => existingSlug === slug && existingSlug !== currentSlug)
	if (isDuplicate) {
		return {
			isValid: false,
			error: t("ibmSettings:modes.edit_modal.slug_already_exists"),
		}
	}

	return { isValid: true }
}

/**
 * Validate a mode name for required field.
 *
 * Validation rules:
 * - Must not be empty
 *
 * @param name - The name to validate
 * @param t - Translation function for error messages
 * @returns ValidationResult with isValid flag and optional error message
 *
 * @example
 * ```ts
 * const result = validateModeName("My Custom Mode", t)
 * if (!result.isValid) {
 *   console.error(result.error)
 * }
 * ```
 */
export function validateModeName(name: string, t: TranslateFunction): ValidationResult {
	// Check if name is empty
	if (!name.trim()) {
		return {
			isValid: false,
			error: t("ibmSettings:modes.edit_modal.name_required"),
		}
	}

	return { isValid: true }
}

/**
 * Validate a role definition for required field.
 *
 * Validation rules:
 * - Must not be empty
 *
 * @param roleDefinition - The role definition to validate
 * @param t - Translation function for error messages
 * @returns ValidationResult with isValid flag and optional error message
 *
 * @example
 * ```ts
 * const result = validateRoleDefinition("You are a helpful assistant", t)
 * if (!result.isValid) {
 *   console.error(result.error)
 * }
 * ```
 */
export function validateRoleDefinition(roleDefinition: string, t: TranslateFunction): ValidationResult {
	// Check if role definition is empty
	if (!roleDefinition.trim()) {
		return {
			isValid: false,
			error: t("ibmSettings:modes.edit_modal.role_definition_required"),
		}
	}

	return { isValid: true }
}

/**
 * Perform comprehensive validation on a mode configuration.
 * Validates all required fields based on mode type (custom vs built-in).
 *
 * For custom modes, validates:
 * - slug (required, format, uniqueness)
 * - name (required)
 * - roleDefinition (required)
 *
 * For all modes, validates:
 * - roleDefinition (required)
 *
 * Optional validation can be added for:
 * - description
 * - whenToUse
 * - customInstructions
 *
 * @param config - Partial mode configuration to validate
 * @param allModes - Array of all existing modes for uniqueness checks
 * @param currentMode - The current mode being edited (optional, for edit vs create)
 * @param t - Translation function for error messages
 * @returns ModeConfigValidationResult with overall validity and field-specific errors
 *
 * @example
 * ```ts
 * const result = validateModeConfig(
 *   { slug: "my-mode", name: "My Mode", roleDefinition: "You are..." },
 *   allModes,
 *   currentMode,
 *   t
 * )
 * if (!result.isValid) {
 *   if (result.slugError) console.error(result.slugError)
 *   if (result.nameError) console.error(result.nameError)
 *   if (result.roleDefinitionError) console.error(result.roleDefinitionError)
 * }
 * ```
 */
export function validateModeConfig(
	config: Partial<ModeConfig>,
	allModes: ModeItem[],
	currentMode: ModeItem | undefined,
	t: TranslateFunction
): ModeConfigValidationResult {
	const result: ModeConfigValidationResult = {
		isValid: true,
	}

	// Only validate slug and name for custom modes
	const isCustomMode = currentMode?.type === "custom"

	if (isCustomMode) {
		// Validate slug - required for custom modes
		if (!config.slug) {
			result.isValid = false
			result.slugError = t("ibmSettings:modes.edit_modal.slug_required")
		} else {
			const existingSlugs = allModes.map((m) => m.data.slug)
			const currentSlug = currentMode?.data.slug
			const slugValidation = validateSlug(config.slug, existingSlugs, currentSlug, t)

			if (!slugValidation.isValid) {
				result.isValid = false
				result.slugError = slugValidation.error
			}
		}

		// Validate name - required for custom modes
		if (!config.name) {
			result.isValid = false
			result.nameError = t("ibmSettings:modes.edit_modal.name_required")
		} else {
			const nameValidation = validateModeName(config.name, t)

			if (!nameValidation.isValid) {
				result.isValid = false
				result.nameError = nameValidation.error
			}
		}
	}

	// Validate roleDefinition - required for all modes
	if (!config.roleDefinition) {
		result.isValid = false
		result.roleDefinitionError = t("ibmSettings:modes.edit_modal.role_definition_required")
	} else {
		const roleDefinitionValidation = validateRoleDefinition(config.roleDefinition, t)

		if (!roleDefinitionValidation.isValid) {
			result.isValid = false
			result.roleDefinitionError = roleDefinitionValidation.error
		}
	}

	// Additional field validations can be added here as needed
	// For example, max length checks, format validations, etc.

	return result
}

