import { IBM_BOB_CONFIG_KEY } from "@roo/IBM/bobSourcesConfig"

/**
 * Helper to extract nested value from an object using dot notation
 * Removes config prefix if present (e.g., "ibm-bob-config.findings" -> "findings")
 */
export function getNestedValue(obj: any, path: string): any {
	const configPrefix = `${IBM_BOB_CONFIG_KEY}.`
	const cleanPath = path.startsWith(configPrefix) ? path.substring(configPrefix.length) : path
	return cleanPath.split(".").reduce((current, key) => current?.[key], obj)
}
