import * as React from "react"
import { vscode } from "@/utils/vscode"
import { useWorkspaceState } from "@/ibm/hooks/useWorkspaceState/useWorkspaceState"
import { WorkspaceStateBinding } from "../BindingTypes"

interface WorkspaceStateWrapperProps<TComponentProps extends Record<string, any>> {
	/** The component to render */
	component: React.ComponentType<TComponentProps & { value: any; setValue: (value: any) => void }>
	/** Binding configuration */
	binding: WorkspaceStateBinding
	/** Component-specific props (excluding binding) */
	props?: TComponentProps
}

/**
 * Generic wrapper component that manages workspace state binding
 * Accepts binding and props as separate parameters to match JSON schema structure
 *
 * @example
 * <WorkspaceStateWrapper
 *   component={Dropdown}
 *   binding={{ type: "workspaceState", stateKey: "ibm-bob-config.llmAttributionMode", settingKey: "ibm-bob-config.llmAttributionMode" }}
 *   props={{ options: [...], label: "LLM Attribution" }}
 * />
 */
function WorkspaceStateWrapper<TComponentProps extends Record<string, any>>({
	component: Component,
	binding,
	props = {} as TComponentProps,
}: WorkspaceStateWrapperProps<TComponentProps>) {
	const stateValue = useWorkspaceState(binding.stateKey, binding.defaultValue)

	const setValue = React.useCallback(
		(value: any) => {
			// Use updateVSCodeSetting message which routes through handleBobSettingsWebview
			// to update the workspace state via BobWorkspaceState
			vscode.postMessage({
				type: "updateVSCodeSetting",
				setting: binding.settingKey,
				value: value,
			})
		},
		[binding.settingKey],
	)

	return <Component {...(props as any)} value={stateValue} setValue={setValue} />
}

export default WorkspaceStateWrapper

