import { useState } from "react"
import { MarketplaceItem, McpServerStatusMessage } from "@roo-code/types"
import { vscode } from "@/utils/vscode"
import { createMessageListener } from "@/ibm/utils/messageListener"
import { ValidationErrorState } from "./shared/ValidationError"

interface UseMarketplaceInstallOptions {
	item: MarketplaceItem | null
	isEditMode?: boolean
	currentTarget?: 'global' | 'project'
	onClose: () => void
}

interface InstallOptions {
	scope: 'project' | 'global'
	parameters?: Record<string, any>
}

export const useMarketplaceInstall = ({
	item,
	isEditMode = false,
	currentTarget,
	onClose,
}: UseMarketplaceInstallOptions) => {
	const [isInstalling, setIsInstalling] = useState(false)
	const [validationError, setValidationError] = useState<ValidationErrorState | null>(null)

	/**
	 * Sets up a listener to wait for MCP server connection status.
	 * Only applicable for MCP server installations.
	 *
	 * @param serverName - The name of the MCP server to wait for
	 * @param scope - The scope where the server was installed (global or project)
	 */
	const waitForMcpServerStatus = (serverName: string, scope: 'global' | 'project') => {
		// Only wait for MCP server status if this is an MCP item
		if (item?.type !== 'mcp') {
			// For non-MCP items, close immediately after installation
			setIsInstalling(false)
			onClose()
			return
		}

		// Set up listener for MCP server status
		// This listener will persist through multiple status updates (connecting -> connected)
		createMessageListener<{ mcpServerStatus: McpServerStatusMessage }>({
			messageType: "mcpServerStatus",
			matchCondition: (message) => {
				// Match by server name and source (global/project)
				const status = message.mcpServerStatus
				return status.serverName === serverName && status.source === scope
			},
			onSuccess: (message) => {
				// The actual status data is nested under mcpServerStatus
				const status = message.mcpServerStatus
				
				// Check the status
				if (status.status === "connected") {
					// Server connected successfully - close modal and cleanup listener
					setIsInstalling(false)
					onClose()
					return false // Cleanup listener
				} else if (status.status === "error" || status.status === "disconnected") {
					// Server failed to connect - show error with scope and server name
					setIsInstalling(false)
					const errorMsg = status.error || "MCP server failed to start"
					setValidationError({ message: errorMsg, scope, serverName })
					return false // Cleanup listener
				} else {
					// "connecting" status - keep waiting
					return true // Keep listener active
				}
			},
			onError: (error) => {
				// Timeout or other error - show error message with scope and server name
				setIsInstalling(false)
				setValidationError({
					message: error.message || "Timeout waiting for MCP server to start. The configuration has been added but the server did not respond.",
					scope,
					serverName
				})
			},
			timeout: 60000, // 60 seconds timeout for server startup
		})
	}

	const install = (options: InstallOptions) => {
		if (!item) return

		setValidationError(null)
		setIsInstalling(true)

		const { scope, parameters = {} } = options

		if (isEditMode) {
			// For edit mode, use sequential remove + install with MCP server status waiting
			createMessageListener({
				messageType: "marketplaceRemoveResult",
				matchCondition: (message) => message.slug === item.id,
				onSuccess: () => {
					// Removal succeeded - now install with new parameters
					createMessageListener({
						messageType: "marketplaceInstallResult",
						matchCondition: (message) => message.slug === item.id,
						onSuccess: () => {
							// Installation succeeded - request fresh data
							vscode.postMessage({
								type: "fetchMarketplaceData",
							})
							// Wait for MCP server status before closing
							waitForMcpServerStatus(item.id, scope)
						},
						onError: (error) => {
							// Installation failed - show error with scope and server name
							setIsInstalling(false)
							setValidationError({ message: error.message || "Installation failed", scope, serverName: item.id })
						},
						timeout: 30000,
					})
					
					// Send install message
					vscode.postMessage({
						type: "installMarketplaceItem",
						mpItem: item,
						mpInstallOptions: {
							target: scope,
							parameters,
						},
					})
				},
				onError: (error) => {
					// Removal failed - show error with scope and server name
					setIsInstalling(false)
					setValidationError({ message: error.message || "Failed to remove existing configuration", scope, serverName: item.id })
				},
				timeout: 30000,
			})
			
			// Send remove message to start the process
			vscode.postMessage({
				type: "removeInstalledMarketplaceItem",
				mpItem: item,
				mpInstallOptions: {
					target: currentTarget || "global",
				},
			})
		} else {
			// For new installation, listen for result then wait for MCP server status
			createMessageListener({
				messageType: "marketplaceInstallResult",
				matchCondition: (message) => message.slug === item.id,
				onSuccess: () => {
					// Installation succeeded - request fresh data
					vscode.postMessage({
						type: "fetchMarketplaceData",
					})
					// Wait for MCP server status before closing
					waitForMcpServerStatus(item.id, scope)
				},
				onError: (error) => {
					// Installation failed - show error with scope and server name
					setIsInstalling(false)
					setValidationError({ message: error.message || "Installation failed", scope, serverName: item.id })
				},
				timeout: 30000,
			})
			
			// Send install message
			vscode.postMessage({
				type: "installMarketplaceItem",
				mpItem: item,
				mpInstallOptions: {
					target: scope,
					parameters,
				},
			})
		}
	}

	return {
		isInstalling,
		validationError,
		setValidationError,
		install,
	}
}

