import * as React from "react"
import { useVSCodeSetting } from "@/ibm/hooks/useVsCodeSetting/useVSCodeSetting"
import { VSCodeSettingBinding } from "../BindingTypes"

interface VSCodeSettingWrapperProps<TComponentProps extends Record<string, any>> {
	/** The component to render */
	component: React.ComponentType<TComponentProps & { value: any; setValue: (value: any) => void }>
	/** Binding configuration */
	binding: VSCodeSettingBinding
	/** Component-specific props (excluding binding) */
	props?: TComponentProps
}

/**
 * Generic wrapper component that manages VSCode setting binding
 * Accepts binding and props as separate parameters to match JSON schema structure
 *
 * @example
 * <VSCodeSettingWrapper
 *   component={Toggle}
 *   binding={{ type: "vscodeSetting", settingKey: "...", defaultValue: true }}
 *   props={{ noContainer: true, icon: <Icon /> }}
 * />
 */
function VSCodeSettingWrapper<TComponentProps extends Record<string, any>>({
	component: Component,
	binding,
	props = {} as TComponentProps,
}: VSCodeSettingWrapperProps<TComponentProps>) {
	const [value, setValue] = useVSCodeSetting(binding.settingKey, binding.defaultValue)

	return <Component {...(props as any)} value={value} setValue={setValue} />
}

export default VSCodeSettingWrapper

