import { useMemo } from "react"
import { useExtensionState } from "@/context/ExtensionStateContext"

/**
 * Custom hook to check if marketplace features are enabled via feature flag
 * @returns boolean indicating if marketplace is enabled (defaults to false)
 */
export const useMarketplaceEnabled = (): boolean => {
	const { featureFlags } = useExtensionState()
	
	const isMarketplaceEnabled = useMemo(() => {
		return featureFlags?.["marketplace-enabled"] ?? false
	}, [featureFlags])
	
	return isMarketplaceEnabled
}