import React, { useMemo } from "react"
import { formatRelative } from "date-fns"
import type { McpErrorEntry } from "@roo/mcp"
import { useTranslation } from "react-i18next"
import SectionRow from "../../../components/SectionRow"

type McpErrorSettingRowProps = {
	error: McpErrorEntry
}

export const McpErrorSettingRow: React.FC<McpErrorSettingRowProps> = ({ error }) => {
	const { t } = useTranslation("ibmSettings")

	const color = useMemo(() => {
		switch (error.level) {
			case "error":
				return "var(--vscode-errorForeground)"
			case "warn":
				return "var(--vscode-charts-yellow)"
			case "info":
				return "var(--vscode-testing-iconPassed)"
		}
	}, [error.level])

	// Get translated error level
	const errorLevelTranslation = useMemo(() => {
		return t(`mcp.details.error_levels.${error.level}`)
	}, [error.level, t])

	const timestamp = formatRelative(error.timestamp, new Date())

	// Create detailed error description with original message and stringified error
	const errorDescription = useMemo(() => {
		// If error.message is already a string, use it directly
		// Otherwise, stringify the entire error object for debugging
		const originalMessage = error.message
		const stringifiedError = JSON.stringify(error, null, 2)
		
		// If they're different, show both; otherwise just show the message
		if (originalMessage !== stringifiedError) {
			return `${originalMessage}\n\nFull error details:\n${stringifiedError}`
		}
		return originalMessage
	}, [error])

	// Create title with error icon
	const titleWithIcon = (
		<div className="flex items-center gap-2">
			<span className="codicon codicon-error" style={{ color }} />
			<span>{`${errorLevelTranslation}: ${timestamp}`}</span>
		</div>
	)

	return <SectionRow title={titleWithIcon as any} description={errorDescription} />
}

export default McpErrorSettingRow