import React from "react"
import { useAppTranslation } from "@/i18n/TranslationContext"
import { vscode } from "@/utils/vscode"
import { Button } from "@/components/ui"

export interface ValidationErrorState {
	message: string
	scope?: 'global' | 'project'
	serverName?: string // ibm_change: Server name to navigate to in config file
}

interface ValidationErrorProps {
	error: ValidationErrorState | string | null
}

/**
 * ValidationError Component
 *
 * Shared component for displaying validation errors in modals.
 * ibm_change: Now supports displaying a structured error box with config file link
 */
export const ValidationError: React.FC<ValidationErrorProps> = ({ error }) => {
	const { t } = useAppTranslation()
	
	if (!error) return null

	// Handle both old string format and new object format
	const errorMessage = typeof error === 'string' ? error : error.message
	const errorScope = typeof error === 'object' ? error.scope : undefined
	const serverName = typeof error === 'object' ? error.serverName : undefined

	// ibm_change: Pass serverName to open config at the correct location
	const handleOpenConfig = () => {
		if (errorScope === 'global') {
			vscode.postMessage({ type: "openMcpSettings", serverName })
		} else if (errorScope === 'project') {
			vscode.postMessage({ type: "openProjectMcpSettings", serverName })
		}
	}

	// For MCP errors with scope, show structured error box
	if (errorScope) {
		return (
			<div className="w-full rounded-md bg-vscode-sideBar-background border border-vscode-inputValidation-errorBorder mt-2">
				{/* Header with icon */}
				<div className="border-b border-vscode-editor-background p-2">
					<div className="flex items-center gap-2 text-sm font-medium mb-1">
						<span
							className="codicon codicon-error"
							style={{ color: "var(--vscode-errorForeground)" }}
						/>
						<span>{t("marketplace:install.errorTitle")}</span>
					</div>
					<div className="text-vscode-descriptionForeground text-sm">
						{t("marketplace:install.errorConfigAdded")}
					</div>
				</div>
				
				{/* Error Details Section */}
				<div className="p-2 border-b border-vscode-editor-background">
					<div className="text-xs font-medium text-vscode-descriptionForeground mb-1">
						{t("marketplace:install.errorDetails")}
					</div>
					<div className="text-sm bg-vscode-inputValidation-errorBackground rounded">
						{errorMessage}
					</div>
				</div>
				
				{/* Button Section */}
				<div className="p-2">
					<Button
						onClick={handleOpenConfig}
						variant="secondary"
						className="w-full"
					>
						{t("marketplace:install.openConfigFile")}
					</Button>
				</div>
			</div>
		)
	}

	// For simple validation errors (no scope), show simple error box
	return (
		<div className="text-sm text-red-500 bg-red-500/10 border border-red-500/20 rounded p-2 mt-2">
			{errorMessage}
		</div>
	)
}

