// Define the navigation tab types
export type SettingsTabId = "general" | "chat" | "editor" | "bobFindings" | "mcp" | "modes" | "rules" | "commands"

/**
 * Base properties shared by all settings navigation items
 */
interface SettingsNavigationItemBase {
	id: SettingsTabId
	icon: LucideIcon | CarbonIconType
	labelTranslationKey: string
	/** Flag to control visibility of the navigation item. Defaults to true if not specified. */
	visible?: boolean
}

/**
 * Navigation item with JSON-based tab definition for programmatic rendering.
 *
 * **Use this approach when:**
 * - Settings are simple and declarative (toggles, inputs, dropdowns)
 * - Content can be easily represented in JSON format
 * - You want to leverage the built-in TabRenderer and SectionRenderer
 * - Settings benefit from programmatic generation or configuration
 *
 * **Example:**
 * ```typescript
 * {
 *   id: "general",
 *   icon: Settings,
 *   labelTranslationKey: "ibmSettings:sidebar.navigation.general",
 *   tabDefinition: generalTabDefinitionJson as unknown as SettingsTabDefinition,
 * }
 * ```
 *
 * The tab content is defined declaratively in JSON and rendered through TabRenderer.
 * See `GeneralTabDefinition.json` for a complete example.
 */
interface SettingsNavigationItemWithDefinition extends SettingsNavigationItemBase {
	/** JSON-based tab definition for programmatic rendering */
	tabDefinition: SettingsTabDefinition
	component?: never
}

/**
 * Navigation item with direct React component reference.
 *
 * **Use this approach when:**
 * - Tab requires complex UI with custom interactions
 * - Component needs sophisticated state management
 * - JSON definition would be overly complex or limiting
 * - You need full control over rendering and behavior
 *
 * **Example:**
 * ```typescript
 * {
 *   id: "modes",
 *   icon: UserRole,
 *   labelTranslationKey: "ibmSettings:sidebar.navigation.modes",
 *   component: ModesTab,
 *   visible: true,
 * }
 * ```
 *
 * The tab content is rendered directly without JSON definition processing.
 * The component receives full access to ExtensionState context and all React hooks.
 * See `ModesTab.tsx` for a complete example.
 */

/**
 * Search metadata for component-based tabs that don't use JSON definitions.
 * This allows the search index to include these tabs in search results.
 */
export interface ComponentTabSearchMetadata {
	sections: Array<{
		titleKey?: string
		descriptionKey?: string
		rows?: Array<{
			titleKey: string
			descriptionKey?: string
		}>
	}>
}

interface SettingsNavigationItemWithComponent extends SettingsNavigationItemBase {
	/** Direct React component reference for rendering tab content */
	component: React.ComponentType
	tabDefinition?: never
	/** Search metadata for indexing component-based tabs */
	searchMetadata?: ComponentTabSearchMetadata
}

/**
 * Settings navigation item supporting two rendering approaches:
 *
 * 1. **JSON-based definition (tabDefinition)** - For declarative, simple settings
 *    - Rendered through TabRenderer → SectionRenderer
 *    - Supports built-in components (toggle, input, dropdown, etc.)
 *    - Can reference custom components via CustomComponentsRegistry
 *    - Best for straightforward settings pages
 *
 * 2. **Direct component reference (component)** - For complex, interactive UIs
 *    - Rendered directly as a React component
 *    - Full access to hooks, state management, and context
 *    - Complete control over rendering and behavior
 *    - Best for sophisticated features like mode management
 *
 * **Important:** The `tabDefinition` and `component` fields are mutually exclusive.
 * TypeScript enforces that exactly one must be provided via discriminated union types.
 *
 * **Both approaches support:**
 * - Conditional rendering via `visible` flag
 * - Access to ExtensionState context
 * - Translation system integration
 * - Consistent styling and layout
 *
 * @see SettingsNavigationItemWithDefinition for JSON-based approach details
 * @see SettingsNavigationItemWithComponent for direct component approach details
 * @see SettingsContent.tsx for the rendering logic that handles both approaches
 */
export type SettingsNavigationItem = SettingsNavigationItemWithDefinition | SettingsNavigationItemWithComponent

