// Populate the byId map
settingsNavigation.items.forEach((item) => {
	settingsNavigation.byId[item.id] = item
})

interface SettingsPageProps {
	onDone?: () => void
	initialTab?: SettingsTabId
}

// Import search functionality
import { SettingsSearchProvider } from "./context/SettingsSearchContext"
import { useSettingsKeyboard } from "./hooks/useSettingsKeyboard"

/**
 * Inner component that uses search context (must be inside SettingsSearchProvider)
 */
const SettingsPageContent: React.FC<SettingsPageProps> = ({ onDone, initialTab }) => {
	// State for active tab
	const [activeTab, setActiveTab] = useState<SettingsTabId>(initialTab || "general")

	// Enable keyboard shortcuts
	useSettingsKeyboard()

	useEffect(() => {
		if (initialTab) {
			setActiveTab(initialTab)
		}
	}, [initialTab])

	// Handle tab change - search persists when navigating between tabs
	const handleTabChange = (tabId: SettingsTabId) => {
		setActiveTab(tabId)
	}

	return (
		<div className="flex flex-col h-full p-6 pr-0 pb-2 overflow-hidden max-h-screen items-center">
			<div className="flex flex-col w-full max-w-[870px] [@media(min-width:1000px)]:max-w-[1000px] h-full min-h-0">
				{/* Search bar spans full width above sidebar + content */}
				<SettingsHeader onDone={onDone} />
				<div className="flex flex-1 overflow-hidden min-h-0">
					<SettingsSidebar activeTab={activeTab} onTabChange={handleTabChange} />
					<SettingsContent activeTab={activeTab} />
				</div>
			</div>
		</div>
	)
}

/**
 * Main SettingsPage component wrapped with search provider
 */
const SettingsPage: React.FC<SettingsPageProps> = (props) => {
	return (
		<SettingsSearchProvider>
			<SettingsPageContent {...props} />
		</SettingsSearchProvider>
	)
}

export default SettingsPage

