import { ReactNode } from "react"

/**
 * ItemOverview Component
 *
 * A container component that composes OverviewHeader and OverviewSection components
 * to create complete detail views. Provides consistent layout with header at top
 * and scrollable content sections below.
 *
 * @example
 * ```tsx
 * <ItemOverview
 *   header={
 *     <OverviewHeader
 *       title="My Mode"
 *       onBack={() => navigate('back')}
 *       actions={<Button>Edit</Button>}
 *     />
 *   }
 * >
 *   <OverviewSection label="Description">
 *     This is the description
 *   </OverviewSection>
 *   <OverviewSection label="Tags">
 *     <div className="flex gap-2">
 *       <VSCodeBadge>tag1</VSCodeBadge>
 *     </div>
 *   </OverviewSection>
 * </ItemOverview>
 * ```
 */

interface ItemOverviewProps {
	/** OverviewHeader component (required) */
	header: ReactNode
	/** OverviewSection components (required) */
	children: ReactNode
	/** Additional CSS classes */
	className?: string
}

export function ItemOverview({ header, children, className = "" }: ItemOverviewProps) {
	return (
		<div className={`flex flex-col gap-1 ${className}`}>
			{/* Header area */}
			{header}

			{/* Content area with sections */}
			{children}
		</div>
	)
}

