import * as React from "react"
import { BrowserSettings } from "@/components/settings/BrowserSettings"
import { MaxLimitInputs } from "@/components/settings/MaxLimitInputs"
import { useExtensionState } from "@/context/ExtensionStateContext"
import { vscode } from "@/utils/vscode"
import CommandsSection from "../../tabs/chat/CommandsSection"
import ToolsHeaderDescription from "../../tabs/chat/ToolsHeaderDescription"
import AccountBudgetSection from "../../tabs/general/AccountBudgetSection"
import { BaseActionComponentProps } from "./BaseActionComponentProps"
import ReviewExclusionsManager from "../../tabs/review/ReviewExclusionsManager" // ibm_change

/**
 * Type for custom component props
 */
export interface CustomComponentProps {
	[key: string]: any
}

/**
 * Type for custom component definition in settings
 */
export interface CustomComponentDefinition extends BaseActionComponentProps {
	/**
	 * Name of the custom component in the registry
	 */
	componentName: string
	/**
	 * Additional props to pass to the custom component
	 */
	additionalProps?: Record<string, any>
}

/**
 * Type for custom component render function
 */
export type CustomComponentRenderer = (props: CustomComponentProps) => React.ReactNode

/**
 * Registry of custom components that can't be represented as pure JSON
 */
export class CustomComponentsRegistry {
	private static registry: Record<string, CustomComponentRenderer> = {}

	/**
	 * Register a custom component
	 * @param name The name of the component
	 * @param renderer The component renderer function
	 */
	public static register(name: string, renderer: CustomComponentRenderer): void {
		CustomComponentsRegistry.registry[name] = renderer
	}

	/**
	 * Get a custom component by name
	 * @param name The name of the component
	 * @returns The component renderer function or undefined if not found
	 */
	public static get(name: string): CustomComponentRenderer | undefined {
		return CustomComponentsRegistry.registry[name]
	}

	/**
	 * Check if a component exists in the registry
	 * @param name The name of the component
	 * @returns True if the component exists, false otherwise
	 */
	public static has(name: string): boolean {
		return !!CustomComponentsRegistry.registry[name]
	}

	/**
	 * Render a custom component
	 * @param name The name of the component
	 * @param props The props to pass to the component
	 * @returns The rendered component or null if not found
	 */
	public static render(name: string, props: CustomComponentProps): React.ReactNode {
		const renderer = CustomComponentsRegistry.get(name)
		if (!renderer) {
			console.warn(`Custom component "${name}" not found in registry`)
			return null
		}
		return renderer(props)
	}
}

// Register built-in custom components
CustomComponentsRegistry.register("BrowserSettings", () => {
	const { browserToolEnabled, browserViewportSize, screenshotQuality, remoteBrowserHost, remoteBrowserEnabled } =
		useExtensionState()

	return (
		<BrowserSettings
			browserToolEnabled={browserToolEnabled}
			browserViewportSize={browserViewportSize}
			screenshotQuality={screenshotQuality}
			remoteBrowserHost={remoteBrowserHost}
			remoteBrowserEnabled={remoteBrowserEnabled}
			setCachedStateField={(field, value) => {
				// Send updateSettings message to persist changes
				vscode.postMessage({
					type: "updateSettings",
					updatedSettings: {
						[field]: value,
					},
				})
			}}
		/>
	)
})

CustomComponentsRegistry.register("MaxLimitInputs", () => {
	const { allowedMaxRequests, allowedMaxCost, setAllowedMaxRequests, setAllowedMaxCost } = useExtensionState()

	return (
		<MaxLimitInputs
			allowedMaxRequests={allowedMaxRequests || undefined}
			allowedMaxCost={allowedMaxCost || undefined}
			onMaxRequestsChange={(value) => {
				setAllowedMaxRequests(value)
				vscode.postMessage({
					type: "updateSettings",
					updatedSettings: {
						allowedMaxRequests: value ?? null,
					},
				})
			}}
			onMaxCostChange={(value) => {
				setAllowedMaxCost(value)
				vscode.postMessage({
					type: "updateSettings",
					updatedSettings: {
						allowedMaxCost: value ?? null,
					},
				})
			}}
		/>
	)
})

CustomComponentsRegistry.register("CommandsSection", () => <CommandsSection />)

CustomComponentsRegistry.register("ToolsHeaderDescription", () => <ToolsHeaderDescription />)

CustomComponentsRegistry.register("AccountBudgetSection", () => <AccountBudgetSection />)

CustomComponentsRegistry.register("ReviewExclusionsManager", () => <ReviewExclusionsManager />)

/**
 * Custom component wrapper for use in settings definitions
 */
export const CustomComponent: React.FC<{
	name: string
	props?: CustomComponentProps
}> = ({ name, props = {} }) => {
	return <>{CustomComponentsRegistry.render(name, props)}</>
}

export default CustomComponent

