import React, { useState } from "react"
import { X } from "lucide-react"
import { useAppTranslation } from "@/i18n/TranslationContext"
import { Button, Input } from "@/components/ui"
import { useVSCodeSetting } from "@/ibm/hooks/useVsCodeSetting/useVSCodeSetting"
import { IBM_BOB_CONFIG_REVIEW_EXCLUSIONS } from "@roo/IBM/bobSourcesConfig"

interface ReviewExclusionsManagerProps {
	className?: string
}

const ReviewExclusionsManager: React.FC<ReviewExclusionsManagerProps> = ({ className }) => {
	const { t } = useAppTranslation()
	const [exclusions, setExclusions] = useVSCodeSetting<string[]>(IBM_BOB_CONFIG_REVIEW_EXCLUSIONS, [".vscode/**", ".bobignore"]) // ibm_change: add .bobignore to the review exclusions
	const [exclusionInput, setExclusionInput] = useState("")

	const handleAddExclusion = () => {
		if (exclusionInput && !exclusions.includes(exclusionInput)) {
			const newExclusions = [...exclusions, exclusionInput]
			setExclusions(newExclusions)
			setExclusionInput("")
		}
	}

	const handleRemoveExclusion = (index: number) => {
		const newExclusions = exclusions.filter((_, i) => i !== index)
		setExclusions(newExclusions)
	}

	return (
		<div className={`p-2 ${className}`}>
			<div className="flex gap-2 mb-2">
				<Input
					value={exclusionInput}
					onChange={(e: any) => setExclusionInput(e.target.value)}
					onKeyDown={(e: any) => {
						if (e.key === "Enter") {
							e.preventDefault()
							handleAddExclusion()
						}
					}}
					placeholder={t("ibmSettings:bobFindings.reviewExclusions.placeholder")}
					className="grow"
					data-testid="exclusion-input"
				/>
				<Button variant="outline" onClick={handleAddExclusion} data-testid="add-exclusion-button">
					{t("ibmSettings:bobFindings.reviewExclusions.addButton")}
				</Button>
			</div>

			{exclusions.length === 0 ? (
				<div className="text-vscode-descriptionForeground text-sm italic">
					{t("ibmSettings:bobFindings.reviewExclusions.empty")}
				</div>
			) : (
				<div className="flex flex-col gap-1">
					{exclusions.map((exclusion, index) => (
						<div
							key={index}
							data-testid={`exclusion-row-${index}`}
							className="grow pl-2 justify-between bg-vscode-input-background border border-vscode-input-border rounded flex items-center">
							<span className="text-vscode-foreground font-mono text-sm">{exclusion}</span>
							<Button
								variant="ghost"
								size="icon"
								data-testid={`remove-exclusion-${index}`}
								onClick={() => handleRemoveExclusion(index)}>
								<X className="w-4 h-4" />
							</Button>
						</div>
					))}
				</div>
			)}
		</div>
	)
}

export default ReviewExclusionsManager
