import React, { useState } from "react"
import { Trans, useTranslation } from "react-i18next"
import { VSCodeLink } from "@vscode/webview-ui-toolkit/react"
import { useBuildDocLink } from "@/utils/docLinks"
import { McpOverviewGrid } from "./McpOverviewGrid"
import { McpServerDetailsView } from "./McpServerDetailsView"
import { McpServerItem } from "./types"
import SectionRow from "../../components/SectionRow"
import { vscode } from "@/utils/vscode"
import { Button, StandardTooltip } from "@/components/ui"
import Section from "../../components/Section"
import { useExtensionState } from "@/context/ExtensionStateContext"
import ToggleButton from "@/ibm/components/common/toggleButton/ToggleButton"
import { useSettingsSearch } from "../../context/SettingsSearchContext"
import { HighlightedText } from "../../components/HighlightedText"

/**
 * Main MCP settings tab component
 * Displays MCP server configuration and management interface
 * Manages navigation between overview and details views
 */
export const McpTab: React.FC = () => {
	const buildDocLink = useBuildDocLink()
	const { t } = useTranslation()
	const { mcpEnabled, setMcpEnabled, enableMcpServerCreation, setEnableMcpServerCreation } = useExtensionState()
	const { isSearchActive, getHighlightInfoByTitleKey } = useSettingsSearch()
	// ibm_change_start: Store server identifier (name for custom, marketplace ID for marketplace servers)
	// This ensures the selection persists through installation when the server name might change
	const [selectedServerId, setSelectedServerId] = useState<string | null>(null)
	// ibm_change_end

	// Search highlighting helpers
	const dimClass = "opacity-30 pointer-events-none transition-opacity duration-200"
	const normalClass = "transition-opacity duration-200"

	const getRowProps = (titleKey: string, descriptionKey: string) => {
		const highlightInfo = getHighlightInfoByTitleKey(titleKey)
		const title = t(titleKey)
		const description = t(descriptionKey)
		const isDimmed = isSearchActive && !highlightInfo.isMatch

		return {
			title: highlightInfo.isMatch ? (
				<HighlightedText text={title} positions={highlightInfo.titlePositions} />
			) : (
				title
			),
			description:
				highlightInfo.isMatch && highlightInfo.descriptionPositions.length > 0 ? (
					<HighlightedText text={description} positions={highlightInfo.descriptionPositions} />
				) : (
					description
				),
			className: isDimmed ? dimClass : normalClass,
		}
	}

	const handleServerSelect = (server: McpServerItem) => {
		// For marketplace servers, use the marketplace item ID as the identifier
		// For custom servers, use the server name
		const serverId = server.type === "marketplace" && server.metaData?.id ? server.metaData.id : server.data.name
		setSelectedServerId(serverId)
	}

	const handleBackToOverview = () => {
		setSelectedServerId(null)
	}

	const handleOpenGlobalSettings = () => {
		vscode.postMessage({
			type: "openMcpSettings",
		})
	}

	const handleOpenProjectSettings = () => {
		vscode.postMessage({
			type: "openProjectMcpSettings",
		})
	}

	// Show details view if a server is selected, otherwise show overview grid
	return (
		<div className="flex flex-col gap-1">
			{/* Header Section - Only show in overview */}
			{!selectedServerId && (
				<>
					<div className="flex flex-col gap-2 pl-2">
						<div className="text-sm text-vscode-descriptionForeground">
							<Trans i18nKey="ibmSettings:mcp.description">
								<VSCodeLink
									href={buildDocLink("configuration/mcp/understanding-mcp")}
									className="text-sm"
									aria-label="Learn about MCP (Model Context Protocol)"></VSCodeLink>
							</Trans>
						</div>
					</div>
					<Section className="mb-2">
						<SectionRow
							{...getRowProps(
								"ibmSettings:mcp.use_mcp_servers_section.title",
								"ibmSettings:mcp.use_mcp_servers_section.description",
							)}
							actionComponent={
								<ToggleButton
									checked={mcpEnabled}
									onChange={(checked) => {
										setMcpEnabled(checked)
										vscode.postMessage({
											type: "updateSettings",
											updatedSettings: { mcpEnabled: checked },
										})
									}}
									noContainer
								/>
							}
						/>
						<SectionRow
							{...getRowProps(
								"ibmSettings:mcp.enable_server_creation_section.title",
								"ibmSettings:mcp.enable_server_creation_section.description",
							)}
							actionComponent={
								<ToggleButton
									checked={enableMcpServerCreation}
									onChange={(checked) => {
										setEnableMcpServerCreation(checked)
										vscode.postMessage({ type: "enableMcpServerCreation", bool: checked })
									}}
									noContainer
								/>
							}
						/>
						<SectionRow
							{...getRowProps(
								"ibmSettings:mcp.global_mcps_section.title",
								"ibmSettings:mcp.global_mcps_section.description",
							)}
							actionComponent={
								<StandardTooltip content={t("ibmSettings:mcp.global_mcps_section.open_button_tooltip")}>
									<Button variant="secondary" size="sm" onClick={handleOpenGlobalSettings}>
										{t("ibmSettings:mcp.global_mcps_section.open_button")}
									</Button>
								</StandardTooltip>
							}
						/>
						<SectionRow
							{...getRowProps(
								"ibmSettings:mcp.project_mcps_section.title",
								"ibmSettings:mcp.project_mcps_section.description",
							)}
							actionComponent={
								<StandardTooltip
									content={t("ibmSettings:mcp.project_mcps_section.open_button_tooltip")}>
									<Button variant="secondary" size="sm" onClick={handleOpenProjectSettings}>
										{t("ibmSettings:mcp.project_mcps_section.open_button")}
									</Button>
								</StandardTooltip>
							}
						/>
					</Section>
				</>
			)}

			{/* Content - Switch between overview and details */}
			{selectedServerId ? (
				<McpServerDetailsView serverId={selectedServerId} onBack={handleBackToOverview} />
			) : (
				<McpOverviewGrid onServerSelect={handleServerSelect} />
			)}
		</div>
	)
}
