import React, { createContext, useContext, useState, useCallback, useMemo, useRef } from "react"
import { useSettingsIndex, SettingsSearchResult, createEmptyTabCounts } from "../hooks/useSettingsIndex"
import { SettingsTabId } from "../SettingsPage"

/**
 * Highlight info for a setting row, used by component-based tabs
 */
export interface SettingHighlightInfo {
	/** Whether this setting matches the current search */
	isMatch: boolean
	/** Character positions to highlight in the title */
	titlePositions: number[]
	/** Character positions to highlight in the description */
	descriptionPositions: number[]
}

/**
 * Context value for settings search functionality
 */
interface SettingsSearchContextValue {
	/** Current search query */
	searchQuery: string
	/** Set the search query */
	setSearchQuery: (query: string) => void
	/** Whether search is currently active (query is non-empty) */
	isSearchActive: boolean
	/** Search results with match positions */
	searchResults: SettingsSearchResult[]
	/** Get highlight positions for a specific setting's title */
	getTitleHighlightPositions: (settingId: string) => number[]
	/** Get highlight positions for a specific setting's description */
	getDescriptionHighlightPositions: (settingId: string) => number[]
	/** Get highlight info for a setting by its translation key (for component-based tabs) */
	getHighlightInfoByTitleKey: (titleKey: string) => SettingHighlightInfo
	/** Clear the search and reset to normal view */
	clearSearch: () => void
	/** Match counts per tab for sidebar badges */
	matchCountsByTab: Record<SettingsTabId, number>
	/** Total number of search results */
	totalResults: number
	/** Reference to the search input for focus management */
	searchInputRef: React.RefObject<HTMLInputElement>
	/** Focus the search input */
	focusSearchInput: () => void
}

const SettingsSearchContext = createContext<SettingsSearchContextValue | null>(null)

/**
 * Builds lookup maps from search results for efficient highlight position retrieval.
 */
function buildHighlightMaps(results: SettingsSearchResult[]) {
	const titleMap = new Map<string, number[]>()
	const descriptionMap = new Map<string, number[]>()
	const titleKeyMap = new Map<string, SettingHighlightInfo>()

	for (const result of results) {
		titleMap.set(result.item.id, result.titlePositions)
		descriptionMap.set(result.item.id, result.descriptionPositions)

		// Also index by titleKey for component-based tabs
		if (result.item.titleKey) {
			titleKeyMap.set(result.item.titleKey, {
				isMatch: true,
				titlePositions: result.titlePositions,
				descriptionPositions: result.descriptionPositions,
			})
		}
	}

	return { titleMap, descriptionMap, titleKeyMap }
}

/** Default highlight info for settings that don't match the search */
const defaultHighlightInfo: SettingHighlightInfo = { isMatch: false, titlePositions: [], descriptionPositions: [] }

/**
 * Provider component for settings search functionality
 */
export const SettingsSearchProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
	const [searchQuery, setSearchQuery] = useState("")
	const searchInputRef = useRef<HTMLInputElement>(null)
	const { search, getMatchCountsByTab } = useSettingsIndex()

	const trimmedQuery = searchQuery.trim()
	const isSearchActive = trimmedQuery.length > 0

	const searchResults = useMemo(() => {
		return isSearchActive ? search(searchQuery) : []
	}, [search, searchQuery, isSearchActive])

	const matchCountsByTab = useMemo(() => {
		return isSearchActive ? getMatchCountsByTab(searchQuery) : createEmptyTabCounts()
	}, [getMatchCountsByTab, searchQuery, isSearchActive])

	const highlightMaps = useMemo(() => buildHighlightMaps(searchResults), [searchResults])

	const getTitleHighlightPositions = useCallback(
		(settingId: string) => highlightMaps.titleMap.get(settingId) ?? [],
		[highlightMaps],
	)

	const getDescriptionHighlightPositions = useCallback(
		(settingId: string) => highlightMaps.descriptionMap.get(settingId) ?? [],
		[highlightMaps],
	)

	const getHighlightInfoByTitleKey = useCallback(
		(titleKey: string): SettingHighlightInfo => highlightMaps.titleKeyMap.get(titleKey) ?? defaultHighlightInfo,
		[highlightMaps],
	)

	const clearSearch = useCallback(() => setSearchQuery(""), [])

	const focusSearchInput = useCallback(() => searchInputRef.current?.focus(), [])

	const value = useMemo<SettingsSearchContextValue>(
		() => ({
			searchQuery,
			setSearchQuery,
			isSearchActive,
			searchResults,
			getTitleHighlightPositions,
			getDescriptionHighlightPositions,
			getHighlightInfoByTitleKey,
			clearSearch,
			matchCountsByTab,
			totalResults: searchResults.length,
			searchInputRef,
			focusSearchInput,
		}),
		[
			searchQuery,
			isSearchActive,
			searchResults,
			getTitleHighlightPositions,
			getDescriptionHighlightPositions,
			getHighlightInfoByTitleKey,
			clearSearch,
			matchCountsByTab,
			focusSearchInput,
		],
	)

	return <SettingsSearchContext.Provider value={value}>{children}</SettingsSearchContext.Provider>
}

/**
 * Hook to access settings search context
 * @throws Error if used outside of SettingsSearchProvider
 */
export function useSettingsSearch(): SettingsSearchContextValue {
	const context = useContext(SettingsSearchContext)
	if (!context) {
		throw new Error("useSettingsSearch must be used within a SettingsSearchProvider")
	}
	return context
}

