import { ModeItem } from "../hooks/useModes"

/**
 * Configuration for a single badge display
 */
export interface BadgeConfig {
	text: string
	className: string
}

/**
 * Complete badge configuration for a mode
 */
export interface ModeBadges {
	typeBadge: BadgeConfig | null
	scopeBadge: BadgeConfig | null
	statusText: string | undefined
}

/**
 * Translation function type for i18n support
 */
type TranslateFunction = (key: string) => string

/**
 * Get all badge configurations for a mode item.
 * Centralizes badge logic for consistent display across components.
 * 
 * @param modeItem - The mode item to generate badges for
 * @param t - Translation function for i18n
 * @param isMarketplaceEnabled - Whether marketplace feature is enabled
 * @returns Complete badge configuration including type badge, scope badge, and status text
 * 
 * @example
 * ```typescript
 * const { typeBadge, scopeBadge, statusText } = getModeBadges(
 *   modeItem,
 *   t,
 *   isMarketplaceEnabled
 * )
 * ```
 */
export function getModeBadges(
	modeItem: ModeItem,
	t: TranslateFunction,
	isMarketplaceEnabled: boolean
): ModeBadges {
	const isMarketplaceItem = modeItem.type === "marketplace"
	const isInstalled = modeItem?.metaData?.isInstalled
	const isApiRegistered = modeItem.type === "apiRegistered"

	const typeBadge = getTypeBadge(modeItem, t, isMarketplaceEnabled)
	const scopeBadge = getScopeBadge(modeItem, t)
	const statusText = getStatusText(t, isMarketplaceItem, isInstalled, isApiRegistered, typeBadge, scopeBadge)

	return { typeBadge, scopeBadge, statusText }
}

/**
 * Get the type badge for a mode (marketplace, API-registered, built-in, or custom).
 * Only shows marketplace badge if marketplace feature is enabled.
 * 
 * @param modeItem - The mode item
 * @param t - Translation function
 * @param isMarketplaceEnabled - Whether marketplace feature is enabled
 * @returns Badge configuration or null if no badge should be shown
 * 
 * @example
 * ```typescript
 * const typeBadge = getTypeBadge(modeItem, t, true)
 * // Returns: { text: "Marketplace", className: "bg-[#8a3ffc]/20 text-[#be95ff]" }
 * ```
 */
export function getTypeBadge(
	modeItem: ModeItem,
	t: TranslateFunction,
	isMarketplaceEnabled: boolean
): BadgeConfig | null {
	const isMarketplaceItem = modeItem.type === "marketplace"
	const isApiRegistered = modeItem.type === "apiRegistered"

	// Only show marketplace badge if marketplace is enabled
	if (isMarketplaceItem && isMarketplaceEnabled) {
		return {
			text: t("ibmSettings:shared.badges.marketplace"),
			className: "bg-[#8a3ffc]/20 text-[#be95ff]",
		}
	}

	if (isApiRegistered) {
		return {
			text: t("ibmSettings:modes.badge_api_registered"),
			className: "bg-[#8a3ffc]/20 text-[#be95ff]",
		}
	}

	if (modeItem.type === "builtIn") {
		return {
			text: t("ibmSettings:modes.badge_builtin"),
			className: "bg-[#0f62fe]/20 text-[#78a9ff]",
		}
	}

	if (modeItem.type === "custom") {
		return {
			text: t("ibmSettings:modes.badge_custom"),
			className: "bg-[#198038]/20 text-[#42be65]",
		}
	}

	return null
}

/**
 * Get the scope badge for a mode (global or project).
 * 
 * @param modeItem - The mode item
 * @param t - Translation function
 * @returns Badge configuration or null if no scope badge should be shown
 * 
 * @example
 * ```typescript
 * const scopeBadge = getScopeBadge(modeItem, t)
 * // Returns: { text: "Global", className: "bg-[#0f62fe]/10 text-[#78a9ff] text-[9px]" }
 * ```
 */
export function getScopeBadge(
	modeItem: ModeItem,
	t: TranslateFunction
): BadgeConfig | null {
	if (modeItem.data.source === "global") {
		return {
			text: t("ibmSettings:shared.badges.global"),
			className: "bg-[#0f62fe]/10 text-[#78a9ff] text-[9px]",
		}
	}

	if (modeItem.data.source === "project") {
		return {
			text: t("ibmSettings:shared.badges.project"),
			className: "bg-[#8a3ffc]/10 text-[#be95ff] text-[9px]",
		}
	}

	return null
}

/**
 * Get the status text that combines badge information.
 * Used for displaying mode status in a single text string.
 * 
 * @param t - Translation function
 * @param isMarketplaceItem - Whether this is a marketplace mode
 * @param isInstalled - Whether the marketplace mode is installed
 * @param isApiRegistered - Whether this is an API-registered mode
 * @param typeBadge - The type badge configuration
 * @param scopeBadge - The scope badge configuration
 * @returns Status text string or undefined
 * 
 * @example
 * ```typescript
 * const statusText = getStatusText(modeItem, t, true, true, false, typeBadge, scopeBadge)
 * // Returns: "Installed / Global"
 * ```
 */
export function getStatusText(
	t: TranslateFunction,
	isMarketplaceItem: boolean,
	isInstalled: boolean | undefined,
	isApiRegistered: boolean,
	typeBadge: BadgeConfig | null,
	scopeBadge: BadgeConfig | null
): string | undefined {
	// For installed marketplace modes, show "Installed / scope"
	if (isMarketplaceItem && isInstalled) {
		return `${t("ibmSettings:shared.badges.installed")} / ${scopeBadge?.text || t("ibmSettings:shared.badges.global")}`
	}

	// For API-registered modes, show just the type badge text
	if (isApiRegistered) {
		return typeBadge?.text
	}

	// For non-marketplace modes, combine type and scope badges
	if (!isMarketplaceItem) {
		return `${typeBadge?.text}${scopeBadge ? ` / ${scopeBadge.text}` : ""}`
	}

	return undefined
}