/**
 * Interface representing the fields that can be compared for mode customization.
 * These fields are used to track modifications to built-in and API-registered modes.
 */
export interface ModeFieldComparison {
	description?: string
	roleDefinition?: string
	whenToUse?: string
	customInstructions?: string
}

/**
 * Interface for the updated mode data structure.
 */
export interface UpdatedModeData {
	description?: string
	roleDefinition?: string
	whenToUse?: string
	customInstructions?: string
	slug: string
	[key: string]: any
}

/**
 * Compares mode fields between updated values and original values,
 * returning only the fields that have been modified.
 * 
 * This utility is used for both built-in modes (comparing against DEFAULT_MODES)
 * and API-registered modes (comparing against originalValues) to track customizations
 * and enable proper reset functionality.
 * 
 * @param updatedData - The updated mode data containing potentially modified fields
 * @param originalValues - The original field values to compare against
 * @returns An object containing only the fields that differ from the original values
 * 
 * @example
 * ```typescript
 * // For built-in modes
 * const defaultMode = DEFAULT_MODES.find(m => m.slug === mode.slug)
 * const customPrompt = getModifiedFields(updatedMode.data, defaultMode)
 * 
 * // For API-registered modes
 * const customPrompt = getModifiedFields(updatedMode.data, mode.originalValues)
 * ```
 */
export function getModifiedFields(
	updatedData: UpdatedModeData,
	originalValues: ModeFieldComparison
): Record<string, string> {
	const customPrompt: Record<string, string> = {}
	
	// Define the fields to compare
	const fields: (keyof ModeFieldComparison)[] = [
		"description",
		"roleDefinition",
		"whenToUse",
		"customInstructions",
	]

	// Compare each field and include only those that differ
	fields.forEach((field) => {
		const updatedValue = updatedData[field] || ""
		const originalValue = originalValues[field] || ""

		if (updatedValue !== originalValue) {
			customPrompt[field] = updatedValue
		}
	})

	return customPrompt
}