import * as React from "react"
import { VSCodeCheckbox } from "@vscode/webview-ui-toolkit/react"
import { useAppTranslation } from "@/i18n/TranslationContext"

export interface CheckboxProps {
	/** Current checkbox value */
	value: boolean
	/** Callback when checkbox value changes */
	setValue: (value: boolean) => void
	/** Translation key for the label */
	label?: string
	/** Translation key for the description */
	description?: string
	/** Whether the component is disabled */
	disabled?: boolean
	/** CSS class name to apply to the component */
	className?: string
	/** Test ID for the component */
	testId?: string
}

/**
 * Pure Checkbox component for settings
 * Receives value and setValue props from wrapper components
 * This component is state-agnostic and can be used with any state management approach
 */
const Checkbox: React.FC<CheckboxProps> = ({ value, setValue, label, description, disabled = false, testId }) => {
	const { t } = useAppTranslation()

	// Handle checkbox change
	const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
		setValue(e.target.checked)
	}

	return (
		<div className="flex items-start">
			<div className="flex-shrink-0 w-5 h-5 mt-0.5">
				<VSCodeCheckbox
					checked={value}
					onChange={handleChange as any}
					disabled={disabled}
					data-testid={testId}
					className="min-w-[20px] min-h-[20px]"
				/>
			</div>
			{(label || description) && (
				<div className="ml-2">
					{label && <span className="text-sm">{t(label)}</span>}
					{description && <div className="text-vscode-descriptionForeground text-sm">{t(description)}</div>}
				</div>
			)}
		</div>
	)
}

export default Checkbox

