import React, { useState, useMemo, useCallback, useRef, useEffect } from "react"
import { RefreshCw, Loader2 } from "lucide-react"
import { useAppTranslation } from "@/i18n/TranslationContext"
import { useExtensionState } from "@/context/ExtensionStateContext"
import { MarketplaceItem } from "@roo-code/types"
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue, StandardTooltip, Button } from "@/components/ui"
import { SearchInput } from "@/ibm/components/common/SearchInput"
import { vscode } from "@/utils/vscode"
import { McpInstallModal, useMarketplaceFilterReset } from "@/ibm/components/settings/components/marketplace"
import { MarketplaceLoadingState } from "@/ibm/components/settings/components/MarketplaceLoadingState"
import { useMcpServers, isGlobalMcpServer, isProjectMcpServer, isMarketplaceMcpServer } from "./hooks/useMcpServers"
import { useModal } from "../../../../hooks/useModal"
import { useMarketplaceEnabled } from "../modes/hooks/useMarketplaceEnabled"
import { useMarketplaceInstall } from "./hooks/useMarketplaceInstall"
import { McpServerItem } from "./types"
import { McpServerTile } from "./McpServerTile"

type FilterType =
	| "all"
	| "connected"
	| "disconnected"
	| "global"
	| "project"
	| "installed"
	| "not-installed"
	| "marketplace"

interface McpOverviewGridProps {
	onServerSelect?: (server: McpServerItem) => void
}

const REFRESH_TIMEOUT = 2000

/**
 * McpOverviewGrid Component
 *
 * Displays a grid of MCP server tiles with search, filter, and action capabilities.
 * Shows both custom-configured servers and marketplace servers from the API.
 */
export const McpOverviewGrid: React.FC<McpOverviewGridProps> = ({ onServerSelect }) => {
	const { t } = useAppTranslation()
	const { cwd } = useExtensionState()
	const {
		allMcpServers,
		marketplaceMcpServers,
		initialMarketplaceItemsLoaded,
		marketplaceFetchError,
		isMarketplaceNetworkError,
		retryMarketplaceFetch,
		marketplaceItems,
	} = useMcpServers()
	const isMarketplaceEnabled = useMarketplaceEnabled()

	// Local state
	const [searchQuery, setSearchQuery] = useState("")
	const [filterType, setFilterType] = useState<FilterType>("all")
	const [isRefreshing, setIsRefreshing] = useState(false)

	// Modal state management using useModal hook
	const installModal = useModal<MarketplaceItem>()

	// Ref to store timeout ID for cleanup
	const refreshTimeoutRef = useRef<NodeJS.Timeout | null>(null)

	// Cleanup timeout on unmount
	useEffect(() => {
		return () => {
			if (refreshTimeoutRef.current) {
				clearTimeout(refreshTimeoutRef.current)
			}
		}
	}, [])

	useMarketplaceFilterReset(isMarketplaceEnabled, filterType, setFilterType, [
		"marketplace",
		"installed",
		"not-installed",
	])

	// Filter and search logic
	const filteredServers = useMemo(() => {
		let servers: McpServerItem[] = []

		if (filterType === "all") {
			servers = allMcpServers
		} else if (filterType === "connected") {
			// Show only servers with status "connected"
			servers = allMcpServers.filter((s) => s.data.status === "connected")
		} else if (filterType === "disconnected") {
			// Show only installed MCPs that are disabled OR have status "disconnected" (error state)
			// This includes custom servers (always considered installed) and marketplace servers that are installed
			servers = allMcpServers.filter(
				(s) => s.data.status === "disconnected" && (s.type === "custom" || s.metaData?.isInstalled),
			)
		} else if (filterType === "global") {
			// Show servers from global configuration
			servers = allMcpServers.filter(
				(s) => isGlobalMcpServer(s) && (!isMarketplaceMcpServer(s) || s.metaData?.isInstalled),
			)
		} else if (filterType === "project") {
			// Show servers from project configuration
			servers = allMcpServers.filter(
				(s) => isProjectMcpServer(s) && (!isMarketplaceMcpServer(s) || s.metaData?.isInstalled),
			)
		} else if (filterType === "installed") {
			// Show marketplace MCPs that are installed
			servers = marketplaceMcpServers.filter((s) => s.metaData?.isInstalled)
		} else if (filterType === "not-installed") {
			// Show marketplace MCPs that are not installed
			servers = marketplaceMcpServers.filter((s) => !s.metaData?.isInstalled)
		} else if (filterType === "marketplace") {
			// Show all marketplace MCPs (both installed and not installed)
			servers = marketplaceMcpServers
		}

		// Apply search filter
		if (searchQuery.trim()) {
			const query = searchQuery.toLowerCase()
			servers = servers.filter((s) => {
				return (
					s.data.name.toLowerCase().includes(query) ||
					s?.metaData?.description?.toLowerCase().includes(query) ||
					s?.metaData?.tags?.some((t: string) => t.toLowerCase().includes(query)) ||
					s?.metaData?.author?.toLowerCase().includes(query)
				)
			})
		}
		return servers
	}, [allMcpServers, filterType, marketplaceMcpServers, searchQuery])

	const handleRefreshAll = () => {
		// Clear any existing timeout
		if (refreshTimeoutRef.current) {
			clearTimeout(refreshTimeoutRef.current)
		}

		setIsRefreshing(true)
		refreshTimeoutRef.current = setTimeout(() => {
			setIsRefreshing(false)
			refreshTimeoutRef.current = null
		}, REFRESH_TIMEOUT)

		// Refresh all MCP servers
		vscode.postMessage({
			type: "refreshAllMcpServers",
		})
	}

	// Server tile action handlers
	const handleServerClick = useCallback(
		(server: McpServerItem) => {
			// Navigate to server details view
			if (onServerSelect) {
				onServerSelect(server)
			}
		},
		[onServerSelect],
	)

	const { handleInstall } = useMarketplaceInstall(marketplaceItems, installModal)

	return (
		<div className="flex flex-col gap-1">
			{/* Toolbar: Search, Filter, and Actions */}
			<div className="flex items-center gap-2 mb-1">
				{/* Search Input */}
				<SearchInput
					value={searchQuery}
					onChange={setSearchQuery}
					placeholder={t("ibmSettings:mcp.search_placeholder")}
					clearTooltip={t("ibmSettings:mcp.clear_search")}
					className="flex-1"
				/>

				{/* Filter Dropdown */}
				<Select value={filterType} onValueChange={(value) => setFilterType(value as FilterType)}>
					<SelectTrigger className="bg-vscode-dropdown-background border-vscode-dropdown-border text-[11px] min-w-[100px]">
						<SelectValue />
					</SelectTrigger>
					<SelectContent>
						<SelectItem value="all">{t("ibmSettings:shared.filters.all")}</SelectItem>
						<SelectItem value="connected">{t("ibmSettings:mcp.filter_connected")}</SelectItem>
						<SelectItem value="disconnected">{t("ibmSettings:mcp.filter_disconnected")}</SelectItem>
						<SelectItem value="global">{t("ibmSettings:mcp.filter_global")}</SelectItem>
						<SelectItem value="project">{t("ibmSettings:mcp.filter_project")}</SelectItem>
						{isMarketplaceEnabled && (
							<>
								<SelectItem value="installed">{t("common:status.installed")}</SelectItem>
								<SelectItem value="not-installed">{t("common:status.not_installed")}</SelectItem>
								<SelectItem value="marketplace">
									{t("ibmSettings:shared.filters.marketplace")}
								</SelectItem>
							</>
						)}
					</SelectContent>
				</Select>

				{/* Action Icons */}
				<div className="flex items-center gap-0">
					<StandardTooltip content={t("ibmSettings:mcp.actions.refresh_all")}>
						<Button variant="ghost" size="icon" onClick={handleRefreshAll} disabled={isRefreshing}>
							<RefreshCw className={`h-4 w-4 ${isRefreshing ? "animate-spin" : ""}`} />
						</Button>
					</StandardTooltip>
				</div>
			</div>

			{/* Main MCP Servers Grid */}
			<div className="flex flex-col">
				{/* Servers Grid */}
				{filteredServers.length > 0 && (
					<div className="grid grid-cols-1 [@media(min-width:600px)]:grid-cols-2 [@media(min-width:848px)]:grid-cols-3 gap-2">
						{filteredServers.map((server) => {
							const serverName = server.data.name
							const serverId = server?.metaData?.id
							// Use a stable key that combines both serverId and serverName to prevent orphaned tiles
							const stableKey = serverId ? `${serverId}-${serverName}` : serverName
							const shouldShowLoading =
								(isMarketplaceEnabled && !initialMarketplaceItemsLoaded) || isRefreshing

							return (
								<McpServerTile
									key={stableKey}
									serverItem={server}
									onClick={() => handleServerClick(server)}
									onInstall={() => handleInstall(server)}
									isLoading={shouldShowLoading}
								/>
							)
						})}
					</div>
				)}

				{/* Empty State */}
				{filteredServers.length === 0 && (
					<div className="text-center py-12 text-vscode-descriptionForeground">
						{isMarketplaceEnabled &&
						!initialMarketplaceItemsLoaded &&
						(filterType === "marketplace" ||
							filterType === "installed" ||
							filterType === "not-installed") ? (
							<div className="flex flex-col items-center gap-3">
								<Loader2 className="h-6 w-6 animate-spin text-vscode-descriptionForeground" />
								<p className="text-sm">{t("common:status.loading")}</p>
							</div>
						) : (
							<p className="text-sm">
								{searchQuery ? t("common:status.no_results") : t("ibmSettings:mcp.no_servers")}
							</p>
						)}
					</div>
				)}

				{/* Loading and error states below tiles when marketplace is enabled */}
				{isMarketplaceEnabled && filteredServers.length > 0 && (
					<MarketplaceLoadingState
						isLoading={!initialMarketplaceItemsLoaded}
						hasError={marketplaceFetchError}
						isMarketplaceNetworkError={isMarketplaceNetworkError}
						onRetry={() => {
							retryMarketplaceFetch()
							vscode.postMessage({ type: "retryMarketplaceConnection" })
						}}
					/>
				)}
			</div>

			{/* Install Modal - Only render when needed */}
			{installModal.isOpen && installModal.data && installModal.data.type === "mcp" && (
				<McpInstallModal
					item={installModal.data}
					isOpen={installModal.isOpen}
					onClose={installModal.close}
					hasWorkspace={!!cwd}
				/>
			)}
		</div>
	)
}

