import React from "react"
import { McpResource, McpResourceTemplate } from "@roo/mcp"
import { useTranslation } from "react-i18next"
import SectionRow from "../../../components/SectionRow"

type McpResourceSettingRowProps = {
	item: McpResource | McpResourceTemplate
}

const McpResourceSetting: React.FC<McpResourceSettingRowProps> = ({ item }) => {
	const { t } = useTranslation("ibmSettings")

	// Determine if this is a resource or resource template
	const hasUri = "uri" in item
	const identifier = hasUri ? item.uri : item.uriTemplate

	// Build description from name and description
	const baseDescription = item.name && item.description
		? `${item.name}: ${item.description}`
		: !item.name && item.description
			? item.description
			: !item.description && item.name
				? item.name
				: undefined

	// ibm_change_start: Add MIME type display to description
	const mimeTypeDisplay = item.mimeType || t("mcp.details.unknown_mime_type")
	const fullDescription = (
		<>
			{baseDescription && <div>{baseDescription}</div>}
			<div>
				<span className="opacity-80">{t("mcp.details.returns")} </span>
				<code
					className="text-vscode-textPreformat-foreground bg-vscode-textPreformat-background px-1 py-0.5 rounded"
				>
					{mimeTypeDisplay}
				</code>
			</div>
		</>
	)
	// ibm_change_end

	return <SectionRow title={identifier} description={fullDescription} />
}

export default McpResourceSetting