import { useCallback } from "react"
import { MarketplaceItem } from "@roo-code/types"
import { logger } from "@/ibm/utils/logger"
import { McpServerItem } from "../types"

/**
 * Hook to handle marketplace MCP server installation
 * Opens the install modal for marketplace items that require parameter configuration
 */
export const useMarketplaceInstall = (
	marketplaceItems: MarketplaceItem[] | undefined,
	installModal: { open: (item: MarketplaceItem) => void }
) => {
	const handleInstall = useCallback((server: McpServerItem) => {
		// Install marketplace server - find the original MarketplaceItem and show modal
		const marketplaceItem = marketplaceItems?.find(item => item.id === server.metaData?.id)
		
		if (marketplaceItem) {
			logger.info('Opening install modal for marketplace MCP server', { marketplaceItemId: marketplaceItem.id })
			installModal.open(marketplaceItem)
		} else {
			logger.error('Could not find marketplace item for MCP server', { serverId: server.metaData?.id })
		}
	}, [marketplaceItems, installModal])

	return { handleInstall }
}

