import { useEffect, useCallback } from "react"
import { useSettingsSearch } from "../context/SettingsSearchContext"

/**
 * Hook that handles keyboard shortcuts for settings search
 *
 * Shortcuts:
 * - Cmd/Ctrl+F: Focus search input
 * - Escape: Clear search (when search input is focused)
 */
export function useSettingsKeyboard() {
	const { focusSearchInput, clearSearch, isSearchActive, searchInputRef } = useSettingsSearch()

	const handleKeyDown = useCallback(
		(event: KeyboardEvent) => {
			// Cmd/Ctrl+F to focus search
			if ((event.metaKey || event.ctrlKey) && event.key === "f") {
				event.preventDefault()
				focusSearchInput()
				return
			}

			// Escape to clear search (only when search input is focused)
			if (event.key === "Escape" && isSearchActive) {
				const activeElement = document.activeElement
				if (activeElement === searchInputRef.current) {
					event.preventDefault()
					clearSearch()
					// Blur the input after clearing
					searchInputRef.current?.blur()
				}
			}
		},
		[focusSearchInput, clearSearch, isSearchActive, searchInputRef],
	)

	useEffect(() => {
		document.addEventListener("keydown", handleKeyDown)
		return () => {
			document.removeEventListener("keydown", handleKeyDown)
		}
	}, [handleKeyDown])
}

