import React, { useState, useMemo } from "react"
import { Edit, Trash2, Upload } from "lucide-react"
import { useAppTranslation } from "@/i18n/TranslationContext"
import { Button } from "@/components/ui"
import { vscode } from "@/utils/vscode"
import { ModeItem, canDeleteMode, isApiRegisteredMode, isCustomMode, isMarketplaceMode } from "./hooks/useModes"
import Section from "../../components/Section"
import SectionRow from "../../components/SectionRow"
import { useExtensionState } from "@/context/ExtensionStateContext"
import { ModeInstallModal, ModeUninstallModal } from "@/ibm/components/settings/components/marketplace"
import { logger } from "@/ibm/utils/logger"
import { MarketplaceItem } from "@roo-code/types"
import { VSCodeBadge } from "@vscode/webview-ui-toolkit/react"
import { EditModeModal } from "./EditModeModal"
import { getToolGroupLabel, findMarketplaceItem, getToolGroups } from "./modeUtils"
import { useModal } from "../../../../hooks/useModal"
import { saveModeChanges } from "./modeOperations"
import { ConfirmationDialog } from "../../components/ConfirmationDialog"
import { ItemOverview, OverviewHeader, createActionButton } from "../../components/common"
import { createMessageListener } from "@/ibm/utils/messageListener"

interface ModeDetailsViewProps {
	mode: ModeItem
	onBack: () => void
}

/**
 * ModeDetailsView Component
 *
 * Displays detailed information about a mode with contextual action buttons.
 * Shows role definition, when to use, custom instructions, available tools, and MCP servers.
 */
export const ModeDetailsView: React.FC<ModeDetailsViewProps> = ({ mode, onBack }) => {
	const { t } = useAppTranslation()
	const { marketplaceItems, cwd, marketplaceInstalledMetadata, activeProfile } = useExtensionState()
	const isExternal = activeProfile != null && !activeProfile.is_internal

	// State for loading and confirmation dialogs
	const [isDeleting, setIsDeleting] = useState(false)
	
	// Modal state management using useModal hook
	const deleteConfirmModal = useModal()
	const uninstallConfirmModal = useModal()
	const installModal = useModal<MarketplaceItem>()
	const editModal = useModal()

	// Find the original marketplace item if this is a marketplace mode
	const marketplaceItem = useMemo(() => {
		return findMarketplaceItem(mode.metaData?.id, marketplaceItems)
	}, [mode.metaData?.id, marketplaceItems])

	// Calculate current installation status from live metadata
	const isInstalled = useMemo(() => {
		if (!isMarketplaceMode(mode)) {
			return false
		}
		// For marketplace modes, check using the slug (not item.id) since modes are stored by slug
		const checkKey = mode.data.slug
		return !!(marketplaceInstalledMetadata?.global[checkKey] ||
			marketplaceInstalledMetadata?.project[checkKey])
	}, [mode, marketplaceInstalledMetadata])

	// Get tool groups for display
	const toolGroups = useMemo(() => {
		const groups = getToolGroups(mode)
		return isExternal ? groups.filter((g) => g !== "browser") : groups
	}, [mode, isExternal])

	// Action handlers
	const handleEdit = () => {
		editModal.open()
	}

	const handleSaveEdit = (updatedMode: ModeItem) => {
		saveModeChanges(mode, updatedMode, t, {
			cwd,
			marketplaceItem: marketplaceItem,
			onSuccess: () => {
				editModal.close()
			},
			onError: (error: Error) => {
				console.error(error.message)
				// TODO: Show error notification to user
			},
		})
	}

	const handleCancelEdit = () => {
		editModal.close()
	}

	const handleDelete = () => {
		setIsDeleting(true)
		try {
			vscode.postMessage({
				type: "deleteCustomMode",
				slug: mode.data.slug,
			})
			// Wait a bit for the deletion to process, then go back
			setTimeout(() => {
				deleteConfirmModal.close()
				setIsDeleting(false)
				onBack()
			}, 500)
		} catch (error) {
			console.error("Failed to delete mode:", error)
			setIsDeleting(false)
		}
	}

	const handleExport = () => {
		vscode.postMessage({
			type: "exportMode",
			slug: mode.data.slug,
		})
	}

	const handleInstall = () => {
		if (!marketplaceItem) {
			logger.error('Could not find marketplace item for mode', { modeId: mode.metaData?.id })
			return
		}

		installModal.open(marketplaceItem)
	}

	const handleUninstall = () => {
		if (!marketplaceItem) {
			console.error("Cannot uninstall: marketplace item not found")
			return
		}

		if (mode.data.source === 'registry') {
			return
		}

		setIsDeleting(true)

		// Capture marketplaceItem.id in a variable to avoid closure issues
		const itemId = marketplaceItem.id

		// Set up message listener for uninstall result
		// Note: Backend sends slug as marketplaceItem.id, not mode.data.slug
		createMessageListener({
			messageType: 'marketplaceRemoveResult',
			matchCondition: (message) => message.slug === itemId,
			onSuccess: () => {
				setIsDeleting(false)
				uninstallConfirmModal.close()
				onBack()
			},
			onError: (error) => {
				console.error("Failed to uninstall mode:", error)
				setIsDeleting(false)
				// TODO: Show error notification to user
			},
			timeout: 30000
		})

		// Send uninstall message
		vscode.postMessage({
			type: "removeInstalledMarketplaceItem",
			mpItem: marketplaceItem,
			mpInstallOptions: { target: mode.data.source || "global" },
		})
	}

	if (!mode) {
		return (
			<div className="flex flex-col items-center justify-center py-12 text-vscode-descriptionForeground">
				<p className="text-sm">{t("ibmSettings:modes.mode_not_found")}</p>
				<Button variant="ghost" onClick={onBack} className="mt-4">
					{t("common:actions.go_back")}
				</Button>
			</div>
		)
	}

	// ibm_change_start: Refactored to use createActionButton utility for DRY code
	const actionButtons = [
		createActionButton({
			key: "edit",
			condition: !(isMarketplaceMode(mode) && !isInstalled),
			icon: Edit,
			onClick: handleEdit,
			title: t("ibmSettings:modes.details.edit_button_title")
		}),
		createActionButton({
			key: "delete",
			condition: canDeleteMode(mode),
			icon: Trash2,
			onClick: () => deleteConfirmModal.open(),
			title: t("ibmSettings:modes.details.delete_button_title"),
			disabled: isDeleting,
			className: "text-vscode-foreground hover:text-vscode-foreground",
		}),
		createActionButton({
			key: "export",
			condition: isCustomMode(mode),
			icon: Upload,
			onClick: () => handleExport(),
			title: t("ibmSettings:modes.details.export_button_title"),
			className: "text-vscode-foreground hover:text-vscode-foreground",
		}),
		createActionButton({
			key: "install",
			condition: isMarketplaceMode(mode) && !isInstalled,
			onClick: handleInstall,
			title: t("ibmSettings:modes.details.install_button_title"),
			variant: "outline",
			size: "default",
			text: t("ibmSettings:modes.install"),
		}),
		createActionButton({
			key: "uninstall",
			condition: isMarketplaceMode(mode) && isInstalled,
			onClick: () => uninstallConfirmModal.open(),
			title: t("ibmSettings:modes.details.uninstall_button_title"),
			variant: "outline",
			size: "default",
			text: t("ibmSettings:modes.uninstall"),
		}),
	]
	// ibm_change_end


	return (
		<>
			<ItemOverview
				header={
					<OverviewHeader
						title={mode.data.name}
						onBack={onBack}
						actions={<>{actionButtons}</>}
					/>
				}
			>
				<Section>
					{mode.data.description && (
						<SectionRow
							title={t("ibmSettings:shared.details.description")}
							description={mode.data.description}
						/>
					)}

					{/* ibm_change_start: Display source information for API-registered modes */}
					{isApiRegisteredMode(mode) && mode.sourceInfo && (
						<SectionRow
							title={t("ibmSettings:modes.details.extension_source")}
							description={mode.sourceInfo.sourceName}
						/>
					)}
					{/* ibm_change_end */}

					{mode?.metaData?.tags && (
						<div className="p-2 pb-3">
							<label className="block text-sm font-medium text-vscode-foreground mb-1">
								{t("ibmSettings:shared.details.tags")}
							</label>
							<div className="flex flex-wrap gap-2">
								{Array.isArray(mode.metaData.tags) ? (
									mode.metaData.tags.map((tag) => (
										<VSCodeBadge key={tag} className="capitalize">
											{tag}
										</VSCodeBadge>
									))
								) : (
									<VSCodeBadge className="capitalize">
										{mode.metaData.tags}
									</VSCodeBadge>
								)}
							</div>
						</div>
					)}

					{/* ibm_change: Only show scope for non-API-registered modes */}
					{!isApiRegisteredMode(mode) && mode.data.source && (
						<SectionRow
							title={t("ibmSettings:shared.details.scope")}
							description={mode.data.source === 'global' ? t("ibmSettings:shared.badges.global") : t("ibmSettings:shared.badges.project")}
						/>
					)}

					{mode.data.roleDefinition && (
						<SectionRow
							title={t("ibmSettings:modes.details.role_definition")}
							description={mode.data.roleDefinition}
						/>
					)}

					{mode.data.whenToUse && (
						<SectionRow
							title={t("ibmSettings:modes.details.when_to_use")}
							description={mode.data.whenToUse}
						/>
					)}

					{mode.data.customInstructions && (
						<SectionRow
							title={t("ibmSettings:modes.details.custom_instructions")}
							description={mode.data.customInstructions}
						/>
					)}

					{mode.data.roleDefinition && (
						<SectionRow
							title={t("ibmSettings:modes.details.available_tools")}
							description={
								<div className="flex flex-wrap gap-2 mt-2">
									{toolGroups.map((group) => (
										<VSCodeBadge
											key={group}
											className="capitalize"
										>
											{getToolGroupLabel(group, t)}
										</VSCodeBadge>
									))}
								</div>
							}
						/>
					)}
				</Section>
			</ItemOverview>

			{/* Delete Confirmation Dialog */}
			<ConfirmationDialog
				isOpen={deleteConfirmModal.isOpen}
				title={t("ibmSettings:modes.delete_confirm_title")}
				message={t("ibmSettings:modes.delete_confirm_message")}
				confirmText={isDeleting ? t("ibmSettings:modes.deleting") : t("common:actions.delete")}
				cancelText={t("common:actions.cancel")}
				isLoading={isDeleting}
				onConfirm={handleDelete}
				onCancel={deleteConfirmModal.close}
				isDestructive
			/>
	
			{/* Uninstall Modal */}
			{uninstallConfirmModal.isOpen && marketplaceItem && marketplaceItem.type === "mode" && (
				<ModeUninstallModal
					item={marketplaceItem}
					isOpen={uninstallConfirmModal.isOpen}
					onClose={uninstallConfirmModal.close}
					onConfirm={handleUninstall}
					isLoading={isDeleting}
				/>
			)}
	
			{/* Install Modal */}
			{installModal.isOpen && installModal.data && installModal.data.type === "mode" && (
				<ModeInstallModal
					item={installModal.data}
					isOpen={installModal.isOpen}
					onClose={installModal.close}
					hasWorkspace={!!cwd}
				/>
			)}
	
			{/* Edit Mode Modal */}
			{editModal.isOpen && (
				<EditModeModal
					isOpen={editModal.isOpen}
					mode={mode}
					onSave={handleSaveEdit}
					onCancel={handleCancelEdit}
				/>
			)}
		</>
	)
}

