import * as React from "react"
import ToggleButton from "@/ibm/components/common/toggleButton/ToggleButton"

export interface ToggleProps {
	/** Current toggle value */
	value: boolean
	/** Callback when toggle value changes */
	setValue: (value: boolean) => void
	/** Whether to render without a container */
	noContainer?: boolean
	/** Optional icon to display when toggled on */
	icon?: React.ReactNode
	/** Whether the component is disabled */
	disabled?: boolean
}

/**
 * Pure Toggle component for settings
 * Receives value and setValue props from wrapper components
 * This component is state-agnostic and can be used with any state management approach
 *
 * @example Usage with wrapper:
 * ```tsx
 * <ExtensionStateWrapper binding={binding}>
 *   {(value, setValue) => (
 *     <Toggle value={value} setValue={setValue} />
 *   )}
 * </ExtensionStateWrapper>
 * ```
 */
const Toggle: React.FC<ToggleProps> = ({ value, setValue, noContainer = true, icon, disabled = false }) => {
	return (
		<ToggleButton checked={value} onChange={setValue} noContainer={noContainer} icon={icon} disabled={disabled} />
	)
}

export default Toggle

