import { DEFAULT_MODES, MarketplaceItem } from "@roo-code/types"
import { isApiRegisteredMode, isBuiltInMode, isCustomMode, isMarketplaceMode, ModeItem } from "./hooks/useModes"
import { TranslateFunction } from "./modeUtils"
import { vscode } from "@/utils/vscode"
import { getModifiedFields } from "./utils/modeFieldComparison"
import { validateScopeChange, handleMarketplaceScopeChange, handleCustomScopeChange } from "./utils/scopeChange"

/**
 * Options for saving mode changes
 */
export interface SaveModeOptions {
	/**
	 * Current working directory (required for project scope validation)
	 */
	cwd?: string
	/**
	 * Marketplace item data (required for marketplace mode scope changes)
	 */
	marketplaceItem?: MarketplaceItem
	/**
	 * Callback to execute after successful save
	 */
	onSuccess?: () => void
	/**
	 * Callback to execute on error
	 */
	onError?: (error: Error) => void
}

/**
 * Options for deleting a mode
 */
export interface DeleteModeOptions {
	/**
	 * Callback to execute after successful deletion
	 */
	onSuccess?: () => void
	/**
	 * Callback to execute on error
	 */
	onError?: (error: Error) => void
}

/**
 * Options for exporting a mode
 */
export interface ExportModeOptions {
	/**
	 * Callback to execute after successful export
	 */
	onSuccess?: () => void
	/**
	 * Callback to execute on error
	 */
	onError?: (error: Error) => void
}

/**
 * Save or update a mode's configuration.
 * Handles both built-in and custom modes with appropriate message types.
 *
 * For built-in modes:
 * - Compares with default configuration
 * - Only sends modified fields via 'updatePrompt' message
 * - Allows reset functionality to work properly
 *
 * For custom modes:
 * - Handles scope changes (global <-> project)
 * - Validates workspace exists for project scope
 * - Deletes from old location when scope changes
 * - Sends complete configuration via 'updateCustomMode' message
 *
 * @param mode - The original mode being edited
 * @param updatedMode - The mode with updated values
 * @param t - Translation function for error messages
 * @param options - Optional save options including callbacks and cwd
 * @throws Error if workspace is required but not available
 *
 * @example
 * ```ts
 * // Save built-in mode changes
 * saveModeChanges(originalMode, updatedMode, t, {
 *   onSuccess: () => console.log("Saved!"),
 *   onError: (err) => console.error(err)
 * })
 *
 * // Save custom mode with scope change
 * saveModeChanges(originalMode, updatedMode, t, {
 *   cwd: "/path/to/workspace",
 *   onSuccess: () => closeModal()
 * })
 * ```
 */
export function saveModeChanges(
	mode: ModeItem,
	updatedMode: ModeItem,
	t: TranslateFunction,
	options?: SaveModeOptions
): void {
	try {
		if (isBuiltInMode(mode)) {
			// For built-in modes, only send fields that differ from defaults
			// This allows reset functionality to work properly
			const defaultMode = DEFAULT_MODES.find((m) => m.slug === updatedMode.data.slug)
			
			// ibm_change: Use getModifiedFields utility to compare fields
			const customPrompt = defaultMode ? getModifiedFields(updatedMode.data, defaultMode) : {}
	
			vscode.postMessage({
				type: "updatePrompt",
				promptMode: updatedMode.data.slug,
				customPrompt,
			})
	
			options?.onSuccess?.()
		} else if (isApiRegisteredMode(mode)) {
			// For API-registered modes, use the same pattern as built-in modes
			// Store only the changed fields in customModePrompts
			const originalMode = mode.originalValues
			
			// ibm_change: Use getModifiedFields utility to compare fields
			const customPrompt = originalMode ? getModifiedFields(updatedMode.data, originalMode) : {}
	
			vscode.postMessage({
				type: "updatePrompt",
				promptMode: updatedMode.data.slug,
				customPrompt,
			})
	
			options?.onSuccess?.()
		} else if (isMarketplaceMode(mode)) {
			// ibm_change: Handle marketplace mode scope changes and custom field updates
			const originalScope = mode.data.source
			const newScope = updatedMode.data.source

			// Apply custom prompt changes
			const applyCustomPrompt = () => {
				vscode.postMessage({
					type: "updateCustomMode",
					modeConfig: {
						slug: updatedMode.data.slug,
						name: updatedMode.data.name,
						description: updatedMode.data.description || "",
						roleDefinition: updatedMode.data.roleDefinition || "",
						whenToUse: updatedMode.data.whenToUse || "",
						customInstructions: updatedMode.data.customInstructions || "",
						source: updatedMode.data.source,
						groups: updatedMode.data.groups || [],
					},
				})

				options?.onSuccess?.()
				// This ensures the UI reflects the new installation location
				vscode.postMessage({
					type: "fetchMarketplaceData",
				})
			}

			// ibm_change: Use validateScopeChange utility to check if scope changed and validate workspace
			const scopeChanged = validateScopeChange({
				originalScope,
				newScope,
				cwd: options?.cwd,
				t,
			})

			if (scopeChanged) {
				// ibm_change: Use handleMarketplaceScopeChange utility for marketplace mode scope changes
				handleMarketplaceScopeChange({
					mode,
					originalScope,
					newScope,
					marketplaceItem: options?.marketplaceItem,
					applyCustomPrompt,
					vscode,
					onError: options?.onError,
				})
			} else {
				// ibm_change: No scope change, apply custom field changes if marketplace item is provided
				applyCustomPrompt()
			}
		} else if (isCustomMode(mode)) {
			// ibm_change: Use validateScopeChange utility to check if scope changed and validate workspace
			const originalScope = mode.data.source
			const newScope = updatedMode.data.source
			const scopeChanged = validateScopeChange({
				originalScope,
				newScope,
				cwd: options?.cwd,
				t,
			})

			if (scopeChanged) {
				// ibm_change: Use handleCustomScopeChange utility to delete mode from old location
				handleCustomScopeChange({
					mode: updatedMode,
					vscode,
				})
			}

			vscode.postMessage({
				type: "updateCustomMode",
				modeConfig: {
					slug: updatedMode.data.slug,
					name: updatedMode.data.name,
					description: updatedMode.data.description || "",
					roleDefinition: updatedMode.data.roleDefinition || "",
					whenToUse: updatedMode.data.whenToUse || "",
					customInstructions: updatedMode.data.customInstructions || "",
					source: updatedMode.data.source,
					groups: updatedMode.data.groups || [],
				},
			})

			options?.onSuccess?.()
		}
	} catch (error) {
		if (error instanceof Error) {
			options?.onError?.(error)
		}
		throw error
	}
}

/**
 * Delete a custom mode.
 * Only custom modes can be deleted; built-in and marketplace modes cannot be deleted.
 *
 * @param mode - The mode to delete
 * @param options - Optional delete options including callbacks
 * @throws Error if attempting to delete a non-custom mode
 *
 * @example
 * ```ts
 * deleteMode(mode, {
 *   onSuccess: () => {
 *     console.log("Mode deleted")
 *     navigateBack()
 *   },
 *   onError: (err) => console.error(err)
 * })
 * ```
 */
export function deleteMode(mode: ModeItem, options?: DeleteModeOptions): void {
	try {
		if (!isCustomMode(mode)) {
			const error = new Error("Only custom modes can be deleted")
			options?.onError?.(error)
			throw error
		}

		vscode.postMessage({
			type: "deleteCustomMode",
			slug: mode.data.slug,
		})

		options?.onSuccess?.()
	} catch (error) {
		if (error instanceof Error) {
			options?.onError?.(error)
		}
		throw error
	}
}

/**
 * Export a mode's configuration to a file.
 * Sends a message to the extension to handle the file save dialog and export.
 *
 * @param mode - The mode to export
 * @param options - Optional export options including callbacks
 *
 * @example
 * ```ts
 * exportMode(mode, {
 *   onSuccess: () => console.log("Mode exported"),
 *   onError: (err) => console.error(err)
 * })
 * ```
 */
export function exportMode(mode: ModeItem, options?: ExportModeOptions): void {
	try {
		vscode.postMessage({
			type: "exportMode",
			modeConfig: mode.data,
		})

		options?.onSuccess?.()
	} catch (error) {
		if (error instanceof Error) {
			options?.onError?.(error)
		}
		throw error
	}
}

