import React from "react"
import { VSCodeRadioGroup, VSCodeRadio } from "@vscode/webview-ui-toolkit/react"
import { useAppTranslation } from "@/i18n/TranslationContext"

export type scopeType = "global" | "project" | "registry"

interface ScopeSelectorProps {
	/** Current scope value */
	value: scopeType
	/** Callback when scope changes */
	onChange: (scope: scopeType) => void
	/** Whether the scope has changed from original */
	scopeChanged?: boolean
	/** Helper text to display below the selector */
	helperText?: string
	/** Label for the selector */
	label: string
}

/**
 * ScopeSelector Component
 *
 * Displays scope selection (global/project) for custom modes.
 * Shows a warning when the scope is changed to inform users about file relocation.
 */
export const ScopeSelector: React.FC<ScopeSelectorProps> = ({
	value,
	onChange,
	scopeChanged = false,
	helperText,
	label,
}) => {
	const { t } = useAppTranslation()
	return (
		<div className="border-b border-vscode-editor-background last:border-b-0 p-2">
			<label className="block text-sm font-medium text-vscode-foreground mb-1">
				{label}
			</label>
			{helperText && (
				<div className="text-xs text-vscode-descriptionForeground mb-2">
					{helperText}
				</div>
			)}
			<VSCodeRadioGroup
				value={value}
				onChange={(e: any) => onChange(e.target.value)}
			>
				<VSCodeRadio value="global">
					{t("ibmSettings:modes.edit_modal.scope_global")}
				</VSCodeRadio>
				<VSCodeRadio value="project">
					{t("ibmSettings:modes.edit_modal.scope_project")}
				</VSCodeRadio>
			</VSCodeRadioGroup>
			{scopeChanged && (
				<div className="mt-2 p-2 bg-yellow-500/10 border border-yellow-500/30 rounded text-xs text-yellow-500">
					⚠️ {value === 'global'
						? t("ibmSettings:common.scope_change_to_global")
						: t("ibmSettings:common.scope_change_to_project")}
				</div>
			)}
		</div>
	)
}

