import React from 'react'

/**
 * ModalFooter Component
 * 
 * A reusable modal footer component for action buttons. Provides consistent
 * layout with right-aligned buttons, proper spacing, and a top border for
 * visual separation from the modal body.
 * 
 * @example
 * ```tsx
 * <ModalFooter>
 *   <Button variant="ghost" onClick={onCancel}>Cancel</Button>
 *   <Button onClick={onSave}>Save</Button>
 * </ModalFooter>
 * ```
 * 
 * Design Reference: Edit Mode modal (Figma 476-8985)
 * Source Reference: EditModeModal.tsx (lines 310-322)
 */

interface ModalFooterProps {
	/** Action buttons to display in the footer */
	children: React.ReactNode
	/** Additional CSS classes to apply to the footer container */
	className?: string
}

export const ModalFooter: React.FC<ModalFooterProps> = ({
	children,
	className = '',
}) => {
	return (
		<div className={`flex justify-end gap-2 p-3 ${className}`.trim()}>
			{children}
		</div>
	)
}

