import React from "react"
import MarkdownBlock from "@/components/common/MarkdownBlock"

interface SectionRowProps {
	title: string | React.ReactNode
	description?: string | React.ReactNode
	actionComponent?: React.ReactNode
	/** Optional class name for the wrapper div (useful for search dimming) */
	className?: string
}

const SectionRow: React.FC<SectionRowProps> = ({ title, description, actionComponent, className = "" }) => {
	const renderDescription = () => {
		if (!description) return null

		// If description is a string, render it as markdown
		if (typeof description === "string") {
			return <MarkdownBlock markdown={description} className="text-vscode-descriptionForeground !text-sm [&_p]:!m-0" />
		}

		// Otherwise, render it as a React node
		return <div className="text-vscode-descriptionForeground text-sm">{description}</div>
	}

	const wrapperClasses = `min-h-10 border-b border-vscode-editor-background last:border-b-0 ${className}`.trim()

	return (
		<div className={wrapperClasses}>
			<div className="flex justify-between items-center p-2 gap-2">
				<div>
					<div className="text-sm font-medium">{title}</div>
					{renderDescription()}
				</div>
				<div>{actionComponent}</div>
			</div>
		</div>
	)
}

export default SectionRow
