import React, { useMemo } from "react"
import { Information, WarningAlt } from "@carbon/icons-react"
import { useAppTranslation } from "@/i18n/TranslationContext"
import { useExtensionState } from "@/context/ExtensionStateContext"
import { formatRefreshDate, getTrialStatus } from "@roo/IBM/userProfileHelpers"
import { ENTERPRISE_PLAN_ID } from "@/ibm/constants"

/**
 * Component that displays budget reset information
 * Shows an informational message about when budgets reset
 */
const BudgetResetInfo: React.FC = () => {
	const { activeProfile } = useExtensionState()
	const { t, i18n } = useAppTranslation()

	const { isTrial, daysRemaining, isExpired, isExpiringSoon } = useMemo(() => {
		return getTrialStatus(activeProfile)
	}, [activeProfile])

	const isProfileLoading = !activeProfile?.user_id

	if (isProfileLoading) {
		return null
	}
	const locale = i18n.language || "en"
	const isEnterprise = activeProfile?.plan === ENTERPRISE_PLAN_ID
	const formattedDate = activeProfile.refresh_at
		? formatRefreshDate(activeProfile.refresh_at, locale, isEnterprise)
		: ""

	let icon = <Information className="text-vscode-button-secondaryForeground text-[16px]" />
	let text = (
		<p className="text-[12px] font-medium text-vscode-button-secondaryForeground">
			{formattedDate
				? isEnterprise
					? t("ibmSettings:general.enterprisePlanExpiresDate", { date: formattedDate })
					: t("ibmSettings:general.budgetResetsDate", { date: formattedDate })
				: isEnterprise
					? t("ibmSettings:general.enterprisePlanExpires")
					: t("ibmSettings:general.budgetResets")}
		</p>
	)

	if (isTrial && isExpired) {
		icon = <WarningAlt className="text-vscode-errorForeground text-[16px]" />
		text = (
			<p className="text-[12px] font-medium text-vscode-errorForeground">
				{t("ibmSettings:general.trialExpired")}
			</p>
		)
	} else if (isTrial) {
		icon = (
			<WarningAlt
				className={`${isExpiringSoon ? "text-vscode-errorForeground" : "text-vscode-button-secondaryForeground"} text-[16px]`}
			/>
		)
		text = (
			<p
				className={`${isExpiringSoon ? "text-vscode-errorForeground" : "text-vscode-button-secondaryForeground"} text-[12px] font-medium`}>
				{daysRemaining === 1
					? t("ibmSettings:general.trialDayRemaining")
					: t("ibmSettings:general.trialDaysRemaining", { days: daysRemaining })}
			</p>
		)
	}

	return (
		<div className="mx-2 mb-1 mt-2 px-3 bg-vscode-button-secondaryBackground rounded-[4px] flex gap-[10px] items-center">
			{icon}
			{text}
		</div>
	)
}

export default BudgetResetInfo

