import React from "react"
import { Button, StandardTooltip } from "@/components/ui"
import { LucideIcon } from "lucide-react"

/**
 * Configuration for an action button in detail views.
 * 
 * @interface ActionButtonConfig
 * @property {boolean} condition - Whether the button should be rendered
 * @property {LucideIcon} [icon] - Icon component to display (for icon-only buttons)
 * @property {() => void} onClick - Click handler function
 * @property {string} title - Tooltip text for the button
 * @property {'ghost' | 'outline' | 'primary' | 'secondary' | 'destructive' | 'link' | 'combobox'} [variant] - Button style variant (default: 'ghost')
 * @property {'icon' | 'sm' | 'lg' | 'default'} [size] - Button size (default: 'icon')
 * @property {string} [text] - Text to display (for text buttons instead of icon-only)
 * @property {boolean} [disabled] - Whether the button is disabled
 * @property {string} [className] - Additional CSS classes
 * 
 * @example
 * ```tsx
 * const config: ActionButtonConfig = {
 *   condition: canEdit,
 *   icon: Edit,
 *   onClick: handleEdit,
 *   title: "Edit item",
 *   variant: "ghost",
 *   size: "icon"
 * }
 * ```
 */
export interface ActionButtonConfig {
	key?: string
	condition: boolean
	icon?: LucideIcon
	onClick: () => void
	title: string
	variant?: "ghost" | "outline" | "primary" | "secondary" | "destructive" | "link" | "combobox"
	size?: "icon" | "sm" | "lg" | "default"
	text?: string
	disabled?: boolean
	className?: string
}

/**
 * Creates an action button based on the provided configuration.
 * Returns null if the condition is false, enabling conditional rendering.
 * 
 * This utility eliminates duplicate button rendering logic by providing
 * a single, reusable function for creating action buttons with consistent
 * styling and behavior across all detail views (Modes, MCP, Rules, Commands).
 * 
 * @param {ActionButtonConfig} config - Button configuration object
 * @returns {React.ReactNode | null} Button component or null if condition is false
 * 
 * @example
 * ```tsx
 * // Icon-only button
 * const editButton = createActionButton({
 *   condition: !isReadOnly,
 *   icon: Edit,
 *   onClick: handleEdit,
 *   title: "Edit item",
 *   variant: "ghost",
 *   size: "icon"
 * })
 * 
 * // Text button
 * const installButton = createActionButton({
 *   condition: !isInstalled,
 *   onClick: handleInstall,
 *   title: "Install item",
 *   text: "Install",
 *   variant: "outline"
 * })
 * 
 * // Disabled button
 * const deleteButton = createActionButton({
 *   condition: canDelete,
 *   icon: Trash2,
 *   onClick: handleDelete,
 *   title: "Delete item",
 *   disabled: isDeleting,
 *   className: "text-vscode-foreground hover:text-vscode-foreground"
 * })
 * ```
 */
export function createActionButton(config: ActionButtonConfig): React.ReactNode {
	if (!config.condition) {
		return null
	}

	const {
		key,
		icon: Icon,
		onClick,
		title,
		variant = "ghost",
		size = "icon",
		text,
		disabled = false,
		className,
	} = config

	return (
		<StandardTooltip key={key} content={title}>
			<Button
				variant={variant}
				size={size}
				onClick={onClick}
				disabled={disabled}
				className={className}
			>
				{text ? text : Icon && <Icon className="h-4 w-4" />}
			</Button>
		</StandardTooltip>
	)
}

