import React, { StrictMode, useState, useEffect, useCallback } from "react"
import { QueryClient, QueryClientProvider } from "@tanstack/react-query"
import ErrorBoundary from "../../../components/ErrorBoundary"
import { ExtensionStateContextProvider, useExtensionState } from "../../../context/ExtensionStateContext"
import TranslationProvider, { useAppTranslation } from "../../../i18n/TranslationContext"
import { TooltipProvider } from "../../../components/ui/tooltip"
import { STANDARD_TOOLTIP_DELAY } from "../../../components/ui/standard-tooltip"
import { createRoot } from "react-dom/client"
import { vscode } from "../../../utils/vscode"
import { messageCallbackStore } from "../../../utils/MessageCallbackStore"
import SettingsPage, { SettingsTabId } from "./SettingsPage"

// Create a QueryClient instance
const queryClient = new QueryClient()

/**
 * Main Settings component that renders the settings view with all necessary providers
 */
const Settings = () => {
	const { didHydrateState, featureFlags, envConfig } = useExtensionState()
	const { t } = useAppTranslation()
	const [initialTab, setInitialTab] = useState<SettingsTabId | undefined>()
	const [tabChangeKey, setTabChangeKey] = useState(0)

	// Handle messages from the extension
	const onMessage = useCallback((e: MessageEvent) => {
		const message = e.data

		// Handle callback responses
		if (message.type === "resolveCallback" && message.callbackId) {
			messageCallbackStore.resolveCallback(message.callbackId, message.callbackResult)
			return
		}

		if (message.type === "rejectCallback" && message.callbackId) {
			messageCallbackStore.rejectCallback(message.callbackId, message.error || "Unknown error")
			return
		}

		if (message.type === "settingsTabChange" && message.values?.targetTab) {
			setInitialTab(message.values.targetTab)
			// Force re-render by incrementing key to ensure tab change is applied
			setTabChangeKey((prev) => prev + 1)
		}
	}, [])

	// Set up message listener
	useEffect(() => {
		window.addEventListener("message", onMessage)
		// Tell the extension we're ready to receive messages
		vscode.postMessage({ type: "webviewDidLaunch" })
		return () => {
			window.removeEventListener("message", onMessage)
		}
	}, [onMessage])

	// Wait for feature flags and env config to be initialized before rendering
	// This prevents components that use useFeatureFlag from throwing errors
	if (!didHydrateState || !featureFlags || !envConfig) {
		return (
			<div className="flex items-center justify-center h-screen">
				<div className="text-vscode-descriptionForeground">{t("common:status.loading")}</div>
			</div>
		)
	}

	return <SettingsPage key={tabChangeKey} initialTab={initialTab} />
}

/**
 * Root component that wraps the Settings component with all necessary providers
 */
const SettingsWithProviders = () => {
	return (
		<ErrorBoundary>
			<ExtensionStateContextProvider>
				<TranslationProvider>
					<QueryClientProvider client={queryClient}>
						<TooltipProvider delayDuration={STANDARD_TOOLTIP_DELAY}>
							<Settings />
						</TooltipProvider>
					</QueryClientProvider>
				</TranslationProvider>
			</ExtensionStateContextProvider>
		</ErrorBoundary>
	)
}

createRoot(document.getElementById("settings-root")!).render(
	<StrictMode>
		<SettingsWithProviders />
	</StrictMode>,
)

export default SettingsWithProviders

