import React from "react"

interface InfoListProps {
	/** Field label (required) */
	label: string
	/** Array of items to display (required) */
	items: string[]
	/** Optional helper text displayed below the label */
	helperText?: string
}

export const InfoList: React.FC<InfoListProps> = ({
	label,
	items,
	helperText,
}) => {
	return (
		<div className="border-b border-vscode-editor-background last:border-b-0 p-2">
			<label className="text-sm font-medium text-vscode-foreground mb-1 block">
				{label}
			</label>
			{helperText && (
				<div className="text-xs text-vscode-descriptionForeground mb-2">
					{helperText}
				</div>
			)}
			<ul className="list-disc list-inside space-y-1 m-0">
				{items.map((item, index) => (
					<li key={index} className="text-xs text-vscode-descriptionForeground">
						{item}
					</li>
				))}
			</ul>
		</div>
	)
}

