import React, { useMemo } from "react"
import { useExtensionState } from "@/context/ExtensionStateContext"
import { useAppTranslation } from "@/i18n/TranslationContext"
import { Button, StandardTooltip } from "@/components/ui"
import { ItemEditModal, FormField, ScopeSelector } from "../../components/common"
import { isApiRegisteredMode, isCustomMode, isMarketplaceMode, ModeItem } from "./hooks/useModes"
import Section from "../../components/Section"
import { getToolGroups } from "./modeUtils"
import { useModeForm } from "./hooks/useModeForm"
import { ToolGroupSelector } from "./ToolGroupSelector"

interface EditModeModalProps {
	isOpen: boolean
	mode: ModeItem
	onSave: (updatedMode: ModeItem) => void
	onCancel: () => void
	allModes?: ModeItem[]
}

/**
 * EditModeModal Component
 *
 * Modal dialog for editing both built-in and custom modes.
 * Displays appropriate fields based on mode type (built-in vs custom).
 */
export const EditModeModal: React.FC<EditModeModalProps> = ({ isOpen, mode, onSave, onCancel, allModes }) => {
	const { t } = useAppTranslation()
	const { activeProfile } = useExtensionState()
	const isExternal = activeProfile != null && !activeProfile.is_internal

	// Use the form state hook to manage all form state
	const {
		formState,
		setDescription,
		setRoleDefinition,
		setWhenToUse,
		setCustomInstructions,
		setSlug,
		setName,
		setScope,
		handleToolToggle,
		slugError,
		nameError,
		roleDefinitionError,
		setSlugError,
		setNameError,
		setRoleDefinitionError,
		isDescriptionModified,
		isRoleDefinitionModified,
		isWhenToUseModified,
		isCustomInstructionsModified,
		handleResetDescription,
		handleResetRoleDefinition,
		handleResetWhenToUse,
		handleResetCustomInstructions,
		scopeChanged,
		getFormChanges,
		isFormValid,
	} = useModeForm(mode, t)

	// Destructure form state for easier access
	const { description, roleDefinition, whenToUse, customInstructions, slug, name, scope, selectedTools } = formState

	// Available tool groups
	const allToolGroups = ["read", "edit", "browser", "command", "mcp", "modes"]
	const availableToolGroups = isExternal ? allToolGroups.filter((g) => g !== "browser") : allToolGroups

	// Get tool groups for display
	const toolGroups = useMemo(() => {
		const groups = getToolGroups(mode)
		return isExternal ? groups.filter((g) => g !== "browser") : groups
	}, [mode, isExternal])

	// ibm_change: Use isCustomMode to differentiate - all non-custom modes behave the same (except marketplace can change scope)
	const isCustom = isCustomMode(mode)
	const isMarketplace = isMarketplaceMode(mode)
	const isNewMode = !mode.data.name

	// ibm_change: Add source name to title for API-registered modes using translation
	const modalTitle = isNewMode
		? t("ibmSettings:modes.edit_modal.title_create")
		: isApiRegisteredMode(mode) && mode.sourceInfo
			? t("ibmSettings:modes.edit_modal.title_api_registered", {
					modeName: mode.data.name,
					sourceName: mode.sourceInfo.sourceName,
				})
			: t("ibmSettings:modes.edit_modal.title", { modeName: mode.data.name })

	const handleSave = () => {
		// Validate form using the hook's validation
		if (!isFormValid(allModes)) {
			return
		}

		// Get updated mode from form changes
		const updatedMode = getFormChanges() as ModeItem
		onSave(updatedMode)
	}

	// ibm_change_start: Render common fields that appear in all modes
	const renderCommonFields = () => (
		<>
			<FormField
				label={t("ibmSettings:modes.edit_modal.role_definition_label")}
				value={roleDefinition}
				onChange={(value: string) => {
					setRoleDefinition(value)
					if (roleDefinitionError) setRoleDefinitionError("")
				}}
				placeholder={t("ibmSettings:modes.edit_modal.role_definition_placeholder")}
				type="vscode-textarea"
				minRows={4}
				errorText={roleDefinitionError}
				helperText={t("ibmSettings:modes.edit_modal.role_definition_helper")}
				{...(!isCustom && {
					showResetButton: true,
					isModified: isRoleDefinitionModified,
					onReset: handleResetRoleDefinition,
					resetTooltip: t("ibmSettings:modes.edit_modal.reset_button_tooltip"),
				})}
			/>

			<FormField
				label={t("ibmSettings:modes.edit_modal.when_to_use_label")}
				value={whenToUse}
				onChange={setWhenToUse}
				placeholder={t("ibmSettings:modes.edit_modal.when_to_use_placeholder")}
				type="vscode-textarea"
				minRows={3}
				helperText={t("ibmSettings:modes.edit_modal.when_to_use_helper")}
				{...(!isCustom && {
					showResetButton: true,
					isModified: isWhenToUseModified,
					onReset: handleResetWhenToUse,
					resetTooltip: t("ibmSettings:modes.edit_modal.reset_button_tooltip"),
				})}
			/>

			<FormField
				label={t("ibmSettings:modes.edit_modal.custom_instructions_label")}
				value={customInstructions}
				onChange={setCustomInstructions}
				placeholder={t("ibmSettings:modes.edit_modal.custom_instructions_placeholder")}
				type="vscode-textarea"
				minRows={6}
				helperText={t("ibmSettings:modes.edit_modal.custom_instructions_helper")}
				{...(!isCustom && {
					showResetButton: true,
					isModified: isCustomInstructionsModified,
					onReset: handleResetCustomInstructions,
					resetTooltip: t("ibmSettings:modes.edit_modal.reset_button_tooltip"),
				})}
			/>

			<ToolGroupSelector
				label={t("ibmSettings:modes.edit_modal.available_tools_label")}
				availableToolGroups={availableToolGroups}
				selectedTools={!isCustom ? toolGroups : selectedTools}
				onToolToggle={handleToolToggle}
				{...(!isCustom
					? {
							readOnly: true,
							helperText: t("ibmSettings:modes.edit_modal.tools_readonly_helper_builtin"),
						}
					: {
							helperText: t("ibmSettings:modes.edit_modal.tools_helper"),
						})}
			/>
		</>
	)
	// ibm_change_end

	return (
		<ItemEditModal
			isOpen={isOpen}
			title={modalTitle}
			onClose={onCancel}
			footer={
				<>
					<StandardTooltip content={t("ibmSettings:modes.edit_modal.cancel_button_tooltip")}>
						<Button variant="secondary" onClick={onCancel}>
							{t("ibmSettings:modes.edit_modal.cancel_button")}
						</Button>
					</StandardTooltip>
					<StandardTooltip content={t("ibmSettings:modes.edit_modal.save_button_tooltip")}>
						<Button variant="primary" onClick={handleSave}>
							{t("ibmSettings:modes.edit_modal.save_button")}
						</Button>
					</StandardTooltip>
				</>
			}>
			<Section>
				{/* ibm_change_start: Non-custom modes (built-in, API-registered, marketplace) */}
				{!isCustom && (
					<>
						<FormField
							label={t("ibmSettings:modes.edit_modal.description_label")}
							value={description}
							onChange={setDescription}
							placeholder={t("ibmSettings:modes.edit_modal.description_placeholder")}
							type="vscode-textarea"
							minRows={2}
							showResetButton
							isModified={isDescriptionModified}
							onReset={handleResetDescription}
							resetTooltip={t("ibmSettings:modes.edit_modal.reset_button_tooltip")}
						/>

						{/* Marketplace modes can change scope */}
						{isMarketplace && (
							<ScopeSelector
								label={t("ibmSettings:modes.edit_modal.scope_label")}
								value={scope}
								onChange={setScope}
								scopeChanged={scopeChanged}
								helperText={t("ibmSettings:modes.edit_modal.scope_helper")}
							/>
						)}

						{renderCommonFields()}
					</>
				)}

				{/* Custom Mode Fields */}
				{isCustom && (
					<>
						<FormField
							label={t("ibmSettings:modes.edit_modal.slug_label")}
							value={slug}
							onChange={(value: string) => {
								setSlug(value)
								if (slugError) setSlugError("")
							}}
							placeholder={t("ibmSettings:modes.edit_modal.slug_placeholder")}
							type="text"
							errorText={slugError}
							helperText={t("ibmSettings:modes.edit_modal.slug_helper")}
							disabled={!isNewMode}
						/>

						<FormField
							label={t("ibmSettings:modes.edit_modal.name_label")}
							value={name}
							onChange={(value: string) => {
								setName(value)
								if (nameError) setNameError("")
							}}
							placeholder={t("ibmSettings:modes.edit_modal.name_placeholder")}
							type="text"
							errorText={nameError}
						/>

						<FormField
							label={t("ibmSettings:modes.edit_modal.description_label")}
							value={description}
							onChange={setDescription}
							placeholder={t("ibmSettings:modes.edit_modal.description_placeholder")}
							type="vscode-text"
						/>

						<ScopeSelector
							label={t("ibmSettings:modes.edit_modal.scope_label")}
							value={scope}
							onChange={setScope}
							scopeChanged={scopeChanged}
							helperText={t("ibmSettings:modes.edit_modal.scope_helper")}
						/>

						{renderCommonFields()}
					</>
				)}
			</Section>
		</ItemEditModal>
	)
}

