import React from "react"
import { X } from "lucide-react"
import { Input, StandardTooltip } from "@/components/ui"

interface SearchInputProps {
	value: string
	onChange: (value: string) => void
	placeholder: string
	clearTooltip: string
	className?: string
}

/**
 * SearchInput Component
 * 
 * A reusable search input with an integrated clear button.
 * Used across MCP and Modes overview grids for consistent search UX.
 */
export const SearchInput: React.FC<SearchInputProps> = ({
	value,
	onChange,
	placeholder,
	clearTooltip,
	className = "",
}) => {
	return (
		<div className={`relative ${className}`}>
			<Input
				type="text"
				placeholder={placeholder}
				value={value}
				onChange={(e) => onChange(e.target.value)}
				className="flex-1 bg-vscode-input-background text-vscode-input-foreground border-vscode-input-border text-[13px] h-[28px] pr-8"
			/>
			{value && (
				<StandardTooltip content={clearTooltip}>
					<button
						onClick={() => onChange("")}
						className="absolute right-2 top-1/2 -translate-y-1/2 text-vscode-descriptionForeground hover:text-vscode-foreground transition-colors"
						aria-label={clearTooltip}
					>
						<X size={14} />
					</button>
				</StandardTooltip>
			)}
		</div>
	)
}

