import React, { useState } from "react"
import SectionHeader from "./SectionHeader"
import Section from "./Section"
import { ActionComponentDefinition } from "../SettingsDefinition"

interface CollapsibleSectionProps {
	title: string
	description?: string | ActionComponentDefinition
	children: React.ReactNode
	defaultCollapsed?: boolean
	className?: string
	/** Optional content to render between the header and the collapsible section (e.g., search/filter controls) */
	headerContent?: React.ReactNode
}

/**
 * A collapsible section component that combines SectionHeader with Section.
 * The header includes a collapse/expand button on the right side.
 * Optional headerContent can be provided to render controls between the header and section.
 */
const CollapsibleSection: React.FC<CollapsibleSectionProps> = ({
	title,
	description,
	children,
	defaultCollapsed = false,
	className = "",
	headerContent,
}) => {
	const [isCollapsed, setIsCollapsed] = useState(defaultCollapsed)

	return (
		<div className={className}>
			<SectionHeader
				title={title}
				description={description}
				collapsible={true}
				defaultCollapsed={defaultCollapsed}
				onCollapseChange={setIsCollapsed}
			/>
			{!isCollapsed && (
				<>
					{headerContent}
					<Section>{children}</Section>
				</>
			)}
		</div>
	)
}

export default CollapsibleSection