import { useState, useEffect } from "react"
import { useExtensionState } from "@/context/ExtensionStateContext"
import { logger } from "@/ibm/utils/logger"
import { McpServerItem, McpServerMetadata, McpServerType } from "../types"
import { McpServer } from "@roo/mcp"
import { useMarketplaceEnabled } from "../../modes/hooks/useMarketplaceEnabled" // ibm_change
import { useMarketplaceFetch } from "../../../hooks/useMarketplaceFetch" // ibm_change

/**
 * Sort MCP servers: connected first, then disconnected installed/custom, then marketplace not installed
 */
export const sortMcpServers = (servers: McpServerItem[]): McpServerItem[] => {
	return servers.sort((a, b) => {
		const aConnected = a.data.status === 'connected'
		const bConnected = b.data.status === 'connected'
		const aInstalled = a.type === 'custom' || a.metaData?.isInstalled
		const bInstalled = b.type === 'custom' || b.metaData?.isInstalled
		
		// Connected servers come first
		if (aConnected && !bConnected) return -1
		if (!aConnected && bConnected) return 1
		
		// Among same connection status, installed/custom come before not installed
		if (aConnected === bConnected) {
			if (aInstalled && !bInstalled) return -1
			if (!aInstalled && bInstalled) return 1
		}
		
		// Keep original order for same category
		return 0
	})
}

/**
 * Custom hook to manage and provide access to all MCP servers (custom and marketplace)
 * Automatically refreshes when extension state changes
 * Follows the same pattern as useModes hook
 */
export const useMcpServers = () => {
	const { mcpServers, marketplaceItems, marketplaceInstalledMetadata } = useExtensionState()
	const [allMcpServers, setAllMcpServers] = useState<McpServerItem[]>([])
	const [marketplaceMcpServers, setMarketplaceMcpServers] = useState<McpServerItem[]>([])
	const [customMcpServers, setCustomMcpServers] = useState<McpServerItem[]>([])
	const isMarketplaceEnabled = useMarketplaceEnabled()

	const {
		initialMarketplaceItemsLoaded,
		marketplaceFetchError,
		isMarketplaceNetworkError,
		retryMarketplaceFetch
	} = useMarketplaceFetch(isMarketplaceEnabled, "MCP")

	useEffect(() => {
		// Create array to track which servers are custom vs marketplace
		const customOrMarketplace: McpServer[] = []
		
		// All installed servers go into customOrMarketplace for now
		mcpServers.forEach(server => {
			customOrMarketplace.push(server)
		})

		// ibm_change_start: Process marketplace MCP servers (only if marketplace is enabled)
		const marketplace: McpServerItem[] = isMarketplaceEnabled ? (marketplaceItems?.flatMap(item => {
			if (item.type !== 'mcp' || !item.id) {
				return []
			}

			let data: McpServer
			const installedServer = customOrMarketplace.find(server => server.name === item.id)

			if (installedServer) {
				data = installedServer
			} else {
				data = {
					name: item.name || item.id,
					config: '',
					status: 'disconnected',
				}
			}

			if (!data.name) {
				logger.error('[MCP]: Marketplace item missing key properties', data)
				return []
			}

			const metadata: McpServerMetadata = {
				isInstalled: installedServer ? true : false,
				id: item.id,
				name: item.name,
				author: item.author,
				description: item.description,
				tags: item.tags,
			}

			return [{
				type: 'marketplace' as McpServerType,
				data,
				metaData: metadata,
			}]
		}) || []) : []

		setMarketplaceMcpServers(sortMcpServers(marketplace))

		// Custom servers are those in customOrMarketplace that aren't in marketplace
		const custom: McpServerItem[] = customOrMarketplace.flatMap(server => {
			if (marketplace.find(item => item.data.name === server.name)) {
				return []
			}
			return [{
				type: 'custom' as McpServerType,
				data: server
			}]
		}) || []

		setCustomMcpServers(custom)

		// Combine all servers: custom and marketplace (only if enabled)
		const combined = [...custom, ...(isMarketplaceEnabled ? marketplace : [])]
		setAllMcpServers(sortMcpServers(combined))
	}, [mcpServers, marketplaceItems, marketplaceInstalledMetadata, isMarketplaceEnabled])

	return {
		allMcpServers,
		marketplaceMcpServers,
		customMcpServers,
		initialMarketplaceItemsLoaded,
		marketplaceFetchError,
		isMarketplaceNetworkError,
		retryMarketplaceFetch,
		marketplaceItems,
	}
}

/**
 * Helper function to find a specific MCP server by name or marketplace ID from the servers list
 * Useful for refreshing a selected server after updates
 * Searches by both server name and marketplace item ID to handle cases where the name changes after installation
 */
export const findMcpServerByName = (allServers: McpServerItem[], name: string): McpServerItem | undefined => {
	// First try to find by exact server name match
	const byName = allServers.find(server => server.data.name === name)
	if (byName) {
		return byName
	}
	
	// If not found by name, try to find by marketplace item ID
	// This handles the case where a marketplace MCP is viewed before installation (using item.id as name)
	// and then installed (where the actual server name might be different)
	return allServers.find(server =>
		server.type === 'marketplace' && server.metaData?.id === name
	)
}

// ibm_change_start: Type guards for MCP server categories
/**
 * Check if a server is custom (user-configured)
 */
export const isCustomMcpServer = (server: McpServerItem): boolean => {
	return server.type === 'custom'
}

/**
 * Check if a server is from marketplace
 */
export const isMarketplaceMcpServer = (server: McpServerItem): boolean => {
	return server.type === 'marketplace'
}

/**
 * Check if a server can be deleted (only custom servers)
 */
export const canDeleteMcpServer = (server: McpServerItem): boolean => {
	return server.type === 'custom'
}

/**
 * Check if a server is from global configuration
 */
export const isGlobalMcpServer = (server: McpServerItem): boolean => {
	return server.data.source === 'global'
}

/**
 * Check if a server is from project configuration
 */
export const isProjectMcpServer = (server: McpServerItem): boolean => {
	return server.data.source === 'project'
}
// ibm_change_end