import React, { useMemo } from "react"
import { RotateCcw } from "lucide-react"
import { VSCodeTextArea, VSCodeTextField } from "@vscode/webview-ui-toolkit/react"
import { Input } from "@/components/ui"

/**
 * Calculate optimal number of rows for a textarea based on content newlines
 *
 * @param value - The textarea content
 * @param minRows - Minimum number of rows (default: 3)
 * @param maxRows - Maximum number of rows (undefined = unlimited, or specify a number)
 * @returns Calculated number of rows, clamped between min and max (if max is set)
 */
const calculateOptimalRows = (value: string, minRows: number = 3, maxRows?: number): number => {
	if (!value) return minRows

	// Count explicit newlines
	const newlineCount = (value.match(/\n/g) || []).length + 1

	// Apply minimum
	const rowsWithMin = Math.max(newlineCount, minRows)

	// Apply maximum if specified, otherwise unlimited
	return maxRows !== undefined ? Math.min(rowsWithMin, maxRows) : rowsWithMin
}

/**
 * FormField Component
 *
 * A reusable form field component that supports multiple input types and optional reset functionality.
 * Used across MCP, Modes, Rules, and Commands tabs for consistent form field rendering.
 *
 * Features:
 * - Multiple input types: text, VSCode text field, VSCode text area
 * - Optional reset button for reverting to default values
 * - Error and helper text display
 * - Consistent styling with VSCode theme variables
 * - Accessible labels and ARIA attributes
 *
 * @example
 * ```tsx
 * // Basic text input
 * <FormField
 *   label="Name"
 *   value={name}
 *   onChange={setName}
 *   placeholder="Enter name"
 * />
 *
 * // Textarea with dynamic sizing (auto-calculates rows based on content)
 * <FormField
 *   label="Description"
 *   value={description}
 *   onChange={setDescription}
 *   type="vscode-textarea"
 *   helperText="Provide a brief description"
 * />
 *
 * // Textarea with custom min/max rows
 * <FormField
 *   label="Role Definition"
 *   value={roleDefinition}
 *   onChange={setRoleDefinition}
 *   type="vscode-textarea"
 *   minRows={5}
 *   maxRows={20}
 *   showResetButton
 *   isModified={isModified}
 *   onReset={handleReset}
 *   resetTooltip="Reset to default"
 * />
 *
 * // Field with error
 * <FormField
 *   label="Slug"
 *   value={slug}
 *   onChange={setSlug}
 *   errorText="Slug must be unique"
 * />
 * ```
 *
 * Source Reference: ModeFormField.tsx (lines 1-129)
 */

interface FormFieldProps {
	/** Field label (required) */
	label: string
	/** Current field value (required) */
	value: string
	/** Change handler (required) */
	onChange: (value: string) => void
	/** Placeholder text */
	placeholder?: string
	/** Helper text displayed below the input */
	helperText?: string
	/** Error text displayed below the input (takes precedence over helperText) */
	errorText?: string
	/** Minimum number of rows for textarea types (default: 3) */
	minRows?: number
	/** Maximum number of rows for textarea types (undefined = unlimited) */
	maxRows?: number
	/** Input type - determines which input component to render */
	type?: "text" | "vscode-text" | "vscode-textarea"
	/** Whether to show the reset button */
	showResetButton?: boolean
	/** Whether the field has been modified from its default value */
	isModified?: boolean
	/** Reset button click handler */
	onReset?: () => void
	/** Tooltip text for the reset button */
	resetTooltip?: string
	/** Additional CSS classes */
	className?: string
	disabled?: boolean
}

export const FormField: React.FC<FormFieldProps> = ({
	label,
	value,
	onChange,
	placeholder,
	helperText,
	errorText,
	minRows = 3,
	maxRows,
	type = "text",
	showResetButton = false,
	isModified = false,
	onReset,
	resetTooltip,
	className = "",
	disabled = false,
}) => {
	// Calculate optimal rows for vscode-textarea based on content
	// This provides dynamic sizing based on content with configurable min/max bounds
	const effectiveRows = useMemo(() => {
		// For vscode-textarea type, calculate optimal rows based on content
		if (type === "vscode-textarea") {
			return calculateOptimalRows(value, minRows, maxRows)
		}

		// Default for non-textarea types (shouldn't be used but provides fallback)
		return minRows
	}, [value, type, minRows, maxRows])

	const renderInput = () => {
		switch (type) {
			case "vscode-text":
				return (
					<VSCodeTextField
						value={value}
						onInput={(e: any) => onChange(e.target.value)}
						placeholder={placeholder}
						className={`w-full rounded ${className}`}
						disabled={disabled}
					/>
				)
			case "vscode-textarea":
				return (
					<VSCodeTextArea
						value={value}
						onInput={(e: any) => onChange(e.target.value)}
						placeholder={placeholder}
						rows={effectiveRows}
						resize="vertical"
						className={`w-full rounded ${className}`}
						disabled={disabled}
					/>
				)
			case "text":
			default:
				return (
					<Input
						value={value}
						onChange={(e) => onChange(e.target.value)}
						placeholder={placeholder}
						className={`w-full rounded ${className}`}
						disabled={disabled}
					/>
				)
		}
	}
	return (
		<div className="border-b border-vscode-editor-background last:border-b-0 p-2">
			<div className="flex items-center mb-1">
				<label className="text-sm font-medium text-vscode-foreground">{label}</label>
				{showResetButton && onReset && (
					<button
						onClick={onReset}
						disabled={!isModified}
						className={`ml-2 p-1 rounded transition-colors ${
							!isModified
								? "text-vscode-descriptionForeground opacity-30 cursor-not-allowed"
								: "text-vscode-descriptionForeground hover:text-vscode-foreground hover:bg-vscode-list-hoverBackground"
						}`}
						title={resetTooltip}
						aria-label={resetTooltip}>
						<RotateCcw size={14} />
					</button>
				)}
			</div>
			{helperText && <div className="text-xs text-vscode-descriptionForeground mb-2">{helperText}</div>}
			{renderInput()}
			{errorText && <div className="text-xs text-vscode-errorForeground mt-1">{errorText}</div>}
		</div>
	)
}

