import { McpServerItem } from "../types"

/**
 * Configuration for a single badge display
 */
export interface BadgeConfig {
	text: string
	className: string
}

/**
 * Complete badge configuration for an MCP server
 */
export interface McpServerBadges {
	statusBadge: BadgeConfig | null
	scopeBadge: BadgeConfig | null
	statusText: string | undefined
	statusColor: string
}

/**
 * Translation function type for i18n support
 */
type TranslateFunction = (key: string) => string

/**
 * Get all badge configurations for an MCP server item.
 * Centralizes badge logic for consistent display across components.
 * 
 * @param serverItem - The MCP server item to generate badges for
 * @param t - Translation function for i18n
 * @param isMarketplaceEnabled - Whether marketplace feature is enabled
 * @returns Complete badge configuration including status badge, scope badge, status text, and status color
 * 
 * @example
 * ```typescript
 * const { statusBadge, scopeBadge, statusText, statusColor } = getMcpServerBadges(
 *   serverItem,
 *   t,
 *   isMarketplaceEnabled
 * )
 * ```
 */
export function getMcpServerBadges(
	serverItem: McpServerItem,
	t: TranslateFunction,
	isMarketplaceEnabled: boolean
): McpServerBadges {
	const isMarketplaceItem = serverItem.type === "marketplace"
	const isInstalled = serverItem?.metaData?.isInstalled

	const statusBadge = getStatusBadge(serverItem, t)
	const scopeBadge = getScopeBadge(serverItem, t)
	const statusText = getStatusText(t, isMarketplaceItem, isInstalled, isMarketplaceEnabled, scopeBadge)
	const statusColor = getStatusColor(serverItem)

	return { statusBadge, scopeBadge, statusText, statusColor }
}

/**
 * Get the status badge for an MCP server (connected/connecting/disconnected/disabled).
 * 
 * @param serverItem - The MCP server item
 * @param t - Translation function
 * @returns Badge configuration or null if no badge should be shown
 * 
 * @example
 * ```typescript
 * const statusBadge = getStatusBadge(serverItem, t)
 * // Returns: { text: "Connected", className: "bg-[#198038]/20 text-[#42be65]" }
 * ```
 */
export function getStatusBadge(
	serverItem: McpServerItem,
	t: TranslateFunction
): BadgeConfig | null {
	// Disabled servers should show disabled status
	if (serverItem.data.disabled) {
		return {
			text: t("ibmSettings:mcp.status.disabled"),
			className: "bg-[rgba(0,0,0,0.1)] text-vscode-descriptionForeground",
		}
	}

	switch (serverItem.data.status) {
		case "connected":
			return {
				text: t("ibmSettings:mcp.status.connected"),
				className: "bg-[#198038]/20 text-[#42be65]",
			}
		case "connecting":
			return {
				text: t("ibmSettings:mcp.status.connecting"),
				className: "bg-[#f1c21b]/20 text-[#f1c21b]",
			}
		case "disconnected":
			return {
				text: t("ibmSettings:mcp.status.disconnected"),
				className: "bg-[#da1e28]/20 text-[#fa4d56]",
			}
	}

	return null
}

/**
 * Get the scope badge for an MCP server (global or project).
 * 
 * @param serverItem - The MCP server item
 * @param t - Translation function
 * @returns Badge configuration or null if no scope badge should be shown
 * 
 * @example
 * ```typescript
 * const scopeBadge = getScopeBadge(serverItem, t)
 * // Returns: { text: "Global", className: "bg-[#0f62fe]/10 text-[#78a9ff] text-[9px]" }
 * ```
 */
export function getScopeBadge(
	serverItem: McpServerItem,
	t: TranslateFunction
): BadgeConfig | null {
	if (serverItem.data.source === "global") {
		return {
			text: t("ibmSettings:shared.badges.global"),
			className: "bg-[#0f62fe]/10 text-[#78a9ff] text-[9px]",
		}
	}

	if (serverItem.data.source === "project") {
		return {
			text: t("ibmSettings:shared.badges.project"),
			className: "bg-[#8a3ffc]/10 text-[#be95ff] text-[9px]",
		}
	}

	return null
}

/**
 * Get the status text that combines badge information.
 * Used for displaying MCP server status in a single text string.
 * 
 * @param t - Translation function
 * @param isMarketplaceItem - Whether this is a marketplace MCP server
 * @param isInstalled - Whether the marketplace MCP server is installed
 * @param isMarketplaceEnabled - Whether marketplace feature is enabled
 * @param scopeBadge - The scope badge configuration
 * @returns Status text string or undefined
 * 
 * @example
 * ```typescript
 * const statusText = getStatusText(t, true, true, true, scopeBadge)
 * // Returns: "Installed / Global"
 * ```
 */
export function getStatusText(
	t: TranslateFunction,
	isMarketplaceItem: boolean,
	isInstalled: boolean | undefined,
	isMarketplaceEnabled: boolean,
	scopeBadge: BadgeConfig | null
): string | undefined {
	// For installed marketplace servers, show "Installed / scope"
	if (isMarketplaceItem && isInstalled && isMarketplaceEnabled) {
		return `${t("ibmSettings:shared.badges.installed")} / ${scopeBadge?.text || t("ibmSettings:shared.badges.global")}`
	}

	// For marketplace servers that are not installed, don't show status text
	// (they will show the Install button instead)
	if (isMarketplaceItem && !isInstalled && isMarketplaceEnabled) {
		return undefined
	}

	// For custom servers, show just the scope badge
	if (!isMarketplaceItem && scopeBadge) {
		return `${t("ibmSettings:modes.badge_custom")} / ${scopeBadge.text}`
	}

	return undefined
}

/**
 * Get the status color for an MCP server based on its connection status.
 * Uses VSCode theme variables for consistent theming.
 * 
 * @param serverItem - The MCP server item
 * @returns CSS color variable string
 * 
 * @example
 * ```typescript
 * const color = getStatusColor(serverItem)
 * // Returns: "var(--vscode-testing-iconPassed)" for connected servers
 * ```
 */
export function getStatusColor(serverItem: McpServerItem): string {
	// Disabled servers should always show grey regardless of connection status
	if (serverItem.data.disabled) {
		return "var(--vscode-descriptionForeground)"
	}

	switch (serverItem.data.status) {
		case "connected":
			return "var(--vscode-testing-iconPassed)"
		case "connecting":
			return "var(--vscode-charts-yellow)"
		case "disconnected":
			return "var(--vscode-testing-iconFailed)"
		default:
			return "var(--vscode-descriptionForeground)"
	}
}

