import React from "react"
import { Search, X } from "lucide-react"
import { useAppTranslation } from "@/i18n/TranslationContext"
import { StandardTooltip } from "@/components/ui"
import { useSettingsSearch } from "./context/SettingsSearchContext"

const isMac = navigator.platform.toUpperCase().indexOf("MAC") >= 0

interface SettingsHeaderProps {
	onDone?: () => void
}

const SettingsHeader: React.FC<SettingsHeaderProps> = () => {
	const { t } = useAppTranslation()
	const { searchQuery, setSearchQuery, isSearchActive, totalResults, searchInputRef, clearSearch } =
		useSettingsSearch()

	// Handle keyboard shortcut display based on platform
	const shortcutHint = isMac ? "⌘F" : "Ctrl+F"

	return (
		<div className="flex items-center gap-3 mb-4 pr-2">
			{/* Search Input Container - spans full width */}
			<div className="relative flex-1">
				{/* Search Icon */}
				<Search
					size={16}
					className="absolute left-3 top-1/2 -translate-y-1/2 text-vscode-input-placeholderForeground pointer-events-none"
				/>

				{/* Search Input */}
				<input
					ref={searchInputRef}
					type="text"
					placeholder={t("ibmSettings:search.placeholder")}
					value={searchQuery}
					onChange={(e) => setSearchQuery(e.target.value)}
					className="w-full h-[34px] pl-10 pr-28 bg-vscode-input-background text-vscode-input-foreground border border-vscode-input-border rounded-md text-[13px] placeholder:text-vscode-input-placeholderForeground focus:outline-none focus:border-vscode-focusBorder focus:ring-1 focus:ring-vscode-focusBorder transition-all"
					aria-label={t("ibmSettings:search.ariaLabel")}
				/>

				{/* Right side: Results count + Clear button */}
				<div className="absolute right-3 top-1/2 -translate-y-1/2 flex items-center gap-2">
					{/* Results count */}
					{isSearchActive && (
						<span className="text-[11px] text-vscode-descriptionForeground whitespace-nowrap px-1.5 py-0.5 bg-vscode-badge-background rounded">
							{totalResults === 0
								? t("ibmSettings:search.noResults")
								: t("ibmSettings:search.resultsCount", { count: totalResults })}
						</span>
					)}

					{/* Clear button */}
					{isSearchActive && (
						<StandardTooltip content={t("ibmSettings:search.clear")}>
							<button
								onClick={clearSearch}
								className="p-1 text-vscode-descriptionForeground hover:text-vscode-foreground transition-colors rounded-md hover:bg-vscode-toolbar-hoverBackground"
								aria-label={t("ibmSettings:search.clear")}>
								<X size={14} />
							</button>
						</StandardTooltip>
					)}

					{/* Keyboard shortcut hint (only when not searching) */}
					{!isSearchActive && (
						<span className="text-[11px] text-vscode-descriptionForeground opacity-50 font-mono">
							{shortcutHint}
						</span>
					)}
				</div>
			</div>
		</div>
	)
}

export default SettingsHeader

