import { ConditionDefinition, ConditionOperator } from "../components/actions"
import { getNestedValue } from "@/ibm/utils/getNestedValue"

/**
 * Evaluates a condition against the provided state
 * Supports nested property paths using dot notation (e.g., "featureFlags.llm-attribution-enabled")
 * @param condition The condition to evaluate
 * @param state The state to evaluate against
 * @returns True if the condition is met, false otherwise
 */
export const evaluateCondition = (condition: ConditionDefinition | undefined, state: any): boolean => {
	if (!condition) return true

	const { property, value, operator = ConditionOperator.EQUALS } = condition
	// Support nested property paths using dot notation
	const stateValue = getNestedValue(state, property)

	switch (operator) {
		case ConditionOperator.EQUALS:
			return stateValue === value
		case ConditionOperator.NOT_EQUALS:
			return stateValue !== value
		case ConditionOperator.GREATER_THAN:
			return stateValue > value
		case ConditionOperator.LESS_THAN:
			return stateValue < value
		case ConditionOperator.CONTAINS:
			return Array.isArray(stateValue) && stateValue.includes(value)
		default:
			return true
	}
}
