import * as React from "react"
import { Slider as UISlider } from "@/components/ui"
import { useAppTranslation } from "@/i18n/TranslationContext"

export interface SliderProps {
	/** Current slider value */
	value: number
	/** Callback when slider value changes */
	setValue: (value: number) => void
	/** Minimum allowed value */
	min?: number
	/** Maximum allowed value */
	max?: number
	/** Step value for the slider */
	step?: number
	/** Whether to show the current value */
	showValue?: boolean
	/** Label for the slider value */
	valueLabel?: string
	/** Format for displaying the value - can be a function or a string template with {value} placeholder */
	valueFormat?: ((value: number) => string) | string
	/** Label for the slider (translation key) */
	label?: string
	/** Description for the slider (translation key) */
	description?: string
	/** Whether the component is disabled */
	disabled?: boolean
	/** CSS class name to apply to the component */
	className?: string
	/** Test ID for the component */
	testId?: string
}

/**
 * Pure Slider component for settings
 * Receives value and setValue props from wrapper components
 * This component is state-agnostic and can be used with any state management approach
 */
const Slider: React.FC<SliderProps> = ({
	value,
	setValue,
	min = 0,
	max = 100,
	step = 1,
	showValue = true,
	valueFormat,
	disabled = false,
	testId,
	className,
	label,
	description,
}) => {
	const { t } = useAppTranslation()

	// Handle slider change
	const handleChange = (values: number[]) => {
		setValue(values[0])
	}

	// Format the value for display
	const formattedValue = React.useMemo(() => {
		if (valueFormat) {
			if (typeof valueFormat === "function") {
				return valueFormat(value)
			} else if (typeof valueFormat === "string") {
				return valueFormat.replace("{value}", value.toString())
			}
		}
		return `${value}`
	}, [value, valueFormat])

	return (
		<div className="flex flex-col gap-1">
			{label && <label className="block text-sm font-medium mb-1">{t(label)}</label>}
			<div className="flex items-center gap-2">
				<UISlider
					min={min}
					max={max}
					step={step}
					value={[value]}
					onValueChange={handleChange}
					disabled={disabled}
					className={className}
					data-testid={testId}
				/>
				{showValue && <span className="w-20">{formattedValue}</span>}
			</div>
			{description && <div className="text-vscode-descriptionForeground text-sm mt-1">{t(description)}</div>}
		</div>
	)
}

export default Slider

