import React, { useState } from "react"
import { useAppTranslation } from "@/i18n/TranslationContext"
import { ActionComponentDefinition } from "../SettingsDefinition"
import { CustomComponentsRegistry } from "./actions/CustomComponentsRegistry"
import { VSCodeButton } from "@vscode/webview-ui-toolkit/react"
import { StandardTooltip } from "@/components/ui"

interface SectionHeaderProps {
	title: string | React.ReactNode
	description?: string | ActionComponentDefinition | React.ReactNode
	collapsible?: boolean
	defaultCollapsed?: boolean
	onCollapseChange?: (collapsed: boolean) => void
}

/**
 * Renders an action component based on its type and props
 */
const renderActionComponent = (actionComponent: ActionComponentDefinition): React.ReactNode => {
	if (!actionComponent) return null

	const { type, props } = actionComponent

	// For custom components, use the registry
	if (type === "custom" && props && "componentName" in props) {
		return CustomComponentsRegistry.render(props.componentName as string, {
			...props,
			...((props as any).additionalProps || {}),
		})
	}

	console.warn(`SectionHeader only supports custom action components, got: ${type}`)
	return null
}

const SectionHeader: React.FC<SectionHeaderProps> = ({
	title,
	description,
	collapsible = false,
	defaultCollapsed = false,
	onCollapseChange
}) => {
	const { t } = useAppTranslation()
	const [isCollapsed, setIsCollapsed] = useState(defaultCollapsed)

	// Handle description - can be a string (translation ID), a custom component definition, or ReactNode
	const renderDescription = () => {
		if (!description) return null

		// Check if description is a custom component definition
		if (typeof description === "object" && "type" in description) {
			return renderActionComponent(description as ActionComponentDefinition)
		}

		// If it's a string, treat as translation ID
		if (typeof description === "string") {
			return t(description)
		}

		// Otherwise it's a ReactNode, return as-is
		return description
	}

	const handleToggleCollapse = () => {
		const newCollapsedState = !isCollapsed
		setIsCollapsed(newCollapsedState)
		onCollapseChange?.(newCollapsedState)
	}

	const renderedDescription = renderDescription()

	return (
		<div className="min-h-10 border-b border-vscode-editor-background last:border-b-0">
			<div className="flex justify-between items-center p-2 gap-2">
				<div className="flex-1">
					<div className="text-sm font-medium">{title}</div>
					{renderedDescription ? (
						<div className="text-vscode-descriptionForeground text-sm">{renderedDescription}</div>
					) : null}
				</div>
				{collapsible && (
					<StandardTooltip content={isCollapsed ? t("common:actions.expand") : t("common:actions.collapse")}>
						<VSCodeButton
							appearance="icon"
							onClick={handleToggleCollapse}
							aria-label={isCollapsed ? t("common:actions.expand") : t("common:actions.collapse")}
						>
							<span className={`codicon ${isCollapsed ? 'codicon-chevron-right' : 'codicon-chevron-down'}`} />
						</VSCodeButton>
					</StandardTooltip>
				)}
			</div>
		</div>
	)
}

export { SectionHeader }
export default SectionHeader
