import React, { useMemo } from "react"
import { useAppTranslation } from "@/i18n/TranslationContext"
import { useExtensionState } from "@/context/ExtensionStateContext"
import { Button } from "@/components/ui/button"
import { vscode } from "@/utils/vscode"
import { getPlanDisplayName } from "@roo/IBM/userProfileHelpers"
import { ENTERPRISE_PLAN_ID } from "@/ibm/constants"

/**
 * Custom component for displaying plan information
 * Shows subscription plan and manage subscription button
 * Only renders if plan information is available
 */
const PlanSection: React.FC = () => {
	const { t } = useAppTranslation()
	const { featureFlags, activeProfile } = useExtensionState()

	const manageSubscriptionUrl = useMemo(() => {
		return featureFlags?.["manage-subscription-url"]
	}, [featureFlags])

	const isEnterprisePlan = useMemo(() => {
		return activeProfile?.plan === ENTERPRISE_PLAN_ID
	}, [activeProfile?.plan])

	// Don't render if no plan information is available or internal
	if (activeProfile?.is_internal || !activeProfile?.plan) {
		return null
	}

	return (
		<tr className="h-6 border-y border-vscode-editor-background">
			<td className="py-4 pl-2 text-sm font-medium w-auto whitespace-nowrap">{t("ibmSettings:general.plan")}</td>
			<td className="pl-4 pr-2 text-sm font-medium text-left w-full">
				<div className="flex items-center justify-between">
					<div className="text-sm font-medium">
						<span>{getPlanDisplayName(activeProfile)}</span>
					</div>

					{manageSubscriptionUrl && !isEnterprisePlan && (
						<Button
							variant="outline"
							onClick={() => vscode.postMessage({ type: "openExternal", url: manageSubscriptionUrl })}>
							{t("ibmSettings:general.manageSubscription")}
						</Button>
					)}
				</div>
			</td>
		</tr>
	)
}

export default PlanSection

