import React, { useState } from "react"
import { useAppTranslation } from "@/i18n/TranslationContext"
import { vscode } from "@src/utils/vscode"
import { X } from "lucide-react"
import { Button, Input } from "@/components/ui"
import { useExtensionState } from "@/context/ExtensionStateContext"

interface CommandListProps {
	title: string
	description: string
	commands: string[]
	inputValue: string
	setInputValue: (value: string) => void
	placeholder: string
	handleAdd: () => void
	handleRemove: (index: number) => void
	testIdPrefix: string
}

const CommandList: React.FC<CommandListProps> = ({
	title,
	description,
	commands,
	inputValue,
	setInputValue,
	placeholder,
	handleAdd,
	handleRemove,
	testIdPrefix,
}) => {
	const { t } = useAppTranslation()

	return (
		<>
			<div className={testIdPrefix !== "allowed" ? "mt-3" : ""}>
				<label className="block font-medium" data-testid={`${testIdPrefix}-commands-heading`}>
					{title}
				</label>
				<div className="text-vscode-descriptionForeground text-sm">{description}</div>
			</div>

			<div className="flex gap-2">
				<Input
					value={inputValue}
					onChange={(e: any) => setInputValue(e.target.value)}
					onKeyDown={(e: any) => {
						if (e.key === "Enter") {
							e.preventDefault()
							handleAdd()
						}
					}}
					placeholder={placeholder}
					className="grow h-6 text-sm"
					data-testid={`${testIdPrefix}-command-input`}
				/>
				<Button className="h-6 text-sm" onClick={handleAdd} data-testid={`add-${testIdPrefix}-command-button`}>
					{t("ibmSettings:tools.execute.addButton")}
				</Button>
			</div>

			<div className="flex flex-wrap gap-2">
				{(commands ?? []).map((cmd, index) => (
					<Button
						key={index}
						className="p-1"
						variant="secondary"
						data-testid={`remove-${testIdPrefix}-command-${index}`}
						onClick={() => handleRemove(index)}>
						<div className="flex flex-row items-center gap-1 text-sm">
							<div>{cmd}</div>
							<X className="text-foreground scale-75" />
						</div>
					</Button>
				))}
			</div>
		</>
	)
}

const CommandsSection: React.FC = () => {
	const { t } = useAppTranslation()
	const { allowedCommands = [], deniedCommands = [] } = useExtensionState()

	const [commandInput, setCommandInput] = useState("")
	const [deniedCommandInput, setDeniedCommandInput] = useState("")

	const handleAddAllowedCommand = () => {
		const currentCommands = allowedCommands ?? []

		if (commandInput && !currentCommands.includes(commandInput)) {
			const newCommands = [...currentCommands, commandInput]
			setCommandInput("")
			vscode.postMessage({ type: "allowedCommands", commands: newCommands })
		}
	}

	const handleAddDeniedCommand = () => {
		const currentCommands = deniedCommands ?? []

		if (deniedCommandInput && !currentCommands.includes(deniedCommandInput)) {
			const newCommands = [...currentCommands, deniedCommandInput]
			setDeniedCommandInput("")
			vscode.postMessage({ type: "deniedCommands", commands: newCommands })
		}
	}

	const handleRemoveAllowedCommand = (index: number) => {
		const newCommands = (allowedCommands ?? []).filter((_, i) => i !== index)
		vscode.postMessage({ type: "allowedCommands", commands: newCommands })
	}

	const handleRemoveDeniedCommand = (index: number) => {
		const newCommands = (deniedCommands ?? []).filter((_, i) => i !== index)
		vscode.postMessage({ type: "deniedCommands", commands: newCommands })
	}

	return (
		<div className="flex flex-col gap-2">
			<CommandList
				title={t("ibmSettings:tools.execute.allowedCommands")}
				description={t("ibmSettings:tools.execute.allowedCommandsDescription")}
				commands={allowedCommands}
				inputValue={commandInput}
				setInputValue={setCommandInput}
				placeholder={t("ibmSettings:tools.execute.commandPlaceholder")}
				handleAdd={handleAddAllowedCommand}
				handleRemove={handleRemoveAllowedCommand}
				testIdPrefix="allowed"
			/>

			<CommandList
				title={t("ibmSettings:tools.execute.deniedCommands")}
				description={t("ibmSettings:tools.execute.deniedCommandsDescription")}
				commands={deniedCommands}
				inputValue={deniedCommandInput}
				setInputValue={setDeniedCommandInput}
				placeholder={t("ibmSettings:tools.execute.deniedCommandPlaceholder")}
				handleAdd={handleAddDeniedCommand}
				handleRemove={handleRemoveDeniedCommand}
				testIdPrefix="denied"
			/>
		</div>
	)
}

export default CommandsSection

