import React from "react"
import { LucideIcon } from "lucide-react"
import { cn } from "../../../../lib/utils"
import { CarbonIconType } from "@carbon/icons-react"

interface SettingsSidebarItemProps {
	icon: LucideIcon | CarbonIconType
	label: string
	isActive: boolean
	onClick: () => void
	/** Number of search matches in this tab (0 = no matches, undefined = not searching) */
	matchCount?: number
	/** Whether search is currently active */
	isSearching?: boolean
}

const SettingsSidebarItem: React.FC<SettingsSidebarItemProps> = ({
	icon: Icon,
	label,
	isActive,
	onClick,
	matchCount,
	isSearching = false,
}) => {
	// Dim the item when searching and there are no matches
	const hasNoMatches = isSearching && matchCount === 0

	return (
		<button
			className={cn(
				"whitespace-nowrap overflow-hidden min-w-0 px-2 py-2 box-border flex items-center rounded-md opacity-70 hover:bg-vscode-list-hoverBackground hover:text-vscode-editor-foreground w-full text-left cursor-pointer transition-opacity",
				isActive &&
					"opacity-100 border-vscode-focusBorder bg-vscode-list-activeSelectionBackground text-vscode-list-activeSelectionForeground",
				hasNoMatches && "opacity-30",
			)}
			onClick={onClick}
		>
			<div className="flex items-center gap-2 flex-1 min-w-0">
				<div className="flex items-center justify-center h-5 flex-shrink-0">
					<Icon className="w-4 h-4" />
				</div>
				<span className="text-[13px] font-medium truncate">{label}</span>
				{/* Match count badge */}
				{isSearching && matchCount !== undefined && matchCount > 0 && (
					<span className="ml-auto flex-shrink-0 text-[10px] bg-vscode-badge-background text-vscode-badge-foreground px-1.5 py-0.5 rounded-full min-w-[18px] text-center">
						{matchCount}
					</span>
				)}
			</div>
		</button>
	)
}

export default SettingsSidebarItem

