import React, { useState, useMemo, useCallback } from "react"
import { Plus, Download, Loader2 } from "lucide-react"
import { useAppTranslation } from "@/i18n/TranslationContext"
import { useExtensionState } from "@/context/ExtensionStateContext"
import { MarketplaceItem } from "@roo-code/types"
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue, StandardTooltip, Button } from "@/components/ui"
import { SearchInput } from "@/ibm/components/common/SearchInput"
import { ModeTile } from "./ModeTile"
import { vscode } from "@/utils/vscode"
import { logger } from "@/ibm/utils/logger"
import { ModeInstallModal, useMarketplaceFilterReset } from "@/ibm/components/settings/components/marketplace"
import { MarketplaceLoadingState } from "@/ibm/components/settings/components/MarketplaceLoadingState"
import { useModes, ModeItem } from "./hooks/useModes"
import { EditModeModal } from "./EditModeModal"
import { findMarketplaceItem } from "./modeUtils"
import { useModal } from "../../../../hooks/useModal"
import { saveModeChanges } from "./modeOperations"
import { useMarketplaceEnabled } from "./hooks/useMarketplaceEnabled" // ibm_change

type FilterType = "all" | "installed" | "not-installed" | "global" | "project" | "marketplace" | "custom" | "built-in"

interface ModesOverviewGridProps {
	onModeSelect?: (mode: ModeItem) => void
}

/**
 * ModesOverviewGrid Component
 *
 * Displays a grid of mode tiles with search, filter, and action capabilities.
 * Shows both custom-created modes and marketplace modes from the API.
 */
export const ModesOverviewGrid: React.FC<ModesOverviewGridProps> = ({ onModeSelect }) => {
	const { t } = useAppTranslation()
	const { cwd } = useExtensionState()
	const {
		allModes,
		builtInModes,
		marketplaceModes,
		customModes,
		initialMarketplaceItemsLoaded,
		marketplaceFetchError,
		isMarketplaceNetworkError,
		retryMarketplaceFetch, // ibm_change: Get retry function from hook
		marketplaceItems
	} = useModes()
	// ibm_change: Check if marketplace is enabled
	const isMarketplaceEnabled = useMarketplaceEnabled()
	
	// Local state
	const [searchQuery, setSearchQuery] = useState("")
	const [filterType, setFilterType] = useState<FilterType>("all")
	
	// Modal state management using useModal hook
	const installModal = useModal<MarketplaceItem>()
	const createModal = useModal<ModeItem>()

	// ibm_change: Use shared hook for marketplace filter reset
	useMarketplaceFilterReset(
		isMarketplaceEnabled,
		filterType,
		setFilterType,
		["marketplace", "installed", "not-installed"]
	)

	// Filter and search logic
	const filteredModes = useMemo(() => {
		let modes: ModeItem[] = []

		if (filterType === "all") {
			modes = allModes
		} else if (filterType === "installed") {
			modes = marketplaceModes.filter(m => m.metaData?.isInstalled)
		} else if (filterType === "marketplace") {
			modes = marketplaceModes
		} else if (filterType === "custom") {
			modes = customModes
		} else if (filterType === "built-in") {
			modes = builtInModes
		} else if (filterType === "not-installed") {
			modes = marketplaceModes.filter(m => !m.metaData?.isInstalled)
		} else if (filterType === "global") {
			modes = allModes.filter(m =>
				m.data.source === 'global' &&
				(m.type !== 'marketplace' || m.metaData?.isInstalled)
			)
		} else if (filterType === "project") {
			modes = allModes.filter(m =>
				m.data.source === 'project' &&
				(m.type !== 'marketplace' || m.metaData?.isInstalled)
			)
		}

		// Apply search filter
		if (searchQuery.trim()) {
			const query = searchQuery.toLowerCase()
			modes = modes.filter((m) => {
				return m.data.slug.toLowerCase().includes(query) ||
				m.data.name.toLowerCase().includes(query) ||
				m.data.description?.toLowerCase().includes(query) ||
				m?.metaData?.tags?.some(t => t.toLowerCase().includes(query)) ||
				m?.metaData?.author?.toLowerCase().includes(query)
			})
		}
		return modes
	}, [allModes, builtInModes, customModes, filterType, marketplaceModes, searchQuery])

	const handleImport = () => {
		vscode.postMessage({
			type: "importMode",
		})
	}

	const handleCreateNew = () => {
		// Create an empty mode for the user to fill in
		const emptyMode: ModeItem = {
			type: "custom",
			data: {
				slug: "",
				name: "",
				roleDefinition: "",
				description: "",
				whenToUse: "",
				customInstructions: "",
				groups: [],
				source: "global",
			},
			metaData: {
				tags: [],
			},
		}
		createModal.open(emptyMode)
	}

	const handleSaveNewMode = (updatedMode: ModeItem) => {
		// For new modes, pass the same mode as both original and updated
		// The service will handle it as a custom mode creation
		saveModeChanges(updatedMode, updatedMode, t, {
			cwd,
			onSuccess: () => {
				createModal.close()
			},
			onError: (error: Error) => {
				console.error(error.message)
				// TODO: Show error notification to user
			},
		})
	}

	const handleCancelCreateMode = () => {
		createModal.close()
	}

	// Mode tile action handlers
	const handleModeClick = useCallback(
		(mode: ModeItem) => {
			// Navigate to mode details view
			if (onModeSelect) {
				onModeSelect(mode)
			}
		},
		[onModeSelect]
	)

	const handleInstall = useCallback((mode: ModeItem) => {
		// Install marketplace mode - find the original MarketplaceItem and show modal
		const marketplaceItem = findMarketplaceItem(mode.metaData?.id, marketplaceItems)
		
		if (marketplaceItem) {
			logger.info('Opening install modal for marketplace mode', { marketplaceItemId: marketplaceItem.id })
			installModal.open(marketplaceItem)
		} else {
			logger.error('Could not find marketplace item for mode', { modeId: mode.metaData?.id })
		}
	}, [marketplaceItems, installModal])

	return (
		<div className="flex flex-col gap-1">
			{/* Toolbar: Search, Filter, and Actions */}
			<div className="flex items-center gap-2 mb-1">
				{/* Search Input */}
				<SearchInput
					value={searchQuery}
					onChange={setSearchQuery}
					placeholder={t("ibmSettings:modes.search_placeholder")}
					clearTooltip={t("ibmSettings:mcp.clear_search")}
					className="flex-1"
				/>

				{/* Filter Dropdown */}
				<Select value={filterType} onValueChange={(value) => setFilterType(value as FilterType)}>
					<SelectTrigger className="bg-vscode-dropdown-background border-vscode-dropdown-border text-[11px] min-w-[100px]">
						<SelectValue />
					</SelectTrigger>
					<SelectContent>
						<SelectItem value="all">{t("ibmSettings:shared.filters.all")}</SelectItem>
						<SelectItem value="built-in">{t("ibmSettings:modes.filter_built_in")}</SelectItem>
						<SelectItem value="global">{t("ibmSettings:modes.filter_global")}</SelectItem>
						<SelectItem value="project">{t("ibmSettings:modes.filter_project")}</SelectItem>
						{/* ibm_change_start: Only show marketplace filters when marketplace is enabled */}
						{isMarketplaceEnabled && (
							<>
								<SelectItem value="installed">{t("common:status.installed")}</SelectItem>
								<SelectItem value="not-installed">{t("common:status.not_installed")}</SelectItem>
								<SelectItem value="marketplace">{t("ibmSettings:shared.filters.marketplace")}</SelectItem>
							</>
						)}
						{/* ibm_change_end */}
					</SelectContent>
				</Select>

				{/* Action Icons */}
				<div className="flex items-center gap-0">
					<StandardTooltip content={t("ibmSettings:actions.create_new_mode")}>
						<Button
							variant="ghost"
							size="icon"
							onClick={handleCreateNew}
						>
							<Plus className="h-4 w-4" />
						</Button>
					</StandardTooltip>
					<StandardTooltip content={t("common:actions.import")}>
						<Button
							variant="ghost"
							size="icon"
							onClick={handleImport}
						>
							<Download className="h-4 w-4" />
						</Button>
					</StandardTooltip>
				</div>
			</div>

			{/* Main Modes Grid - Always show when filter is not "all" or when searching */}
			<div className="flex flex-col">
				{/* Modes Grid */}
				{filteredModes.length > 0 && (
					<div className="grid grid-cols-1 [@media(min-width:600px)]:grid-cols-2 [@media(min-width:848px)]:grid-cols-3 gap-2">
						{filteredModes.map((item) => {
							const modeSlug = item.data.slug
							const modeId = item?.metaData?.id

							return (
								<ModeTile
									key={modeId || modeSlug}
									modeItem={item}
									onClick={() => handleModeClick(item)}
									onInstall={item.type === "marketplace" ? () => handleInstall(item) : undefined}
								/>
							)
						})}
					</div>
				)}
				
				{/* Empty State */}
				{filteredModes.length === 0 && (
					<div className="text-center py-12 text-vscode-descriptionForeground">
						{/* ibm_change_start: Only show marketplace loading when marketplace is enabled and loading */}
						{isMarketplaceEnabled &&
						 !initialMarketplaceItemsLoaded &&
						 (filterType === "marketplace" || filterType === "installed" || filterType === "not-installed") ? (
							<div className="flex flex-col items-center gap-3">
								<Loader2 className="h-6 w-6 animate-spin text-vscode-descriptionForeground" />
								<p className="text-sm">{t("common:status.loading")}</p>
							</div>
						) : (
							<p className="text-sm">
								{searchQuery
									? t("common:status.no_results")
									: t("ibmSettings:modes.no_modes")}
							</p>
						)}
						{/* ibm_change_end */}
					</div>
				)}
				
				{/* ibm_change_start: Loading and error states below tiles when marketplace is enabled */}
				{isMarketplaceEnabled && filteredModes.length > 0 && (
					<MarketplaceLoadingState
						isLoading={!initialMarketplaceItemsLoaded}
						hasError={marketplaceFetchError}
						isMarketplaceNetworkError={isMarketplaceNetworkError}
						onRetry={() => {
							retryMarketplaceFetch()
							vscode.postMessage({ type: "retryMarketplaceConnection" })
						}}
					/>
				)}
				{/* ibm_change_end */}
			</div>

			{/* Install Modal - Only render when needed */}
			{installModal.isOpen && installModal.data && installModal.data.type === "mode" && (
				<ModeInstallModal
					item={installModal.data}
					isOpen={installModal.isOpen}
					onClose={installModal.close}
					hasWorkspace={!!cwd}
				/>
			)}
	
			{/* Create Mode Modal - Only render when needed */}
			{createModal.isOpen && createModal.data && (
				<EditModeModal
					isOpen={createModal.isOpen}
					mode={createModal.data}
					onSave={handleSaveNewMode}
					onCancel={handleCancelCreateMode}
					allModes={allModes}
				/>
			)}
		</div>
	)
}

