import React from "react"
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select"

/**
 * SelectField Component
 *
 * A generic dropdown/select component that follows FormField styling patterns.
 * Can be used across marketplace, modes, and other settings tabs for consistent dropdown UI.
 *
 * Features:
 * - FormField-like wrapper structure with consistent borders and padding
 * - Uses common shadcn Select component
 * - VSCode theme integration
 * - Optional helper text
 * - Generic enough for any dropdown use case
 *
 * @example
 * ```tsx
 * // Method selection
 * <SelectField
 *   label="Installation Method"
 *   value={selectedIndex}
 *   options={[
 *     { label: "NPM", value: 0 },
 *     { label: "Docker", value: 1 }
 *   ]}
 *   onChange={setSelectedIndex}
 *   helperText="Choose your preferred installation method"
 * />
 * ```
 */

interface SelectFieldProps {
	/** Field label (required) */
	label: string
	/** Current selected value (required) */
	value: string | number
	/** Array of options with label and value (required) */
	options: Array<{ label: string; value: string | number }>
	/** Change handler (required) */
	onChange: (value: string | number) => void
	/** Optional helper text displayed below the label */
	helperText?: string
}

export const SelectField: React.FC<SelectFieldProps> = ({
	label,
	value,
	options,
	onChange,
	helperText,
}) => {
	return (
		<div className="border-b border-vscode-editor-background last:border-b-0 p-2">
			<label className="text-sm font-medium text-vscode-foreground mb-1 block">
				{label}
			</label>
			{helperText && (
				<div className="text-xs text-vscode-descriptionForeground mb-2">
					{helperText}
				</div>
			)}
			<Select
				value={String(value)}
				onValueChange={(newValue) => {
					// Try to preserve the original type (number or string)
					const parsedValue = isNaN(Number(newValue)) ? newValue : Number(newValue)
					onChange(parsedValue)
				}}
			>
				<SelectTrigger className="w-full">
					<SelectValue />
				</SelectTrigger>
				<SelectContent>
					{options.map((option) => (
						<SelectItem key={String(option.value)} value={String(option.value)}>
							{option.label}
						</SelectItem>
					))}
				</SelectContent>
			</Select>
		</div>
	)
}

