import * as React from "react"
import { Input } from "@/components/ui"

export interface TextInputProps {
	/** Current input value */
	value: string
	/** Callback when input value changes */
	setValue: (value: string) => void
	/** Placeholder text */
	placeholder?: string
	/** Maximum length of the input */
	maxLength?: number
	/** Pattern for validation */
	pattern?: string
	/** Debounce delay in milliseconds */
	debounceMs?: number
	/** Whether the component is disabled */
	disabled?: boolean
	/** CSS class name to apply to the component */
	className?: string
	/** Test ID for the component */
	testId?: string
}

/**
 * Pure TextInput component for settings
 * Receives value and setValue props from wrapper components
 * This component is state-agnostic and can be used with any state management approach
 */
const TextInput: React.FC<TextInputProps> = ({
	value,
	setValue,
	placeholder,
	disabled = false,
	testId,
	className,
	maxLength,
	pattern,
	debounceMs = 300,
}) => {
	// Local state for the input value (for debouncing)
	const [inputValue, setInputValue] = React.useState(value)

	// Update local state when prop value changes
	React.useEffect(() => {
		setInputValue(value)
	}, [value])

	// Debounce timer ref
	const debounceTimerRef = React.useRef<NodeJS.Timeout | null>(null)

	// Handle input change
	const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
		const newValue = e.target.value
		setInputValue(newValue)

		// Clear existing timer
		if (debounceTimerRef.current) {
			clearTimeout(debounceTimerRef.current)
		}

		// Set new timer
		debounceTimerRef.current = setTimeout(() => {
			// Validate if pattern is provided
			if (pattern && !new RegExp(pattern).test(newValue)) {
				// Reset to previous value if invalid
				setInputValue(value)
				return
			}

			setValue(newValue)
		}, debounceMs)
	}

	return (
		<div className="flex items-center gap-2">
			<Input
				type="text"
				className={`bg-vscode-input-background text-vscode-input-foreground px-2 py-1 rounded text-sm ${className || ""}`}
				value={inputValue}
				placeholder={placeholder}
				disabled={disabled}
				maxLength={maxLength}
				pattern={pattern}
				onChange={handleChange}
				data-testid={testId}
			/>
		</div>
	)
}

export default TextInput

