import React from "react"
import { MarketplaceItem } from "@roo-code/types"
import { useAppTranslation } from "@/i18n/TranslationContext"
import { ItemEditModal } from "@/ibm/components/settings/components/common"
import { Button } from "@/components/ui/button"
import { StandardTooltip } from "@/components/ui/standard-tooltip"

// Type guard to ensure we only work with Mode items
type ModeMarketplaceItem = Extract<MarketplaceItem, { type: "mode" }>

interface ModeUninstallModalProps {
	item: ModeMarketplaceItem | null
	isOpen: boolean
	onClose: () => void
	onConfirm: () => void
	isLoading?: boolean
}

export const ModeUninstallModal: React.FC<ModeUninstallModalProps> = ({
	item,
	isOpen,
	onClose,
	onConfirm,
	isLoading = false,
}) => {
	const { t } = useAppTranslation()

	if (!item) return null

	return (
		<ItemEditModal
			isOpen={isOpen}
			title={t("ibmSettings:modes.uninstall_confirm_title")}
			onClose={onClose}
			className="sm:max-w-[400px]"
			footer={
				<>
					<StandardTooltip content={t("common:actions.cancel")}>
						<Button
							variant="secondary"
							onClick={onClose}
							disabled={isLoading}
						>
							{t("common:actions.cancel")}
						</Button>
					</StandardTooltip>
					<StandardTooltip content={t("ibmSettings:modes.actions.uninstall_mode")}>
						<Button
							variant="destructive"
							onClick={onConfirm}
							disabled={isLoading}
						>
							{isLoading
								? t("ibmSettings:modes.uninstalling")
								: t("ibmSettings:modes.actions.uninstall_mode")}
						</Button>
					</StandardTooltip>
				</>
			}
		>
			<div className="px-1">
				<div className="text-sm text-vscode-descriptionForeground">
					{t("ibmSettings:modes.uninstall_confirm_message")}
				</div>
				<div className="text-sm text-vscode-foreground font-medium mt-2">{item.name}</div>
			</div>
		</ItemEditModal>
	)
}

