import React, { useState, useEffect } from "react"
import { Trans, useTranslation } from "react-i18next"
import { VSCodeLink } from "@vscode/webview-ui-toolkit/react"
import { useBuildDocLink } from "@/utils/docLinks"
import { ModesOverviewGrid } from "./ModesOverviewGrid"
import { ModeDetailsView } from "./ModeDetailsView"
import SectionRow from "../../components/SectionRow"
import { vscode } from "@/utils/vscode"
import { Button, StandardTooltip } from "@/components/ui"
import Section from "../../components/Section"
import { useModes, ModeItem, findModeBySlug } from "./hooks/useModes"
import { useSettingsSearch } from "../../context/SettingsSearchContext"
import { HighlightedText } from "../../components/HighlightedText"

type ViewState = "overview" | "details"

/**
 * ModesTab Component
 *
 * Main component for the Modes tab in IBM Settings.
 * Displays an overview grid of modes with search, filter, and management capabilities.
 * Handles navigation between overview and details views.
 *
 * Features:
 * - Modes overview grid with search and filter (Sub-Task 2 ✓)
 * - Mode tiles for both custom and marketplace modes (Sub-Task 3 ✓)
 * - Mode details view with contextual actions (Sub-Task 4 ✓)
 * - Mode edit modal (Sub-Task 5 - TODO)
 * - Import/Export/Delete actions (Sub-Task 6 - TODO)
 */
const ModesTab: React.FC = () => {
	const buildDocLink = useBuildDocLink()
	const { t } = useTranslation()
	const { allModes } = useModes()
	const { isSearchActive, getHighlightInfoByTitleKey } = useSettingsSearch()

	// Navigation state
	const [viewState, setViewState] = useState<ViewState>("overview")
	const [selectedMode, setSelectedMode] = useState<ModeItem | null>(null)

	// Search highlighting helpers
	const dimClass = "opacity-30 pointer-events-none transition-opacity duration-200"
	const normalClass = "transition-opacity duration-200"

	const getRowProps = (titleKey: string, descriptionKey: string) => {
		const highlightInfo = getHighlightInfoByTitleKey(titleKey)
		const title = t(titleKey)
		const description = t(descriptionKey)
		const isDimmed = isSearchActive && !highlightInfo.isMatch

		return {
			title: highlightInfo.isMatch ? (
				<HighlightedText text={title} positions={highlightInfo.titlePositions} />
			) : (
				title
			),
			description:
				highlightInfo.isMatch && highlightInfo.descriptionPositions.length > 0 ? (
					<HighlightedText text={description} positions={highlightInfo.descriptionPositions} />
				) : (
					description
				),
			className: isDimmed ? dimClass : normalClass,
		}
	}

	// Update selectedMode when modes change (after save/update)
	useEffect(() => {
		if (!selectedMode || viewState !== "details") {
			return
		}

		// Find the updated mode from the latest allModes list
		const updatedMode = findModeBySlug(allModes, selectedMode.data.slug)

		// Update selectedMode if we found an updated version
		if (updatedMode) {
			setSelectedMode(updatedMode)
		}
	}, [allModes, selectedMode, viewState])

	// Navigation handlers
	const handleModeSelect = (mode: ModeItem) => {
		setSelectedMode(mode)
		setViewState("details")
	}

	const handleBackToOverview = () => {
		setViewState("overview")
		setSelectedMode(null)
	}

	const handleOpenGlobalModes = () => {
		vscode.postMessage({
			type: "openCustomModesSettings",
		})
	}

	const handleOpenProjectModes = () => {
		// ibm_change: Use .bob/custom_modes.yaml to match CustomModesManager behavior
		vscode.postMessage({
			type: "openFile",
			text: "./.bob/custom_modes.yaml",
			values: {
				create: true,
				content: JSON.stringify({ customModes: [] }, null, 2),
			},
		})
	}

	return (
		<div className="flex flex-col gap-1">
			{/* Header Section - Only show in overview */}
			{viewState === "overview" && (
				<>
					<div className="flex flex-col gap-2 pl-2">
						<div className="text-sm text-vscode-descriptionForeground">
							<Trans i18nKey="ibmSettings:modes.description">
								<VSCodeLink
									href={buildDocLink("features/modes")}
									className="text-sm"
									aria-label="Learn about using modes"></VSCodeLink>
								<VSCodeLink
									href={buildDocLink("configuration/custom-modes")}
									className="text-sm"
									aria-label="Learn about customizing modes"></VSCodeLink>
							</Trans>
						</div>
					</div>
					<Section className="mb-2">
						<SectionRow
							{...getRowProps(
								"ibmSettings:modes.global_modes_section.title",
								"ibmSettings:modes.global_modes_section.description",
							)}
							actionComponent={
								<StandardTooltip
									content={t("ibmSettings:modes.global_modes_section.open_button_tooltip")}>
									<Button variant="secondary" size="sm" onClick={handleOpenGlobalModes}>
										{t("ibmSettings:modes.global_modes_section.open_button")}
									</Button>
								</StandardTooltip>
							}
						/>
						<SectionRow
							{...getRowProps(
								"ibmSettings:modes.project_modes_section.title",
								"ibmSettings:modes.project_modes_section.description",
							)}
							actionComponent={
								<StandardTooltip
									content={t("ibmSettings:modes.project_modes_section.open_button_tooltip")}>
									<Button variant="secondary" size="sm" onClick={handleOpenProjectModes}>
										{t("ibmSettings:modes.project_modes_section.open_button")}
									</Button>
								</StandardTooltip>
							}
						/>
					</Section>
				</>
			)}

			{/* Content - Switch between overview and details */}
			{viewState === "overview" ? (
				<ModesOverviewGrid onModeSelect={handleModeSelect} />
			) : (
				selectedMode && <ModeDetailsView mode={selectedMode} onBack={handleBackToOverview} />
			)}

			{/* TODO: Sub-Task 5 - Add ModeEditModal component here */}
		</div>
	)
}

export default ModesTab

