import React from "react"
import { StandardTooltip } from "@/components/ui"

/**
 * ItemTileSkeleton Component
 *
 * Loading skeleton for ItemTile that maintains the same layout structure.
 * Shows animated placeholder boxes for title, status, and description areas.
 */
const ItemTileSkeleton: React.FC = () => {
	return (
		<div className="bg-vscode-dropdown-background rounded-[4px] p-[8px] h-[120px] flex flex-col border border-[rgba(0,0,0,0.1)]">
			{/* Header skeleton */}
			<div className="flex items-center justify-between py-[4px] w-full">
				<div className="flex items-center gap-2 min-w-0 flex-1">
					<div className="h-[13px] w-[40%] bg-vscode-input-foreground opacity-20 rounded animate-pulse" />
				</div>
				<div className="h-[11px] w-[60px] bg-vscode-input-foreground opacity-20 rounded animate-pulse" />
			</div>
			
			{/* Content skeleton */}
			<div className="flex flex-col flex-1 overflow-hidden w-full gap-1 mt-2">
				<div className="h-[11px] w-full bg-vscode-input-foreground opacity-20 rounded animate-pulse" />
				<div className="h-[11px] w-[90%] bg-vscode-input-foreground opacity-20 rounded animate-pulse" />
				<div className="h-[11px] w-[50%] bg-vscode-input-foreground opacity-20 rounded animate-pulse" />
			</div>
		</div>
	)
}

interface ItemTileProps {
	title: string                    // Main title (required)
	description?: string              // Description text (will be truncated)
	icon?: React.ReactNode            // Custom icon element
	statusIcon?: React.ReactNode      // Status icon after title (e.g., connection status indicator)
	metadata?: string                 // Author/source line below title
	statusText?: string               // Status text in top-right
	actionSlot?: React.ReactNode      // Custom action button/dropdown
	onClick?: () => void              // Click handler for entire tile
	onKeyDown?: (e: React.KeyboardEvent) => void  // Keyboard handler
	className?: string                // Additional CSS classes
	isLoading?: boolean               // Show loading skeleton effect
}

/**
 * ItemTile Component
 * 
 * A reusable tile component for displaying items in grid views.
 * Used across MCP, Modes, Rules, and Commands tabs.
 * 
 * Features:
 * - Fixed 120px height card layout
 * - Optional icon, metadata, description, status text, and action slot
 * - Hover effects and keyboard navigation
 * - Text truncation for long descriptions
 * - Accessible with proper ARIA attributes
 * 
 * @example
 * ```tsx
 * <ItemTile
 *   title="My Mode"
 *   description="A custom mode for development"
 *   metadata="by John Doe"
 *   statusText="Built-in / Global"
 *   onClick={() => console.log('clicked')}
 * />
 * ```
 */
export const ItemTile: React.FC<ItemTileProps> = ({
	title,
	description,
	icon,
	statusIcon,
	metadata,
	statusText,
	actionSlot,
	onClick,
	onKeyDown,
	className = "",
	isLoading = false,
}) => {
	// Handle keyboard navigation
	const handleKeyDown = (e: React.KeyboardEvent) => {
		if (e.key === "Enter" || e.key === " ") {
			e.preventDefault()
			onClick?.()
		}
		onKeyDown?.(e)
	}

	// Return skeleton if loading
	if (isLoading) {
		return <ItemTileSkeleton />
	}

	// Return normal tile content
	return (
		<div
			className={`
				bg-vscode-dropdown-background rounded-[4px] p-[8px] h-[120px] flex flex-col
				hover:bg-vscode-list-hoverBackground hover:shadow-md
				border border-[rgba(0,0,0,0.1)]
				${onClick ? 'cursor-pointer' : ''}
				${className}
			`}
			onClick={onClick}
			onKeyDown={handleKeyDown}
			tabIndex={onClick ? 0 : undefined}
			role={onClick ? "button" : undefined}
		>
			{/* Header: Icon, Title, and Action/Status */}
			<div className="flex items-center justify-between py-[4px] w-full">
				{/* Left side: Icon and Title */}
				<div className="flex items-center gap-2 min-w-0 flex-1">
					{icon && (
						<div className="flex-shrink-0">
							{icon}
						</div>
					)}
					<div className="text-[13px] font-medium whitespace-nowrap overflow-hidden text-ellipsis">
						{title}
					</div>
					{statusIcon && (
						<div className="flex-shrink-0">
							{statusIcon}
						</div>
					)}
				</div>

				{/* Right side: Action Slot or Status Text */}
				<div className="flex items-center gap-[4px] flex-shrink-0 ml-2">
					{actionSlot ? (
						actionSlot
					) : statusText ? (
						<p className="text-[11px] font-medium text-vscode-disabledForeground leading-[0] whitespace-nowrap">
							{statusText}
						</p>
					) : null}
				</div>
			</div>

			{/* Content Section */}
			<div className="flex flex-col flex-1 overflow-hidden w-full">
				{/* Metadata (e.g., author) */}
				{metadata && (
					<div className="text-[11px] mb-1 font-medium text-vscode-disabledForeground w-full">
						{metadata}
					</div>
				)}

				{/* Description with truncation */}
				{description && (
					<StandardTooltip content={description}>
						<div className="text-[11px] font-medium text-vscode-foreground w-full line-clamp-3 overflow-hidden">
							{description}
						</div>
					</StandardTooltip>
				)}
			</div>
		</div>
	)
}

