import React from "react"
import { ChevronUp, ChevronDown } from "lucide-react"
import { Button, StandardTooltip } from "@/components/ui"
import { useAppTranslation } from "@/i18n/TranslationContext"
import MarkdownBlock from "@/components/common/MarkdownBlock"

interface SectionRowExpandableProps {
	title: string | React.ReactNode
	description?: string | React.ReactNode
	maxDescriptionLength?: number
	titleActionComponent?: React.ReactNode
	actionComponent?: React.ReactNode
	children?: React.ReactNode
	/** Whether to start expanded (e.g., when search matches a child) */
	defaultExpanded?: boolean
}

const SectionRowExpandable: React.FC<SectionRowExpandableProps> = ({
	title,
	description,
	maxDescriptionLength,
	titleActionComponent,
	actionComponent,
	children,
	defaultExpanded = false,
}) => {
	const { t } = useAppTranslation()
	const [isExpanded, setIsExpanded] = React.useState(defaultExpanded)
	const [isDescriptionExpanded, setIsDescriptionExpanded] = React.useState(false)

	// Sync isExpanded state when defaultExpanded prop changes (e.g., when search activates)
	React.useEffect(() => {
		if (defaultExpanded) {
			setIsExpanded(true)
		}
	}, [defaultExpanded])

	const toggleExpand = () => {
		setIsExpanded(!isExpanded)
	}

	const toggleDescriptionExpand = () => {
		setIsDescriptionExpanded(!isDescriptionExpanded)
	}

	// Only apply truncation logic for string descriptions
	const isStringDescription = typeof description === "string"
	const shouldTruncateDescription =
		isStringDescription && maxDescriptionLength && (description as string).length > maxDescriptionLength
	const displayDescription =
		shouldTruncateDescription && !isDescriptionExpanded
			? (description as string).slice(0, maxDescriptionLength) + "..."
			: description

	const titleSection = <div className="flex items-center justify-between flex-1">
							<div className="text-sm font-medium">{title}</div>
							{titleActionComponent && <div>{titleActionComponent}</div>}
						</div>
	const expandButton = (
		<StandardTooltip content={isExpanded ? t("ibmSettings:common.collapse") : t("ibmSettings:common.expand")}>
			<button
				onClick={toggleExpand}
				className="ml-2 text-vscode-foreground hover:bg-vscode-button-hoverBackground rounded flex-shrink-0">
				{isExpanded ? <ChevronUp size={16} /> : <ChevronDown size={16} />}
			</button>
		</StandardTooltip>
	)

	return (
		<div className="min-h-10 border-b border-vscode-editor-background last:border-b-0 p-2">
			{description ? (
				// Layout with description: title row with titleActionComponent, description row with chevron
				<>
					{titleSection}
					<div className="flex justify-between align items-center gap-2 mt-1">
						<div className="flex-1">
							{isStringDescription ? (
								<MarkdownBlock
									markdown={displayDescription as string}
									className="text-vscode-descriptionForeground !text-sm [&_p]:!m-0"
								/>
							) : (
								<div className="text-vscode-descriptionForeground text-sm">{displayDescription}</div>
							)}
							{shouldTruncateDescription && (
								<Button
									variant="link"
									size="sm"
									onClick={toggleDescriptionExpand}
									className="h-auto p-0 text-vscode-textLink hover:underline">
									{isDescriptionExpanded
										? t("ibmSettings:common.show_less")
										: t("ibmSettings:common.show_more")}
								</Button>
							)}
						</div>
						<div className="flex justify-between items-center gap-2">
							{actionComponent && <div>{actionComponent}</div>}
							{expandButton}
						</div>
					</div>
				</>
			) : (
				// Layout without description: title, titleActionComponent, actionComponent, and chevron all in one row
				<div className="flex justify-between items-center gap-2">
					{titleSection}
					<div className="flex items-center gap-2">
						{actionComponent && <div>{actionComponent}</div>}
						{expandButton}
					</div>
				</div>
			)}
			{isExpanded && children && <div className="mt-2 p-2 text-sm bg-vscode-editor-background">{children}</div>}
		</div>
	)
}

export default SectionRowExpandable
