import * as React from "react"
import { useAppTranslation } from "@/i18n/TranslationContext"
import { useExtensionState } from "@/context/ExtensionStateContext"
import { SectionDefinition, SectionRowDefinition, ActionComponentType } from "../SettingsDefinition"
import Section from "./Section"
import SectionRow from "./SectionRow"
import SectionRowExpandable from "./SectionRowExpandable"
import Toggle from "./actions/Toggle"
import Checkbox from "./actions/Checkbox"
import NumberInput from "./actions/NumberInput"
import TextInput from "./actions/TextInput"
import Slider from "./actions/Slider"
import Select from "./actions/Select"
import CommandButton from "./actions/CommandButton"
import { CustomComponentsRegistry } from "./actions/CustomComponentsRegistry"
import { ExtensionStateWrapper, VSCodeSettingWrapper, WorkspaceStateWrapper } from "./actions/wrappers"
import SectionHeader from "./SectionHeader"
import { evaluateCondition } from "../utils/evaluateCondition"
import { useSettingsSearch } from "../context/SettingsSearchContext"
import { HighlightedText } from "./HighlightedText"

/**
 * Props for the SectionRenderer component
 */
interface SectionRendererProps {
	/** The section definition to render */
	definition: SectionDefinition
	/** Section index for building setting IDs */
	sectionIndex?: number
	/** Set of matched setting IDs when search is active (null when not searching) */
	matchedSettingIds?: Set<string> | null
	/** Whether search mode is active */
	isSearchActive?: boolean
}

/**
 * Renders an action component based on its type and props
 * Uses wrapper pattern for components with binding configuration
 * @param actionComponent The action component definition
 * @param state The extension state
 * @returns The rendered action component
 */
const renderActionComponent = (actionComponent: any, state: any) => {
	if (!actionComponent) return null

	const { type, binding, props = {} } = actionComponent

	// Skip rendering if condition is not met
	if (props.condition && !evaluateCondition(props.condition, state)) {
		return null
	}

	// Get the appropriate wrapper based on binding type
	const getWrapper = (component: React.ComponentType<any>) => {
		if (!binding) return null

		// Pass state and defaultValue to the component through props
		const propsWithState = {
			...props,
			state,
			defaultValue: binding.defaultValue,
		}

		if (binding.type === "extensionState") {
			return <ExtensionStateWrapper component={component} binding={binding} props={propsWithState} />
		} else if (binding.type === "vscodeSetting") {
			return <VSCodeSettingWrapper component={component} binding={binding} props={propsWithState} />
		} else if (binding.type === "workspaceState") {
			return <WorkspaceStateWrapper component={component} binding={binding} props={propsWithState} />
		}
		return null
	}

	// Render component with wrapper if binding exists, otherwise render directly
	switch (type) {
		case ActionComponentType.TOGGLE:
			return binding ? getWrapper(Toggle) : <Toggle {...props} />
		case ActionComponentType.CHECKBOX:
			return binding ? getWrapper(Checkbox) : <Checkbox {...props} />
		case ActionComponentType.NUMBER_INPUT:
			return binding ? getWrapper(NumberInput) : <NumberInput {...props} />
		case ActionComponentType.TEXT_INPUT:
			return binding ? getWrapper(TextInput) : <TextInput {...props} />
		case ActionComponentType.SLIDER:
			return binding ? getWrapper(Slider) : <Slider {...props} />
		case ActionComponentType.SELECT:
			return binding ? getWrapper(Select) : <Select {...props} />
		case ActionComponentType.COMMAND_BUTTON:
			return <CommandButton {...props} />
		case ActionComponentType.CUSTOM:
			if (!props.componentName) {
				console.warn("Custom component missing componentName")
				return null
			}
			return CustomComponentsRegistry.render(props.componentName, {
				...props,
				...(props.additionalProps || {}),
			})
		default:
			console.warn(`Unknown action component type: ${type}`)
			return null
	}
}

/**
 * Component to render a section row
 */
const SectionRowRenderer: React.FC<{
	rowDefinition: SectionRowDefinition
	index: number
	state: any
	/** Whether this setting matches the current search */
	isMatched: boolean
	/** Whether search mode is active */
	isSearchActive: boolean
}> = ({ rowDefinition, index, state, isMatched, isSearchActive }) => {
	const { t } = useAppTranslation()
	const { getHighlightInfoByTitleKey } = useSettingsSearch()
	const { title, description, actionComponent, children, condition } = rowDefinition

	// Skip rendering if condition is not met
	if (condition && !evaluateCondition(condition, state)) {
		return null
	}

	const translatedTitle = t(title)
	const translatedDescription = description ? t(description) : undefined
	const renderedActionComponent = actionComponent ? renderActionComponent(actionComponent, state) : undefined

	// Get highlight positions for this row
	const highlightInfo = getHighlightInfoByTitleKey(title)

	// Render title with highlighting if matched
	const renderTitle = () => {
		if (isMatched && highlightInfo.titlePositions.length > 0) {
			return <HighlightedText text={translatedTitle} positions={highlightInfo.titlePositions} />
		}
		return translatedTitle
	}

	// Render description with highlighting if matched
	const renderDescription = () => {
		if (!translatedDescription) return undefined
		if (isMatched && highlightInfo.descriptionPositions.length > 0) {
			return <HighlightedText text={translatedDescription} positions={highlightInfo.descriptionPositions} />
		}
		return translatedDescription
	}

	// Apply dimming when searching and this row doesn't match
	const dimmed = isSearchActive && !isMatched
	const wrapperClassName = dimmed
		? "opacity-30 pointer-events-none transition-opacity duration-200"
		: "transition-opacity duration-200"

	// If there are children, render as expandable row
	if (children && children.length > 0) {
		const renderedChildren = (
			<div className="flex flex-col gap-2">
				{children.map((child, childIndex) => {
					// Handle both direct action components and child row definitions
					if ("actionComponent" in child) {
						// This is a ChildRowDefinition
						if (child.condition && !evaluateCondition(child.condition, state)) {
							return null
						}
						return (
							<div key={childIndex} className={child.className}>
								{renderActionComponent(child.actionComponent, state)}
							</div>
						)
					} else {
						// This is an ActionComponentDefinition
						// Check for condition
						if (child.condition && !evaluateCondition(child.condition, state)) {
							return null
						}
						return <div key={childIndex}>{renderActionComponent(child, state)}</div>
					}
				})}
			</div>
		)

		return (
			<div className={wrapperClassName}>
				<SectionRowExpandable
					key={index}
					title={renderTitle()}
					description={renderDescription()}
					actionComponent={renderedActionComponent}
					defaultExpanded={isSearchActive && isMatched}>
					{renderedChildren}
				</SectionRowExpandable>
			</div>
		)
	}

	// Otherwise, render as regular row
	return (
		<div className={wrapperClassName}>
			<SectionRow
				key={index}
				title={renderTitle()}
				description={renderDescription()}
				actionComponent={renderedActionComponent}
			/>
		</div>
	)
}

/**
 * Parses a setting ID string (format: "prefix/sectionId/rowIndex").
 * @returns The parsed sectionId and rowIndex, or null if invalid
 */
function parseSettingId(settingId: string): { sectionId: string; rowIndex: number } | null {
	const parts = settingId.split("/")
	if (parts.length < 3) return null

	const rowIndex = parseInt(parts[2], 10)
	if (isNaN(rowIndex)) return null

	return { sectionId: parts[1], rowIndex }
}

/**
 * Checks if a setting ID belongs to a specific section.
 */
function settingBelongsToSection(settingId: string, sectionId: string, sectionIndex: number): boolean {
	const parsed = parseSettingId(settingId)
	if (!parsed) return false
	return parsed.sectionId === sectionId || parsed.sectionId === `section-${sectionIndex}`
}

/**
 * Determines if any matched setting IDs belong to a specific section.
 */
function checkSectionHasMatches(matchedIds: Set<string>, sectionId: string, sectionIndex: number): boolean {
	for (const id of matchedIds) {
		if (settingBelongsToSection(id, sectionId, sectionIndex)) {
			return true
		}
	}
	return false
}

/**
 * Computes the set of row indices that match the search within a section.
 */
function getMatchedRowIndices(matchedIds: Set<string>, sectionId: string, sectionIndex: number): Set<number> {
	const indices = new Set<number>()
	for (const id of matchedIds) {
		const parsed = parseSettingId(id)
		if (parsed && (parsed.sectionId === sectionId || parsed.sectionId === `section-${sectionIndex}`)) {
			indices.add(parsed.rowIndex)
		}
	}
	return indices
}

/**
 * Renders a custom component section with search highlighting support.
 */
const CustomComponentSection: React.FC<{
	definition: SectionDefinition
	extensionState: unknown
	isDimmed: boolean
}> = ({ definition, extensionState, isDimmed }) => {
	const { t } = useAppTranslation()
	const { getHighlightInfoByTitleKey } = useSettingsSearch()
	const { className, title, description, customComponent } = definition

	const highlightInfo = title ? getHighlightInfoByTitleKey(title) : null
	const isMatched = highlightInfo?.isMatch ?? false

	const renderTitle = () => {
		if (!title) return ""
		const translatedTitle = t(title)
		if (isMatched && highlightInfo?.titlePositions.length) {
			return <HighlightedText text={translatedTitle} positions={highlightInfo.titlePositions} />
		}
		return translatedTitle
	}

	const renderDescription = () => {
		if (!description || typeof description !== "string") return description
		const translatedDesc = t(description)
		if (isMatched && highlightInfo?.descriptionPositions.length) {
			return <HighlightedText text={translatedDesc} positions={highlightInfo.descriptionPositions} />
		}
		return translatedDesc
	}

	return (
		<div className={`${className} ${isDimmed ? "opacity-30" : ""}`}>
			{title || description ? (
				<SectionHeader title={renderTitle()} description={renderDescription()} />
			) : null}
			<Section>{renderActionComponent(customComponent, extensionState)}</Section>
		</div>
	)
}

/**
 * Renders a section based on a JSON definition
 */
const SectionRenderer: React.FC<SectionRendererProps> = ({
	definition,
	sectionIndex = 0,
	matchedSettingIds,
	isSearchActive = false,
}) => {
	const { t } = useAppTranslation()
	const { className, rows, customComponent, title, description, condition } = definition
	const extensionState = useExtensionState()

	// Get sectionId from definition or use index
	const sectionId = (definition as { sectionId?: string }).sectionId || `section-${sectionIndex}`

	// Check if any row in this section matches the search
	// Note: hooks must be called unconditionally before any early returns
	const sectionHasMatches = React.useMemo(() => {
		if (!isSearchActive || !matchedSettingIds) return true

		// Check for custom section match (format: tabId/sectionId/custom-section)
		for (const id of matchedSettingIds) {
			if (id.endsWith(`/${sectionId}/custom-section`)) {
				return true
			}
		}

		if (!rows) return false
		return checkSectionHasMatches(matchedSettingIds, sectionId, sectionIndex)
	}, [isSearchActive, matchedSettingIds, sectionIndex, sectionId, rows])

	// Pre-compute which row indices match to avoid recalculating in the map
	const matchedRowIndices = React.useMemo(() => {
		if (!isSearchActive || !matchedSettingIds) return null
		return getMatchedRowIndices(matchedSettingIds, sectionId, sectionIndex)
	}, [isSearchActive, matchedSettingIds, sectionId, sectionIndex])

	// Skip rendering if condition is not met
	if (condition && !evaluateCondition(condition, extensionState)) {
		return null
	}

	// Dim the entire section header if no matches
	const sectionDimmed = isSearchActive && !sectionHasMatches

	if (customComponent) {
		return (
			<CustomComponentSection
				definition={definition}
				extensionState={extensionState}
				isDimmed={sectionDimmed}
			/>
		)
	}

	// Otherwise render rows as normal
	return (
		<div className={className}>
			{title || description ? (
				<div className={sectionDimmed ? "opacity-50 transition-opacity" : "transition-opacity"}>
					<SectionHeader title={title ? t(title) : ""} description={description} />
				</div>
			) : null}
			<Section>
				{rows?.map((row, rowIndex) => {
					// Use pre-computed matched indices for efficient lookup
					const isMatched = !isSearchActive || !matchedRowIndices || matchedRowIndices.has(rowIndex)

					return (
						<SectionRowRenderer
							key={rowIndex}
							rowDefinition={row}
							index={rowIndex}
							state={extensionState}
							isMatched={isMatched}
							isSearchActive={isSearchActive}
						/>
					)
				})}
			</Section>
		</div>
	)
}

export default SectionRenderer

