import React, { useMemo, useEffect, useRef } from "react"
import { useAppTranslation } from "@/i18n/TranslationContext"
import { Coins, ExternalLink, RefreshCw } from "lucide-react"
import { useExtensionState } from "@/context/ExtensionStateContext"
import { useBudget } from "@/ibm/hooks/useBudget"
import { VSCodeLink } from "@vscode/webview-ui-toolkit/react"
import { Button } from "@/components/ui/button"
import { StandardTooltip } from "@/components/ui"
import TeamSelector from "./TeamSelector"
import BudgetResetInfo from "./BudgetResetInfo"
import { getActiveProfile } from "@/ibm/utils/userProfile"
import { logger } from "@/ibm/utils/logger"
import PlanSection from "./PlanSection"
import { isTrial } from "@roo/IBM/userProfileHelpers"
import AutoSetup from "@/ibm/components/welcome/AutoSetup"
import { ENTERPRISE_PLAN_ID } from "@/ibm/constants"

const CRITICAL_BUDGET_PERCENTAGE = 5
const INIT_LOAD_TIMEOUT = 4000 // if the profile message gets missed this ensures that it is updated

/**
 * Custom component for displaying account and budget information
 * Shows account email, budget limit, usage with optional Bobalytics link,
 * and budget reset information
 */
const AccountBudgetSection: React.FC = () => {
	const { t } = useAppTranslation()
	const { featureFlags, activeProfile, showWelcome } = useExtensionState()
	const { budget: budgetData, isLoading, fetchBudget } = useBudget()
	const timeoutRef = useRef<NodeJS.Timeout | null>(null)

	useEffect(() => {
		if (!activeProfile?.user_id) {
			timeoutRef.current = setTimeout(() => {
				getActiveProfile(true).catch(() => {
					logger.error("Failed to fetch active profile after timeout")
				})
			}, INIT_LOAD_TIMEOUT)
		} else if (timeoutRef.current) {
			clearTimeout(timeoutRef.current)
			timeoutRef.current = null
		}

		return () => {
			if (timeoutRef.current) {
				clearTimeout(timeoutRef.current)
				timeoutRef.current = null
			}
		}
	}, [activeProfile?.user_id])

	const isEnterprise = activeProfile?.plan === ENTERPRISE_PLAN_ID

	const bobalyticsUrl = useMemo(() => {
		return featureFlags?.["bobalytics-url"]
	}, [featureFlags])

	const isBudgetCritical = useMemo(() => {
		return budgetData && budgetData.percentage < CRITICAL_BUDGET_PERCENTAGE
	}, [budgetData])

	const isProfileLoading = !activeProfile?.user_id
	// If showWelcome is true, display login message with AutoSetup buttons
	if (showWelcome) {
		return (
			<div className="px-0 pt-2">
				<div className="text-vscode-descriptionForeground text-center text-sm -mb-6">
					{t("ibmSettings:general.pleaseSignIn")}
				</div>
				<AutoSetup />
			</div>
		)
	}

	// Otherwise, show the account details
	return (
		<div className="px-0 py-1">
			{/* Account and Budget Info Table */}
			<table className="w-full">
				<tbody>
					<tr className="h-6">
						<td className="py-2 pl-2 text-sm font-medium w-auto whitespace-nowrap">
							{t("ibmSettings:general.account")}
						</td>
						<td className="pl-4 text-sm font-medium text-left w-full">
							<div className="flex items-center justify-between">
								<span>{isProfileLoading ? t("ibm:fetching") : activeProfile.user_id}</span>
								<StandardTooltip content={t("common:actions.refresh")}>
									<Button
										variant="ghost"
										size="icon"
										onClick={fetchBudget}
										disabled={isLoading}
										aria-label={t("common:actions.refresh")}
										className="h-6 w-6 mr-1">
										<RefreshCw className={`w-3.5 h-3.5 ${isLoading ? "animate-spin" : ""}`} />
									</Button>
								</StandardTooltip>
							</div>
						</td>
					</tr>
					<TeamSelector />
					<PlanSection />
					<tr className="h-6">
						<td className="py-2  pl-2 text-sm font-medium w-auto whitespace-nowrap">
							{isTrial(activeProfile)
								? t("ibmSettings:general.trialBudget")
								: isEnterprise
									? t("ibmSettings:general.enterpriseBudget")
									: t("ibmSettings:general.monthlyBudget")}
						</td>
						<td className="pl-4 text-sm font-medium text-left w-full">
							<Coins className="inline-block size-[1em] mr-1" />
							{isProfileLoading || isLoading ? t("ibm:budget.fetching") : budgetData?.limit || "—"}
						</td>
					</tr>
					<tr>
						<td className="pl-2 text-sm font-medium w-auto whitespace-nowrap">
							{isTrial(activeProfile)
								? t("ibmSettings:general.trialUsage")
								: isEnterprise
									? t("ibmSettings:general.enterpriseUsage")
									: t("ibmSettings:general.monthlyUsage")}
						</td>
						<td className="pl-4 text-sm font-medium text-left w-full">
							<div className="flex gap-[10px] items-start text-sm font-medium">
								<div
									className={
										isBudgetCritical ? "text-vscode-errorForeground" : "text-vscode-foreground"
									}>
									<Coins className="inline-block size-[1em] mr-1" />
									{isProfileLoading || isLoading
										? t("ibm:budget.fetching")
										: budgetData
											? t("ibmSettings:general.usage", budgetData)
											: "—"}
								</div>
								{bobalyticsUrl && (activeProfile?.is_internal || isEnterprise) ? (
									<VSCodeLink href={bobalyticsUrl}>
										<div className="text-[var(--base-colors-info,#3794ff)] flex items-center gap-1 cursor-pointer hover:underline">
											<ExternalLink className="w-3 h-3" />
											<span>{t("ibmSettings:general.viewBobalytics")}</span>
										</div>
									</VSCodeLink>
								) : null}
							</div>
						</td>
					</tr>
				</tbody>
			</table>
			{<BudgetResetInfo />}
		</div>
	)
}

export default AccountBudgetSection

