import { createMessageListener } from "../../../../../utils/messageListener"

/**
 * Scope Change Utilities
 * 
 * Provides reusable utilities for validating and handling scope changes in modes.
 * Consolidates duplicate validation logic and provides separate handlers for
 * marketplace and custom modes.
 * 
 * @example
 * ```typescript
 * // Validate scope change
 * const scopeChanged = validateScopeChange({
 *   originalScope: 'global',
 *   newScope: 'project',
 *   cwd: '/path/to/workspace',
 *   t: translationFunction
 * });
 * 
 * if (scopeChanged) {
 *   // Handle marketplace mode scope change
 *   handleMarketplaceScopeChange({
 *     mode,
 *     originalScope: 'global',
 *     newScope: 'project',
 *     marketplaceItem,
 *     onSuccess: () => console.log('Scope changed!'),
 *     onError: (err) => console.error(err)
 *   });
 * }
 * ```
 */

/**
 * Configuration for scope change validation
 */
export interface ScopeChangeValidation {
	/**
	 * The original scope of the mode
	 */
	originalScope: string | undefined

	/**
	 * The new scope to change to
	 */
	newScope: string | undefined

	/**
	 * Current working directory (workspace path).
	 * Required when changing to project scope.
	 */
	cwd: string | undefined

	/**
	 * Translation function for error messages
	 */
	t: (key: string) => string
}

/**
 * Configuration for marketplace mode scope change
 */
export interface MarketplaceScopeChangeConfig {
	/**
	 * The mode being changed
	 */
	mode: {
		data: {
			slug: string
		}
	}

	/**
	 * The original scope of the mode
	 */
	originalScope: string | undefined

	/**
	 * The new scope to change to
	 */
	newScope: string | undefined

	/**
	 * The marketplace item data required for uninstall/reinstall
	 */
	marketplaceItem: any

	/**
	 * Callback to execute after successful scope change and custom prompt application.
	 * This callback should handle the success notification.
	 */
	applyCustomPrompt: () => void

	/**
	 * VSCode API object for posting messages
	 */
	vscode: {
		postMessage: (message: any) => void
	}

	/**
	 * Callback invoked when scope change fails
	 */
	onError?: (error: Error) => void
}

/**
 * Configuration for custom mode scope change
 */
export interface CustomScopeChangeConfig {
	/**
	 * The mode being changed
	 */
	mode: {
		data: {
			slug: string
		}
	}

	/**
	 * VSCode API object for posting messages
	 */
	vscode: {
		postMessage: (message: any) => void
	}
}

/**
 * Validates a scope change and checks workspace requirements.
 * 
 * This function:
 * - Checks if the scope has actually changed
 * - Validates that a workspace exists when changing to project scope
 * - Throws an error if validation fails
 * 
 * @param config - Validation configuration
 * @returns true if scope changed, false if scope is unchanged
 * @throws Error if changing to project scope without a workspace
 * 
 * @example
 * ```typescript
 * try {
 *   const scopeChanged = validateScopeChange({
 *     originalScope: 'global',
 *     newScope: 'project',
 *     cwd: workspacePath,
 *     t: translationFunction
 *   });
 *   
 *   if (scopeChanged) {
 *     // Handle scope change
 *   }
 * } catch (error) {
 *   // Handle validation error (e.g., no workspace)
 * }
 * ```
 */
export function validateScopeChange(config: ScopeChangeValidation): boolean {
	const { originalScope, newScope, cwd, t } = config

	// Check if scope has changed
	const scopeChanged = originalScope !== newScope

	if (scopeChanged) {
		// Check if workspace exists when changing to project scope
		if (newScope === "project" && !cwd) {
			throw new Error(t("ibmSettings:modes.edit_modal.no_workspace_error"))
		}
	}

	return scopeChanged
}

/**
 * Handles scope change for marketplace modes.
 * 
 * For marketplace modes, changing scope requires:
 * 1. Uninstalling from the old location
 * 2. Reinstalling at the new location
 * 3. Applying any custom field changes
 * 
 * This function uses the createMessageListener utility to handle the
 * asynchronous uninstall/reinstall sequence with timeout protection.
 * 
 * @param config - Marketplace scope change configuration
 * @throws Error if marketplace item data is missing
 * 
 * @example
 * ```typescript
 * handleMarketplaceScopeChange({
 *   mode: { data: { slug: 'my-mode' } },
 *   originalScope: 'global',
 *   newScope: 'project',
 *   marketplaceItem: mpItem,
 *   applyCustomPrompt: () => {
 *     // Apply custom field changes
 *   },
 *   onSuccess: () => console.log('Scope changed successfully'),
 *   onError: (err) => console.error('Scope change failed:', err)
 * });
 * ```
 */
export function handleMarketplaceScopeChange(config: MarketplaceScopeChangeConfig): void {
	const { mode, originalScope, newScope, marketplaceItem, applyCustomPrompt, vscode, onError } = config

	if (!marketplaceItem) {
		const error = new Error("Marketplace item data required for scope change")
		onError?.(error)
		throw error
	}

	// Filter out 'registry' scope as it's not a valid target for uninstall/install
	const oldTarget = originalScope === "registry" ? "global" : (originalScope || "global")
	const newTarget = newScope === "registry" ? "global" : (newScope || "global")

	// Set up listener for removal completion with 30-second timeout
	createMessageListener({
		messageType: "marketplaceRemoveResult",
		matchCondition: (message: any) => message.slug === mode.data.slug,
		onSuccess: () => {
			// Removal successful, now install at new location
			vscode.postMessage({
				type: "installMarketplaceItem",
				mpItem: marketplaceItem,
				mpInstallOptions: { target: newTarget as "global" | "project" },
			})

			// Set up listener for install completion with 30-second timeout
			createMessageListener({
				messageType: "marketplaceInstallResult",
				matchCondition: (installMessage: any) => installMessage.slug === mode.data.slug,
				onSuccess: () => {
					// After successful reinstall, apply any custom field changes
					// applyCustomPrompt already handles the success callback
					applyCustomPrompt()
				},
				onError: (error: Error) => {
					onError?.(error)
				},
				timeout: 30000,
			})
		},
		onError: (error: Error) => {
			onError?.(error)
		},
		timeout: 30000,
	})

	// Uninstall from old location
	vscode.postMessage({
		type: "removeInstalledMarketplaceItem",
		mpItem: marketplaceItem,
		mpInstallOptions: { target: oldTarget as "global" | "project" },
	})
}

/**
 * Handles scope change for custom modes.
 * 
 * For custom modes, changing scope requires deleting the mode from
 * the old location. The mode will be recreated at the new location
 * when the update message is sent.
 * 
 * @param config - Custom mode scope change configuration
 * 
 * @example
 * ```typescript
 * handleCustomScopeChange({
 *   mode: { data: { slug: 'my-custom-mode' } },
 *   vscode: vscodeApi
 * });
 * ```
 */
export function handleCustomScopeChange(config: CustomScopeChangeConfig): void {
	const { mode, vscode } = config

	// Delete mode from old location
	vscode.postMessage({
		type: "deleteCustomMode",
		slug: mode.data.slug,
	})
}