import { ConditionDefinition, ConditionOperator } from "../SettingsDefinition"

type StateObject = Record<string, unknown> | object

/**
 * Gets a nested value from an object using dot notation
 * @param obj The object to traverse
 * @param path The property path (e.g., "featureFlags.llm-attribution-enabled")
 * @returns The value at the path, or undefined if not found
 */
export function getNestedValue(obj: StateObject, path: string): unknown {
	return path.split(".").reduce((current: unknown, key) => {
		if (current && typeof current === "object") {
			return (current as Record<string, unknown>)[key]
		}
		return undefined
	}, obj)
}

/**
 * Evaluates a condition against the provided state
 * Supports nested property paths using dot notation (e.g., "featureFlags.llm-attribution-enabled")
 * @param condition The condition to evaluate
 * @param state The state to evaluate against (typically ExtensionState or similar object)
 * @returns True if the condition is met, false otherwise
 */
export function evaluateCondition(condition: ConditionDefinition | undefined, state: StateObject): boolean {
	if (!condition) return true

	const { property, value, operator = ConditionOperator.EQUALS } = condition
	const stateValue = getNestedValue(state, property)

	switch (operator) {
		case ConditionOperator.EQUALS:
			return stateValue === value
		case ConditionOperator.NOT_EQUALS:
			return stateValue !== value
		case ConditionOperator.GREATER_THAN:
			return typeof stateValue === "number" && stateValue > (value as number)
		case ConditionOperator.LESS_THAN:
			return typeof stateValue === "number" && stateValue < (value as number)
		case ConditionOperator.CONTAINS:
			return Array.isArray(stateValue) && stateValue.includes(value)
		default:
			return true
	}
}

