import React, { useState, useMemo, useEffect } from "react"
import { MarketplaceItem, McpParameter } from "@roo-code/types"
import { useAppTranslation } from "@/i18n/TranslationContext"
import { ItemEditModal, FormField, SelectField, InfoList, ScopeSelector } from "@/ibm/components/settings/components/common"
import { useMarketplaceInstall } from "./useMarketplaceInstall"
import { ValidationError } from "./shared/ValidationError"
import { ModalFooter } from "./shared/ModalFooter"
import { vscode } from "@/utils/vscode"
import { Button } from "@/components/ui"
import Section from "@/ibm/components/settings/components/Section"
import SectionHeader from "@/ibm/components/settings/components/SectionHeader"

// Type guard to ensure we only work with MCP items
type McpMarketplaceItem = Extract<MarketplaceItem, { type: "mcp" }>

interface McpInstallModalProps {
	item: McpMarketplaceItem | null
	isOpen: boolean
	onClose: () => void
	hasWorkspace: boolean
	isEditMode?: boolean
	currentTarget?: 'global' | 'project'
	currentParameters?: Record<string, string>
}

export const McpInstallModal: React.FC<McpInstallModalProps> = ({
	item,
	isOpen,
	onClose,
	hasWorkspace,
	isEditMode = false,
	currentTarget,
	currentParameters,
}) => {
	const { t } = useAppTranslation()
	const [scope, setScope] = useState<"project" | "global">(
		isEditMode && currentTarget ? currentTarget : (hasWorkspace ? "project" : "global")
	)
	const [selectedMethodIndex, setSelectedMethodIndex] = useState(0)
	const [parameterValues, setParameterValues] = useState<Record<string, string>>(currentParameters || {})

	const { isInstalling, validationError, setValidationError, install } = useMarketplaceInstall({
		item,
		isEditMode,
		currentTarget,
		onClose,
	})

	// Reset state when item changes
	React.useEffect(() => {
		if (item) {
			setSelectedMethodIndex(0)
			setParameterValues(isEditMode && currentParameters ? currentParameters : {})
			setValidationError(null)
			setScope(isEditMode && currentTarget ? currentTarget : (hasWorkspace ? "project" : "global"))
		}
	}, [item, isEditMode, currentParameters, currentTarget, hasWorkspace, setSelectedMethodIndex, setParameterValues, setValidationError, setScope])

	// Check if item has multiple installation methods
	const hasMultipleMethods = useMemo(() => {
		return item && Array.isArray(item.content) && item.content.length > 1
	}, [item])

	// Get installation method names
	const methodNames = useMemo(() => {
		if (!item || !Array.isArray(item.content)) return []
		return item.content.map((method) => method.name)
	}, [item])

	// Get effective parameters for validation
	const effectiveParameters = useMemo(() => {
		if (!item) return []

		const globalParams = item.parameters || []
		let methodParams: McpParameter[] = []

		if (Array.isArray(item.content)) {
			const selectedMethod = item.content[selectedMethodIndex]
			methodParams = selectedMethod?.parameters || []
		}

		// Merge parameters with precedence rules:
		// 1. Global params are loaded first into the map
		// 2. Method-specific params override globals with the same key
		// 3. Map ensures uniqueness by key
		const paramMap = new Map<string, McpParameter>()
		globalParams.forEach((p) => paramMap.set(p.key, p))
		methodParams.forEach((p) => paramMap.set(p.key, p))

		return Array.from(paramMap.values())
	}, [item, selectedMethodIndex])

	// Get effective prerequisites
	const effectivePrerequisites = useMemo(() => {
		if (!item) return []

		const globalPrereqs = item.prerequisites || []
		let methodPrereqs: string[] = []

		if (Array.isArray(item.content)) {
			const selectedMethod = item.content[selectedMethodIndex]
			methodPrereqs = selectedMethod?.prerequisites || []
		}

		const allPrereqs = [...globalPrereqs, ...methodPrereqs]
		return Array.from(new Set(allPrereqs))
	}, [item, selectedMethodIndex])

	// Update parameter values when method changes
	useEffect(() => {
		if (!item) return

		const globalParams = item.parameters || []
		let methodParams: McpParameter[] = []

		if (Array.isArray(item.content)) {
			const selectedMethod = item.content[selectedMethodIndex]
			methodParams = selectedMethod?.parameters || []
		}

		const paramMap = new Map<string, McpParameter>()
		globalParams.forEach((p) => paramMap.set(p.key, p))
		methodParams.forEach((p) => paramMap.set(p.key, p))

		const currentEffectiveParams = Array.from(paramMap.values())

		setParameterValues((prev) => {
			const newValues: Record<string, string> = {}
			currentEffectiveParams.forEach((param) => {
				newValues[param.key] = prev[param.key] || ""
			})
			return newValues
		})
	}, [item, selectedMethodIndex])

	const handleInstall = () => {
		if (!item) return

		setValidationError(null)

		// Validate required parameters
		for (const param of effectiveParameters) {
			if (!param.optional && !parameterValues[param.key]?.trim()) {
				// ibm_change: Use new error format (string for validation errors, no scope needed)
				setValidationError({ message: t("marketplace:install.validationRequired", { paramName: param.name }) })
				return
			}
		}

		// Prepare parameters
		const finalParameters: Record<string, any> = { ...parameterValues }
		for (const param of effectiveParameters) {
			if (param.optional && !finalParameters[param.key]) {
				finalParameters[param.key] = ""
			}
		}

		// Use the shared install function
		install({
			scope,
			parameters: {
				...finalParameters,
				_selectedIndex: hasMultipleMethods ? selectedMethodIndex : undefined,
			},
		})
	}

	if (!item) return null

	const modalTitle = isEditMode
		? t("marketplace:install.titleEdit", { name: item.name })
		: t("marketplace:install.titleMcp", { name: item.name })

	// Calculate if scope has changed from original
	const scopeChanged = isEditMode && currentTarget ? scope !== currentTarget : false

	return (
		<ItemEditModal
			isOpen={isOpen}
			title={modalTitle}
			subtitle={
				item.url ? (
					<Button
						variant="link"
						className="h-auto p-0 text-sm text-vscode-textLink-foreground hover:text-vscode-textLink-activeForeground"
						onClick={() => vscode.postMessage({ type: "openExternal", url: item.url })}>
						{t("marketplace:install.moreInfoMcp", { name: item.name })}
					</Button>
				) : undefined
			}
			onClose={onClose}
			className="sm:max-w-[400px]"
			footer={
				<ModalFooter
					onCancel={onClose}
					onConfirm={handleInstall}
					isLoading={isInstalling}
					isEditMode={isEditMode}
				/>
			}
		>
			<Section>
				<ScopeSelector
					label={t("marketplace:install.scope")}
					value={scope}
					onChange={(newScope) => {
						if (newScope === "global" || newScope === "project") {
							setScope(newScope)
						}
					}}
					scopeChanged={scopeChanged}
					helperText={!hasWorkspace ? t("marketplace:install.project_disabled") : t("marketplace:install.scope_helper")}
				/>

				{hasMultipleMethods && (
					<SelectField
						label={t("marketplace:install.method")}
						value={selectedMethodIndex}
						options={methodNames.map((name, index) => ({
							label: name,
							value: index,
						}))}
						onChange={(value) => setSelectedMethodIndex(Number(value))}
					/>
				)}

				{effectivePrerequisites.length > 0 && (
					<InfoList
						label={t("marketplace:install.prerequisites")}
						items={effectivePrerequisites}
					/>
				)}
			</Section>

			{effectiveParameters.length > 0 && (
				<>
					<SectionHeader
						title={t("marketplace:install.configuration")}
						description={t("marketplace:install.configurationDescription")}
					/>
					<Section>
						{effectiveParameters.map((param) => (
							<FormField
								key={param.key}
								label={`${param.name}${param.optional ? ` ${t("ibmSettings:marketplace.install_modal.parameter_optional")}` : ""}`}
								value={parameterValues[param.key] || ""}
								onChange={(value) =>
									setParameterValues((prev) => ({
										...prev,
										[param.key]: value,
									}))
								}
								placeholder={param.placeholder}
								type="text"
							/>
						))}
					</Section>
				</>
			)}

			<ValidationError error={validationError} />
		</ItemEditModal>
	)
}

