import React from "react"
import { useAppTranslation } from "@/i18n/TranslationContext"
import { Button, StandardTooltip } from "@/components/ui"
import { McpServerItem } from "./types"
import { ItemTile } from "../../components/common"
import { useMarketplaceEnabled } from "../modes/hooks/useMarketplaceEnabled" // ibm_change
import { getMcpServerBadges } from "./utils/mcpServerBadges" // ibm_change
import { Circle } from "lucide-react"

interface McpServerTileProps {
	serverItem: McpServerItem
	onClick?: () => void
	onInstall?: (serverId: string) => void
	isLoading?: boolean
}

/**
 * McpServerTile Component
 *
 * Displays a single MCP server tile with name, status indicator, connection status, and scope badge.
 * Shows connection status with colored indicator (green/yellow/red) and source badge (Global/Project).
 * For marketplace servers: shows Install button if not installed, or Installed indicator if installed.
 * All edit/delete/uninstall actions are handled in the MCP Server Details View.
 */
export const McpServerTile: React.FC<McpServerTileProps> = ({ serverItem, onClick, onInstall, isLoading = false }) => {
	const { t } = useAppTranslation()
	// ibm_change: Check if marketplace is enabled
	const isMarketplaceEnabled = useMarketplaceEnabled()

	// Get server properties
	const name = serverItem?.metaData?.name || serverItem.data.name
	const author = serverItem?.metaData?.author
	const description = serverItem?.metaData?.description
	const isMarketplaceItem = serverItem.type === "marketplace"
	const isInstalled = serverItem?.metaData?.isInstalled
	const isDisabled = serverItem.data.disabled

	// ibm_change: Use badge utility for consistent badge display
	const { statusText, statusColor } = getMcpServerBadges(serverItem, t, isMarketplaceEnabled)

	// Handle install button click
	const handleInstall = (e: React.MouseEvent) => {
		e.stopPropagation()
		if (isMarketplaceItem && onInstall && serverItem?.metaData?.id) {
			onInstall(serverItem.metaData.id)
		}
	}

	// Build action slot (Install button for marketplace servers)
	const getActionSlot = () => {
		// ibm_change: Only show install button if marketplace is enabled
		if (isMarketplaceItem && !isInstalled && isMarketplaceEnabled) {
			return (
				<StandardTooltip content={t("ibmSettings:mcp.actions.install_server")}>
					<Button variant="outline" size="sm" onClick={handleInstall}>
						{t("common:actions.install")}
					</Button>
				</StandardTooltip>
			)
		}
		return undefined
	}

	// Build metadata (author line or server type)
	const getMetadata = () => {
		if (author) {
			return `${t("ibmSettings:shared.by_author")} ${author}`
		}
		return undefined
	}

	// Build status icon (connection status indicator)
	// Only show for installed servers (not for marketplace items that aren't installed)
	const getStatusIcon = () => {
		if (isMarketplaceItem && !isInstalled) {
			return undefined
		}

		// Get connection status text for tooltip
		const getConnectionStatusText = () => {
			if (isDisabled) {
				return t("ibmSettings:mcp.status.disabled")
			}
			switch (serverItem.data.status) {
				case "connected":
					return t("ibmSettings:mcp.status.connected")
				case "connecting":
					return t("ibmSettings:mcp.status.connecting")
				case "disconnected":
					return t("ibmSettings:mcp.status.disconnected")
				default:
					return t("ibmSettings:mcp.status.disconnected")
			}
		}

		return (
			<StandardTooltip content={getConnectionStatusText()}>
				<Circle size={8} fill={statusColor} color={statusColor} className="flex-shrink-0" />
			</StandardTooltip>
		)
	}

	return (
		<ItemTile
			title={name}
			description={description}
			statusIcon={getStatusIcon()}
			metadata={getMetadata()}
			statusText={statusText}
			actionSlot={getActionSlot()}
			onClick={onClick || (() => {})} // Always provide onClick to maintain role="button" and tabIndex
			className={isDisabled ? "opacity-60" : ""}
			isLoading={isLoading}
		/>
	)
}

