import * as React from "react"
import { Select as UISelect, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui"
import { useAppTranslation } from "@/i18n/TranslationContext"
import { ConditionDefinition } from "./BaseActionComponentProps"
import { evaluateCondition } from "../../utils/conditionEvaluator"

export interface SelectOption {
	/** The value of the option */
	value: string
	/** The label of the option (translation key or direct text) */
	label: string
	/** Optional description or additional text */
	description?: string
	/** Optional condition to determine if this option should be shown */
	condition?: ConditionDefinition
}

export interface SelectProps {
	/** Current select value */
	value: string
	/** Callback when select value changes */
	setValue: (value: string) => void
	/** Available options for the select */
	options: SelectOption[]
	/** Placeholder text (translation key) */
	placeholder?: string
	/** Whether to translate option labels */
	translateLabels?: boolean
	/** Label for the select (translation key) */
	label?: string
	/** Description for the select (translation key) */
	description?: string
	/** Whether the component is disabled */
	disabled?: boolean
	/** CSS class name to apply to the component */
	className?: string
	/** Test ID for the component */
	testId?: string
	/** Extension state for condition evaluation (optional) */
	state?: any
	/** Default value to fall back to when current value becomes invalid */
	defaultValue?: string
}

/**
 * Pure Select component for settings
 * Receives value and setValue props from wrapper components
 * This component is state-agnostic and can be used with any state management approach
 */
const Select: React.FC<SelectProps> = ({
	value,
	setValue,
	options,
	placeholder,
	disabled = false,
	testId,
	className,
	translateLabels = true,
	label,
	description,
	state,
	defaultValue,
}) => {
	const { t } = useAppTranslation()

	// Filter options based on conditions
	const filteredOptions = React.useMemo(() => {
		if (!state) return options

		return options.filter((option) => {
			if (!option.condition) return true
			return evaluateCondition(option.condition, state)
		})
	}, [options, state])

	// Auto-reset to default if current value is not in filtered options
	React.useEffect(() => {
		// Only validate if we have filtered options and a setValue function
		if (!filteredOptions.length || !setValue) return

		// Check if current value is valid (exists in filtered options)
		const isValueValid = filteredOptions.some((option) => option.value === value)

		if (!isValueValid) {
			// Determine fallback value: prefer defaultValue, otherwise use first filtered option
			const fallbackValue = defaultValue || filteredOptions[0]?.value

			if (fallbackValue && fallbackValue !== value) {
				// Reset to fallback value
				setValue(fallbackValue)
			}
		}
	}, [value, filteredOptions, setValue, defaultValue])

	return (
		<div className="flex flex-col gap-1">
			{label && <label className="block text-sm font-medium">{t(label)}</label>}
			{description && <div className="text-vscode-descriptionForeground text-sm mb-1">{t(description)}</div>}
			<UISelect value={value} onValueChange={setValue} disabled={disabled} data-testid={testId}>
				<SelectTrigger className={`w-full ${className || ""}`}>
					<SelectValue placeholder={placeholder ? t(placeholder) : undefined} />
				</SelectTrigger>
				<SelectContent>
					{filteredOptions.map((option) => (
						<SelectItem key={option.value} value={option.value}>
							{translateLabels ? t(option.label) : option.label}
							{option.description && (
								<span className="text-sm text-vscode-descriptionForeground ml-2">
									{translateLabels ? t(option.description) : option.description}
								</span>
							)}
						</SelectItem>
					))}
				</SelectContent>
			</UISelect>
		</div>
	)
}

export default Select

