import React from "react"
import { useAppTranslation } from "@/i18n/TranslationContext"
import { useExtensionState } from "@/context/ExtensionStateContext"
import { setActiveProfile } from "@/ibm/utils/userProfile"
import type { UserProfile, ProfileId } from "@roo/IBM/userProfileTypes"
import { shouldShowTeamInfo } from "@roo/IBM/userProfileHelpers"
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select"

/**
 * Team Selector Component
 *
 * Displays a dropdown of available team profiles and allows users to switch between them.
 * Only renders when:
 * - Multiple profiles are available (profiles.length > 1)
 *
 * Profile display format:
 * - "team_name" (when only one instance)
 * - "instance_name: team_name" (when multiple instances)
 * Profile ID format: "instance_id:team_id"
 */
const TeamSelector: React.FC = () => {
	const { t } = useAppTranslation()
	const { activeProfile, availableProfiles } = useExtensionState()

	/**
	 * Generate ProfileId from a UserProfile
	 * Format: "instance_id:team_id"
	 */
	const getProfileId = (profile: UserProfile): ProfileId | null => {
		if (profile.instance_id && profile.team_id) {
			return `${profile.instance_id}:${profile.team_id}`
		}
		return null
	}

	/**
	 * Check if there are multiple unique instances
	 */
	const hasMultipleInstances = (): boolean => {
		if (!availableProfiles || availableProfiles.length < 2) {
			return false
		}
		const uniqueInstances = new Set(availableProfiles.map((p) => p.instance_id))
		return uniqueInstances.size > 1
	}

	/**
	 * Format profile display name
	 * Case 1: Multiple instances with multiple teams → "instance_name: team_name"
	 * Case 2: Single instance, multiple teams → "team_name"
	 * Case 3: Multiple instances, single team per instance → "instance_name"
	 */
	const getProfileDisplayName = (profile: UserProfile): string => {
		const teamName = profile.team_name || profile.team_id || t("ibmSettings:general.unknownTeam")
		const instanceName =
			profile.instance_name || profile.instance_id || t("ibmSettings:general.unknownInstance")

		// Case 2: Single instance, multiple teams → show team name only
		if (!hasMultipleInstances()) {
			return teamName
		}

		// Case 3: Multiple instances, single team per instance → show instance only
		if (!shouldShowTeamInfo(availableProfiles)) {
			return instanceName
		}

		// Case 1: Multiple instances with multiple teams → show "instance: team"
		return `${instanceName}: ${teamName}`
	}

	/**
	 * Get the current active profile ID
	 */
	const currentProfileId = activeProfile ? getProfileId(activeProfile) : null

	/**
	 * Handle profile selection change
	 */
	const handleProfileChange = (value: string) => {
		const newProfileId = value as ProfileId

		if (!newProfileId || newProfileId === currentProfileId) {
			return
		}

		// Extension state will be updated via profilesUpdated message
		setActiveProfile(newProfileId)
	}

	// Don't render if less than 2 profiles (need multiple profiles to show selector)
	if (!availableProfiles || availableProfiles.length < 2) {
		return null
	}

	return (
		<tr className="h-6 border-t border-vscode-editor-background">
			<td className="py-4 pl-2 text-sm font-medium">{t("ibmSettings:general.team")}</td>
			<td className="pl-4 text-sm font-medium">
				<Select value={currentProfileId || ""} onValueChange={handleProfileChange}>
					<SelectTrigger className="w-full max-w-[300px]">
						<SelectValue />
					</SelectTrigger>
					<SelectContent>
						{availableProfiles.map((profile) => {
							const profileId = getProfileId(profile)
							if (!profileId) return null

							return (
								<SelectItem key={profileId} value={profileId}>
									{getProfileDisplayName(profile)}
								</SelectItem>
							)
						})}
					</SelectContent>
				</Select>
			</td>
		</tr>
	)
}

export default TeamSelector

