import { useState, useEffect } from "react"
import { vscode } from "@/utils/vscode"
import { logger } from "@/ibm/utils/logger"
import { createMessageListener } from "@/ibm/utils/messageListener"

/**
 * Common hook for fetching marketplace data with error handling
 * Used by both useMcpServers and useModes hooks
 * 
 * @param isEnabled - Whether marketplace is enabled (from feature flag)
 * @param logContext - Context string for logging (e.g., "MCP" or "Modes")
 * @returns Object containing loading state, error state, and retry function
 */
export const useMarketplaceFetch = (isEnabled: boolean, logContext: string) => {
	const [initialMarketplaceItemsLoaded, setInitialMarketplaceItemsLoaded] = useState(false)
	const [marketplaceFetchError, setMarketplaceFetchError] = useState(false)
	const [isMarketplaceNetworkError, setIsMarketplaceNetworkError] = useState(false)

	// Fetch marketplace data when enabled and not yet loaded
	useEffect(() => {
		if (!initialMarketplaceItemsLoaded && isEnabled) {
			// Clear any previous error state
			setMarketplaceFetchError(false)
			setIsMarketplaceNetworkError(false)
			
			// Send fetch request
			vscode.postMessage({
				type: "fetchMarketplaceData",
			})
			
			// Set up listener for response using messageListener utility
			const cleanup = createMessageListener({
				messageType: "marketplaceData",
				matchCondition: (message) => {
					// Check if the message indicates an error (networkError or errors array)
					if (message.networkError || (message.errors && message.errors.length > 0)) {
						return true // Match this message to handle the error
					}
					// Also match successful responses
					return true
				},
				onSuccess: (message) => {
					// Check if this is actually an error response
					if (message.networkError || (message.errors && message.errors.length > 0)) {
						logger.error(`[${logContext}]: Failed to fetch marketplace data`, {
							networkError: message.networkError,
							errors: message.errors
						})
						setInitialMarketplaceItemsLoaded(true) // Mark as loaded even on error
						setMarketplaceFetchError(true)
						setIsMarketplaceNetworkError(!!message.networkError) // Track if it's a network/VPN error
					} else {
						// Successful fetch
						setInitialMarketplaceItemsLoaded(true)
						setMarketplaceFetchError(false)
						setIsMarketplaceNetworkError(false)
					}
				},
				onError: (error) => {
					logger.error(`[${logContext}]: Timeout waiting for marketplace data`, error)
					setInitialMarketplaceItemsLoaded(true) // Mark as loaded even on timeout
					setMarketplaceFetchError(true)
				},
				timeout: 30000 // 30 second timeout
			})
			
			return cleanup
		}
	}, [initialMarketplaceItemsLoaded, isEnabled, logContext])

	// Retry function to refetch marketplace data
	const retryMarketplaceFetch = () => {
		// Reset states to trigger refetch
		setInitialMarketplaceItemsLoaded(false)
		setMarketplaceFetchError(false)
		setIsMarketplaceNetworkError(false)
	}

	return {
		initialMarketplaceItemsLoaded,
		marketplaceFetchError,
		isMarketplaceNetworkError,
		retryMarketplaceFetch,
	}
}

