import React from "react"
import { VSCodeCheckbox } from "@vscode/webview-ui-toolkit/react"
import { McpTool } from "@roo/mcp"
import { useAppTranslation } from "@/i18n/TranslationContext"
import { vscode } from "@/utils/vscode"
import { StandardTooltip } from "@/components/ui"
import SectionRowExpandable from "../../../components/SectionRowExpandable"
import ToggleButton from "../../../../common/toggleButton/ToggleButton"

type McpToolSettingRowProps = {
	tool: McpTool
	serverName: string
	serverSource: "global" | "project"
	toolToggle?: (newValue: boolean) => void
}

const McpToolSettingRow: React.FC<McpToolSettingRowProps> = ({ tool, serverName, serverSource }) => {
	const { t } = useAppTranslation()
	const isToolEnabled = tool.enabledForPrompt ?? true

	const handleAlwaysAllowChange = () => {
		const newValue = !tool.alwaysAllow
		vscode.postMessage({
			type: "toggleToolAlwaysAllow",
			serverName,
			source: serverSource,
			toolName: tool.name,
			alwaysAllow: newValue,
		})
	}

	const handleEnabledForPromptChange = (newValue: boolean) => {
		vscode.postMessage({
			type: "toggleToolEnabledForPrompt",
			serverName,
			source: serverSource,
			toolName: tool.name,
			isEnabled: newValue,
		})
	}

	// Prepare parameters content
	const hasParameters =
		tool.inputSchema &&
		"properties" in tool.inputSchema &&
		Object.keys(tool.inputSchema.properties as Record<string, any>).length > 0

	const parametersContent =
		hasParameters && tool.inputSchema && "properties" in tool.inputSchema ? (
			<div>
				<div className="text-xs uppercase opacity-80 text-vscode-descriptionForeground">
					{t("ibmSettings:mcp.details.parameters")}
				</div>
				<table>
					<tbody>
						{Object.entries(tool.inputSchema.properties as Record<string, any>).map(
							([paramName, schema]) => {
								const isRequired =
									tool.inputSchema &&
									"required" in tool.inputSchema &&
									Array.isArray(tool.inputSchema.required) &&
									tool.inputSchema.required.includes(paramName)

								return (
									<tr key={paramName}>
										<td className="text-vscode-foreground pr-3 py-1 align-top whitespace-nowrap">
											{paramName}
											{isRequired && <span className="text-vscode-errorForeground">*</span>}
										</td>
										<td className="text-vscode-descriptionForeground py-1 align-top">
											{schema.description ||
												t("ibmSettings:mcp.details.no_parameter_description")}
										</td>
									</tr>
								)
							},
						)}
					</tbody>
				</table>
			</div>
		) : (
			<div className="text-xs text-vscode-descriptionForeground opacity-60">
				{t("ibmSettings:mcp.details.no_parameters")}
			</div>
		)

	// Title action component - toggle for enabling/disabling the tool and always allow checkbox
	const titleActionComponent = (
		<div className="flex items-center gap-3">
			<StandardTooltip content={t("mcp:tool.alwaysAllowTooltip")}>
				<VSCodeCheckbox
					checked={tool.alwaysAllow}
					onChange={handleAlwaysAllowChange}
					data-tool={tool.name}
					className="text-xs">
					<span className="text-vscode-descriptionForeground whitespace-nowrap">
						{t("mcp:tool.alwaysAllow")}
					</span>
				</VSCodeCheckbox>
			</StandardTooltip>
			<StandardTooltip content={t("mcp:tool.enabledForPromptTooltip")} asChild={false}>
				<div>
					<ToggleButton
						checked={isToolEnabled}
						onChange={handleEnabledForPromptChange}
						noContainer={true}
						size="compact"
					/>
				</div>
			</StandardTooltip>
		</div>
	)

	return (
		<SectionRowExpandable
			title={tool.name}
			description={tool.description || undefined}
			maxDescriptionLength={200}
			titleActionComponent={titleActionComponent}>
			{parametersContent}
		</SectionRowExpandable>
	)
}

export default McpToolSettingRow
