import React from "react"
import { Loader2, AlertCircle, RefreshCw } from "lucide-react"
import { Button } from "@/components/ui"
import { useAppTranslation } from "@/i18n/TranslationContext"

interface MarketplaceLoadingStateProps {
	/**
	 * Whether marketplace items are still being loaded initially
	 */
	isLoading: boolean
	
	/**
	 * Whether there was an error fetching marketplace items
	 */
	hasError: boolean
	
	/**
	 * Whether the error is a marketplace network/VPN error
	 */
	isMarketplaceNetworkError: boolean
	
	/**
	 * Callback when retry button is clicked
	 */
	onRetry: () => void
}

/**
 * Common component for displaying marketplace loading and error states
 * Used below the tiles in MCP and Modes overview grids
 */
export const MarketplaceLoadingState: React.FC<MarketplaceLoadingStateProps> = ({
	isLoading,
	hasError,
	isMarketplaceNetworkError,
	onRetry
}) => {
	const { t } = useAppTranslation()
	
	// Don't render anything if not loading and no error
	if (!isLoading && !hasError) {
		return null
	}
	
	return (
		<>
			{/* Loading state */}
			{isLoading && !hasError && (
				<div className="flex items-center justify-center gap-2 py-4 text-vscode-descriptionForeground">
					<Loader2 className="h-4 w-4 animate-spin" />
					<p className="text-sm">{t("ibmSettings:marketplace.fetching_items")}</p>
				</div>
			)}
			
			{/* Error state with retry button */}
			{hasError && (
				<div className="flex flex-col items-center justify-center gap-3 py-4 text-vscode-descriptionForeground">
					<div className="flex flex-col items-center gap-2">
						<div className="flex items-center gap-2">
							<AlertCircle className="h-4 w-4 text-vscode-errorForeground" />
							<p className="text-sm font-medium">
								{isMarketplaceNetworkError
									? t("ibmSettings:marketplace.vpn_required")
									: t("ibmSettings:marketplace.fetch_error")
								}
							</p>
						</div>
						<p className="text-xs text-center max-w-md">
							{isMarketplaceNetworkError
								? t("ibmSettings:marketplace.vpn_description")
								: t("ibmSettings:marketplace.error_description")
							}
						</p>
					</div>
					<Button
						variant="secondary"
						size="sm"
						onClick={onRetry}
						className="flex items-center gap-2"
					>
						<RefreshCw className="h-3 w-3" />
						{t("ibmSettings:marketplace.retry_connection")}
					</Button>
				</div>
			)}
		</>
	)
}

