import React, { useMemo } from "react"
import { settingsNavigation, SettingsTabId } from "./SettingsPage"
import { useAppTranslation } from "@/i18n/TranslationContext"
import TabRenderer from "./components/TabRenderer"
import SearchEmptyState from "./components/SearchEmptyState"
import { useScrollbarOnScroll } from "../../hooks/useScrollbarOnScroll"
import { useSettingsSearch } from "./context/SettingsSearchContext"

interface SettingsContentProps {
	activeTab: SettingsTabId
}

const SettingsContent: React.FC<SettingsContentProps> = ({ activeTab }) => {
	const { t } = useAppTranslation()
	const { scrollRef, scrollbarClassName } = useScrollbarOnScroll()
	const { isSearchActive, searchResults, searchQuery, matchCountsByTab } = useSettingsSearch()

	// Get the navigation item for the active tab
	const navItem = settingsNavigation.byId[activeTab]

	// Build set of matched setting IDs for the current tab
	const matchedSettingIds = useMemo(() => {
		if (!isSearchActive) return null

		const ids = new Set<string>()
		searchResults.forEach((result) => {
			if (result.item.tabId === activeTab) {
				ids.add(result.item.id)
				// Also add parent if this is a child
				if (result.item.parentId) {
					ids.add(result.item.parentId)
				}
			}
		})
		return ids
	}, [isSearchActive, searchResults, activeTab])

	// Check if current tab has any matches
	const tabHasMatches = matchCountsByTab[activeTab] > 0

	// Render the appropriate tab content based on activeTab
	const renderTabContent = () => {
		// Priority: component > tabDefinition > fallback

		// Check if both component and tabDefinition exist (should not happen)
		if (navItem?.component && navItem?.tabDefinition) {
			console.warn(
				`Tab "${activeTab}" has both component and tabDefinition. Using component (direct reference takes priority).`,
			)
		}

		// If the tab has a direct component reference, render it
		if (navItem?.component) {
			const Component = navItem.component

			// If searching with no matches in this component tab, show empty state
			if (isSearchActive && !tabHasMatches) {
				return <SearchEmptyState query={searchQuery} />
			}

			// Otherwise render the component (with or without search active)
			return <Component />
		}

		// If the tab has a JSON definition, use TabRenderer with filtering
		if (navItem?.tabDefinition) {
			// If searching and no matches in this tab, show empty state
			if (isSearchActive && !tabHasMatches) {
				return <SearchEmptyState query={searchQuery} />
			}

			return (
				<TabRenderer
					definition={navItem.tabDefinition}
					matchedSettingIds={matchedSettingIds}
					isSearchActive={isSearchActive}
				/>
			)
		}

		// Fallback for tabs with neither definition nor component
		return <div className="text-vscode-descriptionForeground p-2">No content available for this tab.</div>
	}

	return (
		<div ref={scrollRef} className={`overflow-y-auto flex-1 ${scrollbarClassName}`}>
			<div className="px-2 max-w-[718px] [@media(min-width:848px)]:max-w-[848px] min-w-[350px] pb-10">
				<div className="text-[14px] font-medium text-vscode-descriptionForeground p-2">
					{t(navItem?.labelTranslationKey)}
					{isSearchActive && tabHasMatches && (
						<span className="ml-2 text-xs text-vscode-badge-foreground bg-vscode-badge-background px-1.5 py-0.5 rounded">
							{matchCountsByTab[activeTab]} {t("ibmSettings:search.matches")}
						</span>
					)}
				</div>
				{/* ibm_change: Add key prop to force component remount on tab change, preventing state persistence */}
				<div key={activeTab}>{renderTabContent()}</div>
			</div>
		</div>
	)
}

export default SettingsContent

