/**
 * Comparison operators for condition evaluation
 */
export enum ConditionOperator {
	EQUALS = "equals",
	NOT_EQUALS = "notEquals",
	GREATER_THAN = "greaterThan",
	LESS_THAN = "lessThan",
	CONTAINS = "contains",
}

/**
 * Defines a condition for conditional rendering of settings components
 * This structure must be serializable as pure JSON
 */
export interface ConditionDefinition {
	/** State property to check */
	property: string
	/** Value to compare against */
	value: any
	/** Comparison operator (equals, notEquals, etc.) */
	operator?: ConditionOperator
}

/**
 * Base properties for all action components
 */
export interface BaseActionComponentProps {
	/** CSS class name to apply to the component */
	className?: string
	/** Whether the component is disabled */
	disabled?: boolean
	/** Test ID for the component */
	testId?: string
	/** Condition to determine if this component should be rendered */
	condition?: ConditionDefinition
}

