import React from "react"
import { VSCodeCheckbox, VSCodeBadge } from "@vscode/webview-ui-toolkit/react"
import { useAppTranslation } from "@/i18n/TranslationContext"
import { getToolGroupLabel } from "./modeUtils"

interface ToolGroupSelectorProps {
	/** Available tool groups to display */
	availableToolGroups: string[]
	/** Currently selected tool groups */
	selectedTools: string[]
	/** Callback when a tool is toggled */
	onToolToggle: (tool: string, checked: boolean) => void
	/** Whether the selector is read-only (for built-in modes) */
	readOnly?: boolean
	/** Helper text to display below the selector */
	helperText?: string
	/** Label for the selector */
	label: string
}

/**
 * ToolGroupSelector Component
 *
 * Displays and manages tool group selection for modes.
 * Can be used in both editable (custom modes) and read-only (built-in modes) states.
 */
export const ToolGroupSelector: React.FC<ToolGroupSelectorProps> = ({
	availableToolGroups,
	selectedTools,
	onToolToggle,
	readOnly = false,
	helperText,
	label,
}) => {
	const { t } = useAppTranslation()
	if (readOnly) {
		// Read-only view for built-in modes - show as badges
		return (
			<div className="p-2 pb-3">
				<label className="block text-sm font-medium text-vscode-foreground mb-1">
					{label}
				</label>
				{helperText && (
					<div className="text-xs text-vscode-descriptionForeground mb-2">
						{helperText}
					</div>
				)}
				<div className="flex flex-wrap gap-2">
					{selectedTools.map((group) => (
						<VSCodeBadge
							key={group}
							className="capitalize"
						>
							{getToolGroupLabel(group, t)}
						</VSCodeBadge>
					))}
				</div>
			</div>
		)
	}

	// Editable view for custom modes - show as checkboxes
	return (
		<div className="p-2 pb-3">
			<label className="block text-sm font-medium text-vscode-foreground mb-1">
				{label}
			</label>
			{helperText && (
				<div className="text-xs text-vscode-descriptionForeground mb-2">
					{helperText}
				</div>
			)}
			<div className="space-y-2">
				{availableToolGroups.map((tool) => (
					<VSCodeCheckbox
						key={tool}
						checked={selectedTools.includes(tool)}
						onChange={(e: any) => onToolToggle(tool, e.target.checked)}
					>
						{getToolGroupLabel(tool, t)}
					</VSCodeCheckbox>
				))}
			</div>
		</div>
	)
}

