import { useEffect, useState } from "react"
import { vscode } from "@/utils/vscode"

/**
 * Custom hook to access VSCode workspace state values
 * Provides a way to read workspace state with automatic updates
 * when the state changes externally
 *
 * @param stateKey - The workspace state key (e.g., "ibm-bob-config.llmAttributionMode")
 * @param defaultValue - Default value if state is not found
 * @returns The current state value
 *
 * @example
 * const mode = useWorkspaceState<LlmAttrMode>("ibm-bob-config.llmAttributionMode", "comments")
 */
export function useWorkspaceState<T = any>(stateKey: string, defaultValue: T): T {
	const [value, setValue] = useState<T>(defaultValue)

	// Request the current workspace state value when component mounts or stateKey changes
	useEffect(() => {
		vscode.postMessage({
			type: "getWorkspaceState",
			key: stateKey,
		})
	}, [stateKey])

	// Listen for workspace state updates from the extension
	useEffect(() => {
		const messageHandler = (event: MessageEvent) => {
			const message = event.data
			if (message.type === "workspaceState" && message.key === stateKey) {
				setValue(message.value ?? defaultValue)
			}
		}

		window.addEventListener("message", messageHandler)
		return () => window.removeEventListener("message", messageHandler)
	}, [stateKey, defaultValue])

	return value
}

