import { useMemo, useCallback } from "react"
import { useAppTranslation } from "@/i18n/TranslationContext"
import { useExtensionState } from "@/context/ExtensionStateContext"
import {
	SettingsTabDefinition,
	SectionDefinition,
	SectionRowDefinition,
	ConditionDefinition,
} from "../SettingsDefinition"
import { settingsNavigation, SettingsTabId, ComponentTabSearchMetadata } from "../SettingsPage"
import { evaluateCondition } from "../utils/evaluateCondition"

// ============================================================================
// Types
// ============================================================================

/**
 * Represents a single searchable setting item
 */
export interface SearchableSettingItem {
	/** Unique identifier: "tabId/sectionId/rowIndex" or "tabId/sectionId/rowIndex/childIndex" */
	id: string
	/** Which tab this setting belongs to */
	tabId: SettingsTabId
	/** Section identifier within the tab */
	sectionId: string
	/** Row index within section */
	rowIndex: number
	/** Child index if this is a nested setting */
	childIndex?: number
	/** Original i18n key for title */
	titleKey: string
	/** Original i18n key for description */
	descriptionKey?: string
	/** Translated title text for search */
	translatedTitle: string
	/** Translated description text for search */
	translatedDescription?: string
	/** Combined searchable string (title + description + tab name) */
	searchStr: string
	/** Tab display name for showing in results */
	tabLabel: string
	/** Section title for display (translated) */
	sectionTitle?: string
	/** Parent ID if this is a child setting */
	parentId?: string
}

/**
 * Search result with match positions for highlighting
 */
export interface SettingsSearchResult {
	/** The matched setting item */
	item: SearchableSettingItem
	/** Positions in the title text specifically */
	titlePositions: number[]
	/** Positions in the description text specifically */
	descriptionPositions: number[]
}

interface UseSettingsIndexOptions {
	/** Whether to include settings hidden by conditions (default: false) */
	includeConditionalSettings?: boolean
}

/** Translation function type */
type TranslateFn = (key: string) => string

/** Context for building searchable items */
interface IndexingContext {
	t: TranslateFn
	extensionState: Record<string, unknown>
	includeConditionalSettings: boolean
}

// ============================================================================
// Pure Utility Functions
// ============================================================================

/**
 * Finds all positions of a substring in text (case-insensitive).
 * Returns an array of character indices that are part of matches.
 */
function findSubstringPositions(text: string, query: string): number[] {
	const lowerText = text.toLowerCase()
	const lowerQuery = query.toLowerCase()
	const positions: number[] = []
	let startIndex = 0

	while (true) {
		const index = lowerText.indexOf(lowerQuery, startIndex)
		if (index === -1) break

		for (let i = 0; i < query.length; i++) {
			positions.push(index + i)
		}
		startIndex = index + 1
	}

	return positions
}

/**
 * Splits a query into normalized words.
 */
function splitQueryIntoWords(query: string): string[] {
	return query.toLowerCase().split(/\s+/).filter((w) => w.length > 0)
}

/**
 * Checks if text matches query using word-based matching.
 * All words must appear as substrings (in any order).
 */
function textMatchesQuery(text: string, query: string): boolean {
	const lowerText = text.toLowerCase()
	const words = splitQueryIntoWords(query)

	if (words.length === 0) return false
	return words.every((word) => lowerText.includes(word))
}

/**
 * Builds a search string from parts, filtering out undefined values.
 */
function buildSearchString(parts: (string | undefined)[]): string {
	return parts.filter(Boolean).join(" ")
}

/**
 * Checks if a condition is met, considering the includeConditionalSettings option.
 */
function isConditionMet(
	condition: ConditionDefinition | undefined,
	ctx: IndexingContext,
): boolean {
	if (!condition) return true
	if (ctx.includeConditionalSettings) return true
	return evaluateCondition(condition, ctx.extensionState)
}

// ============================================================================
// Indexing Helper Functions
// ============================================================================

/**
 * Extracts searchable props from a child element.
 */
function extractChildProps(child: unknown): {
	label?: string
	description?: string
	condition?: ConditionDefinition
} {
	const childObj = child as Record<string, unknown>
	const props =
		"props" in childObj
			? childObj.props
			: "actionComponent" in childObj
				? (childObj.actionComponent as Record<string, unknown>)?.props
				: undefined

	const propsObj = props as Record<string, unknown> | undefined

	return {
		label: propsObj && "label" in propsObj ? (propsObj.label as string) : undefined,
		description: propsObj && "description" in propsObj ? (propsObj.description as string) : undefined,
		condition: "condition" in childObj ? (childObj.condition as ConditionDefinition) : undefined,
	}
}

/**
 * Creates a searchable item for a child row.
 */
function createChildItem(
	child: unknown,
	childIndex: number,
	parentId: string,
	tabId: SettingsTabId,
	sectionId: string,
	rowIndex: number,
	tabLabel: string,
	sectionTitle: string | undefined,
	ctx: IndexingContext,
): SearchableSettingItem | null {
	const { label, description, condition } = extractChildProps(child)

	// Skip if no searchable text
	if (!label && !description) return null

	// Check condition
	if (!isConditionMet(condition, ctx)) return null

	const translatedLabel = label ? ctx.t(label) : ""
	const translatedDescription = description ? ctx.t(description) : undefined

	return {
		id: `${tabId}/${sectionId}/${rowIndex}/${childIndex}`,
		tabId,
		sectionId,
		rowIndex,
		childIndex,
		titleKey: label ?? "",
		descriptionKey: description,
		translatedTitle: translatedLabel,
		translatedDescription,
		searchStr: buildSearchString([translatedLabel, translatedDescription, tabLabel, sectionTitle]),
		tabLabel,
		sectionTitle,
		parentId,
	}
}

/**
 * Creates a searchable item for a row and its children.
 */
function indexRow(
	row: SectionRowDefinition,
	rowIndex: number,
	tabId: SettingsTabId,
	sectionId: string,
	tabLabel: string,
	sectionTitle: string | undefined,
	ctx: IndexingContext,
): SearchableSettingItem[] {
	// Check row condition
	if (!isConditionMet(row.condition, ctx)) return []

	const translatedTitle = ctx.t(row.title)
	const translatedDescription = row.description ? ctx.t(row.description) : undefined
	const id = `${tabId}/${sectionId}/${rowIndex}`

	const items: SearchableSettingItem[] = [
		{
			id,
			tabId,
			sectionId,
			rowIndex,
			titleKey: row.title,
			descriptionKey: row.description,
			translatedTitle,
			translatedDescription,
			searchStr: buildSearchString([translatedTitle, translatedDescription, tabLabel, sectionTitle]),
			tabLabel,
			sectionTitle,
		},
	]

	// Index children
	if (row.children) {
		for (let childIndex = 0; childIndex < row.children.length; childIndex++) {
			const childItem = createChildItem(
				row.children[childIndex],
				childIndex,
				id,
				tabId,
				sectionId,
				rowIndex,
				tabLabel,
				sectionTitle,
				ctx,
			)
			if (childItem) {
				items.push(childItem)
			}
		}
	}

	return items
}

/**
 * Indexes all rows in a section.
 */
function indexSection(
	section: SectionDefinition,
	sectionIndex: number,
	tabId: SettingsTabId,
	tabLabel: string,
	ctx: IndexingContext,
): SearchableSettingItem[] {
	// Check section condition first
	if (!isConditionMet(section.condition, ctx)) return []

	const sectionId = (section as { sectionId?: string }).sectionId ?? `section-${sectionIndex}`
	const sectionTitle = section.title ? ctx.t(section.title) : undefined
	const items: SearchableSettingItem[] = []

	// Index section-level content for customComponent sections
	if (section.customComponent && (section.title || section.description)) {
		const translatedTitle = section.title ? ctx.t(section.title) : ""
		const translatedDescription =
			typeof section.description === "string" ? ctx.t(section.description) : undefined

		items.push({
			id: `${tabId}/${sectionId}/custom-section`,
			tabId,
			sectionId,
			rowIndex: -1,
			titleKey: section.title ?? "",
			descriptionKey: typeof section.description === "string" ? section.description : undefined,
			translatedTitle,
			translatedDescription,
			searchStr: buildSearchString([translatedTitle, translatedDescription, tabLabel]),
			tabLabel,
			sectionTitle,
			})
	}

	// Skip row indexing if no rows
	if (!section.rows) return items

	for (let rowIndex = 0; rowIndex < section.rows.length; rowIndex++) {
		const rowItems = indexRow(
			section.rows[rowIndex],
			rowIndex,
			tabId,
			sectionId,
			tabLabel,
			sectionTitle,
			ctx,
		)
		items.push(...rowItems)
	}

	return items
}

/**
 * Indexes all sections in a tab.
 */
function indexTab(
	navItem: (typeof settingsNavigation.items)[number],
	ctx: IndexingContext,
): SearchableSettingItem[] {
	// Skip component-based tabs (they don't have tabDefinition)
	if (!("tabDefinition" in navItem) || !navItem.tabDefinition) return []

	const tabId = navItem.id
	const tabLabel = ctx.t(navItem.labelTranslationKey)
	const tabDefinition = navItem.tabDefinition as SettingsTabDefinition

	const items: SearchableSettingItem[] = []

	for (let sectionIndex = 0; sectionIndex < tabDefinition.sections.length; sectionIndex++) {
		const sectionItems = indexSection(
			tabDefinition.sections[sectionIndex],
			sectionIndex,
			tabId,
			tabLabel,
			ctx,
		)
		items.push(...sectionItems)
	}

	return items
}

/**
 * Indexes a component-based tab using its searchMetadata.
 * This allows tabs that use direct React components (like MCP and Modes)
 * to be included in search results.
 */
function indexComponentTab(
	navItem: (typeof settingsNavigation.items)[number],
	ctx: IndexingContext,
): SearchableSettingItem[] {
	// Only process component-based tabs with searchMetadata
	if (!("component" in navItem) || !navItem.component) return []
	if (!("searchMetadata" in navItem) || !navItem.searchMetadata) return []

	const tabId = navItem.id
	const tabLabel = ctx.t(navItem.labelTranslationKey)
	const searchMetadata = navItem.searchMetadata as ComponentTabSearchMetadata
	const items: SearchableSettingItem[] = []

	searchMetadata.sections.forEach((section, sectionIndex) => {
		const sectionId = `component-section-${sectionIndex}`
		const sectionTitle = section.titleKey ? ctx.t(section.titleKey) : undefined

		// Index section-level content if present
		if (section.titleKey || section.descriptionKey) {
			const translatedTitle = section.titleKey ? ctx.t(section.titleKey) : ""
			const translatedDescription = section.descriptionKey ? ctx.t(section.descriptionKey) : undefined

			items.push({
				id: `${tabId}/${sectionId}/section`,
				tabId,
				sectionId,
				rowIndex: -1,
				titleKey: section.titleKey ?? "",
				descriptionKey: section.descriptionKey,
				translatedTitle,
				translatedDescription,
				searchStr: buildSearchString([translatedTitle, translatedDescription, tabLabel]),
				tabLabel,
				sectionTitle,
					})
		}

		// Index rows within the section
		section.rows?.forEach((row, rowIndex) => {
			const translatedTitle = ctx.t(row.titleKey)
			const translatedDescription = row.descriptionKey ? ctx.t(row.descriptionKey) : undefined

			items.push({
				id: `${tabId}/${sectionId}/${rowIndex}`,
				tabId,
				sectionId,
				rowIndex,
				titleKey: row.titleKey,
				descriptionKey: row.descriptionKey,
				translatedTitle,
				translatedDescription,
				searchStr: buildSearchString([translatedTitle, translatedDescription, tabLabel, sectionTitle]),
				tabLabel,
				sectionTitle,
					})
		})
	})

	return items
}

// ============================================================================
// Search Helper Functions
// ============================================================================

/**
 * Collects highlight positions for all query words in a text.
 */
function collectHighlightPositions(text: string | undefined, words: string[]): number[] {
	if (!text) return []

	const positionsSet = new Set<number>()
	for (const word of words) {
		for (const pos of findSubstringPositions(text, word)) {
			positionsSet.add(pos)
		}
	}

	return Array.from(positionsSet).sort((a, b) => a - b)
}

/**
 * Creates a search result for a matched item.
 */
function createSearchResult(item: SearchableSettingItem, query: string): SettingsSearchResult {
	const words = splitQueryIntoWords(query)

	return {
		item,
		titlePositions: collectHighlightPositions(item.translatedTitle, words),
		descriptionPositions: collectHighlightPositions(item.translatedDescription, words),
	}
}

/**
 * Sorts search results by relevance.
 */
function sortSearchResults(results: SettingsSearchResult[]): SettingsSearchResult[] {
	return results.sort((a, b) => {
		// Items with title matches come first
		const aHasTitleMatch = a.titlePositions.length > 0
		const bHasTitleMatch = b.titlePositions.length > 0

		if (aHasTitleMatch && !bHasTitleMatch) return -1
		if (!aHasTitleMatch && bHasTitleMatch) return 1

		// Then sort alphabetically by title
		return a.item.translatedTitle.localeCompare(b.item.translatedTitle)
	})
}

/**
 * Creates empty match counts for all tabs.
 * Exported for use in SettingsSearchContext.
 */
export function createEmptyTabCounts(): Record<SettingsTabId, number> {
	const counts: Record<string, number> = {}
	for (const item of settingsNavigation.items) {
		counts[item.id] = 0
	}
	return counts as Record<SettingsTabId, number>
}

// ============================================================================
// Hook
// ============================================================================

/**
 * Hook that builds a searchable index of all settings from JSON definitions
 * and provides fuzzy search functionality.
 */
export function useSettingsIndex(options: UseSettingsIndexOptions = {}) {
	const { includeConditionalSettings = false } = options
	const { t } = useAppTranslation()
	const extensionState = useExtensionState()

	// Build the searchable items from all JSON-defined tabs
	const searchableItems = useMemo(() => {
		const ctx: IndexingContext = {
			t,
			extensionState: extensionState as unknown as Record<string, unknown>,
			includeConditionalSettings,
		}

		const items: SearchableSettingItem[] = []
		for (const navItem of settingsNavigation.items) {
			items.push(...indexTab(navItem, ctx))
			items.push(...indexComponentTab(navItem, ctx))
		}
		return items
	}, [t, extensionState, includeConditionalSettings])

	/**
	 * Search for settings matching the query.
	 */
	const search = useCallback(
		(query: string): SettingsSearchResult[] => {
			const trimmedQuery = query.trim()
			if (!trimmedQuery) return []

			const results: SettingsSearchResult[] = []

			for (const item of searchableItems) {
				if (textMatchesQuery(item.searchStr, trimmedQuery)) {
					results.push(createSearchResult(item, trimmedQuery))
				}
			}

			return sortSearchResults(results)
		},
		[searchableItems],
	)

	/**
	 * Get match counts per tab for a given query.
	 */
	const getMatchCountsByTab = useCallback(
		(query: string): Record<SettingsTabId, number> => {
			const results = search(query)
			const counts = createEmptyTabCounts()

			for (const result of results) {
				counts[result.item.tabId]++
			}

			return counts
		},
		[search],
	)

	return {
		/** All searchable setting items */
		searchableItems,
		/** Search function that returns results with match positions */
		search,
		/** Get match counts per tab for showing badges */
		getMatchCountsByTab,
		/** Total number of indexed settings */
		totalSettings: searchableItems.length,
	}
}

