import React from "react"
import { Button } from "@/components/ui"

interface ConfirmationDialogProps {
	/** Whether the dialog is open */
	isOpen: boolean
	/** Dialog title */
	title: string
	/** Dialog message/description */
	message: string
	/** Text for the confirm button */
	confirmText: string
	/** Text for the cancel button */
	cancelText: string
	/** Whether the confirm action is in progress */
	isLoading?: boolean
	/** Callback when confirm button is clicked */
	onConfirm: () => void
	/** Callback when cancel button is clicked */
	onCancel: () => void
	/** Whether the confirm button should use destructive styling */
	isDestructive?: boolean
}

/**
 * Reusable confirmation dialog component.
 * Displays a modal dialog with a title, message, and confirm/cancel buttons.
 * 
 * @example
 * ```tsx
 * <ConfirmationDialog
 *   isOpen={deleteModal.isOpen}
 *   title="Delete Mode"
 *   message="Are you sure you want to delete this mode?"
 *   confirmText="Delete"
 *   cancelText="Cancel"
 *   isLoading={isDeleting}
 *   onConfirm={handleDelete}
 *   onCancel={deleteModal.close}
 *   isDestructive
 * />
 * ```
 */
export const ConfirmationDialog: React.FC<ConfirmationDialogProps> = ({
	isOpen,
	title,
	message,
	confirmText,
	cancelText,
	isLoading = false,
	onConfirm,
	onCancel,
	isDestructive = false,
}) => {
	if (!isOpen) {
		return null
	}

	return (
		<div className="fixed inset-0 flex items-center justify-center z-50">
			{/* Backdrop overlay with opacity */}
			<div className="absolute inset-0 bg-vscode-sideBar-background opacity-50" />
			
			{/* Modal container - sits above backdrop */}
			<div className="relative bg-vscode-editor-background rounded-lg p-3 max-w-md w-full mx-4 border border-vscode-panel-border">
				<div className="text-lg font-semibold text-vscode-foreground mb-2">
					{title}
				</div>
				<div className="text-sm text-vscode-descriptionForeground mb-3">
					{message}
				</div>
				<div className="flex justify-end gap-2">
					<Button
						variant="ghost"
						onClick={onCancel}
						disabled={isLoading}
					>
						{cancelText}
					</Button>
					<Button
						variant={isDestructive ? "destructive" : "primary"}
						onClick={onConfirm}
						disabled={isLoading}
					>
						{confirmText}
					</Button>
				</div>
			</div>
		</div>
	)
}

