import React from "react"
import { useAppTranslation } from "@/i18n/TranslationContext"
import SettingsSidebarItem from "./SettingsSidebarItem"
import SettingsSidebarFooter from "./SettingsSidebarFooter"
import { SettingsTabId, settingsNavigation } from "../SettingsPage"
import { useSettingsSearch } from "../context/SettingsSearchContext"

interface SettingsSidebarProps {
	activeTab: SettingsTabId
	onTabChange: (tab: SettingsTabId) => void
}

const SettingsSidebar: React.FC<SettingsSidebarProps> = ({ activeTab, onTabChange }) => {
	const { t } = useAppTranslation()
	const { isSearchActive, matchCountsByTab } = useSettingsSearch()

	return (
		<div className="min-w-[133px] w-fit flex-shrink-0 flex flex-col overflow-hidden">
			{/* Navigation items */}
			{settingsNavigation.items
				.filter((item) => item.visible !== false) // ibm_change: Filter out items with visible=false
				.map((item) => (
					<SettingsSidebarItem
						key={item.id}
						icon={item.icon}
						label={t(item.labelTranslationKey)}
						isActive={activeTab === item.id}
						onClick={() => onTabChange(item.id)}
						matchCount={matchCountsByTab[item.id]}
						isSearching={isSearchActive}
					/>
				))}

			{/* Footer with version and docs */}
			<SettingsSidebarFooter />
		</div>
	)
}

export default SettingsSidebar

