import React, { useState, useMemo, useEffect } from "react"
import { Trash2, RefreshCw, Edit } from "lucide-react"
import { useAppTranslation } from "@/i18n/TranslationContext"
import { MarketplaceItem } from "@roo-code/types"
import { Button, Select, SelectContent, SelectItem, SelectTrigger, SelectValue, StandardTooltip } from "@/components/ui"
import { SearchInput } from "@/ibm/components/common/SearchInput"
import { vscode } from "@/utils/vscode"
import ToggleButton from "@/ibm/components/common/toggleButton/ToggleButton"
import { canDeleteMcpServer, isMarketplaceMcpServer, useMcpServers, findMcpServerByName } from "./hooks/useMcpServers"
import { useMarketplaceInstall } from "./hooks/useMarketplaceInstall"
import Section from "../../components/Section"
import SectionRow from "../../components/SectionRow"
import SectionHeader from "../../components/SectionHeader"
import CollapsibleSection from "../../components/CollapsibleSection"
import { useExtensionState } from "@/context/ExtensionStateContext"
import { logger } from "@/ibm/utils/logger"
import { VSCodeBadge } from "@vscode/webview-ui-toolkit/react"
import { useModal } from "../../../../hooks/useModal"
import { ConfirmationDialog } from "../../components/ConfirmationDialog"
import { McpInstallModal, McpUninstallModal } from "@/ibm/components/settings/components/marketplace"
import { ItemOverview, OverviewHeader, createActionButton } from "../../components/common"
import McpToolSettingRow from "./components/McpToolSettingRow"
import McpResourceSetting from "./components/McpResourceSetting"
import { McpErrorSettingRow } from "./components/McpErrorSettingRow"
import { createMessageListener } from "@/ibm/utils/messageListener"
import { McpTool } from "@roo/mcp"

interface McpServerDetailsViewProps {
	serverId: string
	onBack: () => void
}


/**
 * McpServerDetailsView Component
 *
 * Displays detailed information about an MCP server with contextual action buttons.
 * Shows server metadata, errors (if any), tools, resources (if any), and network timeout configuration.
 * Layout uses sections (not tabs) following the Figma design.
 */
export const McpServerDetailsView: React.FC<McpServerDetailsViewProps> = ({ serverId, onBack }) => {
	const { t } = useAppTranslation()
	const { marketplaceItems, marketplaceInstalledMetadata, cwd } = useExtensionState()

	// Timeout options for network timeout dropdown (values in seconds to match backend)
	const timeoutOptions = useMemo(() => [
		{ value: 5, label: t("ibmSettings:mcp.details.timeout_5_seconds") },
		{ value: 10, label: t("ibmSettings:mcp.details.timeout_10_seconds") },
		{ value: 30, label: t("ibmSettings:mcp.details.timeout_30_seconds") },
		{ value: 60, label: t("ibmSettings:mcp.details.timeout_1_minute") },
		{ value: 120, label: t("ibmSettings:mcp.details.timeout_2_minutes") },
		{ value: 300, label: t("ibmSettings:mcp.details.timeout_5_minutes") },
		{ value: 600, label: t("ibmSettings:mcp.details.timeout_10_minutes") },
		{ value: 1800, label: t("ibmSettings:mcp.details.timeout_30_minutes") },
		{ value: 3600, label: t("ibmSettings:mcp.details.timeout_1_hour") },
	], [t])

	const { allMcpServers } = useMcpServers()

	// Find the live version of the selected server from the hook data
	// serverId can be either a marketplace item ID or a server name (for custom servers)
	const server = useMemo(() => {
		return findMcpServerByName(allMcpServers, serverId)
	}, [allMcpServers, serverId])

	// State for loading and confirmation dialogs
	const [isDeleting, setIsDeleting] = useState(false)
	const [timeoutValue, setTimeoutValue] = useState(server?.data.timeout || 60)
	const [toolSearchQuery, setToolSearchQuery] = useState("")
	const [toolFilterType, setToolFilterType] = useState<"all" | "enabled" | "disabled" | "alwaysAllowed">("all")
	// ibm_change: State to track edit mode
	const [isEditMode, setIsEditMode] = useState(false)

	// Sync timeoutValue with server data when it changes
	useEffect(() => {
		if (server?.data.timeout !== undefined) {
			setTimeoutValue(server.data.timeout)
		}
	}, [server?.data.timeout])

	// ibm_change: Compute current installation target from server data
	const currentTarget = useMemo<'global' | 'project'>(() => {
		return server?.data.source || 'global'
	}, [server?.data.source])

	// Modal state management using useModal hook
	const deleteConfirmModal = useModal()
	const uninstallConfirmModal = useModal()
	const installModal = useModal<MarketplaceItem>()

	// ibm_change: Use extracted hook for marketplace install logic
	const { handleInstall: handleInstallFromHook } = useMarketplaceInstall(marketplaceItems, installModal)


	// Find the original marketplace item if this is a marketplace server
	const marketplaceItem = useMemo(() => {
		if (!server || !isMarketplaceMcpServer(server) || !server.metaData?.id) {
			return undefined
		}
		const item = marketplaceItems?.find((item) => item.id === server.metaData?.id && item.type === "mcp")
		// Type guard to ensure we only return MCP items
		return item?.type === "mcp" ? item : undefined
	}, [server, marketplaceItems])

	// Extract current parameters from server config for edit mode
	const currentParameters = useMemo(() => {
		if (!server?.data.config) {
			return {}
		}
		try {
			const config = JSON.parse(server.data.config)
			// Extract env variables as parameters (for stdio servers)
			if (config.env && typeof config.env === 'object') {
				return config.env as Record<string, string>
			}
			// For other server types, return empty object
			return {}
		} catch (error) {
			logger.error('Failed to parse server config for parameters:', error)
			return {}
		}
	}, [server?.data.config])

	// Calculate current installation status from live metadata
	const isInstalled = useMemo(() => {
		if (!server || !isMarketplaceMcpServer(server) || !server.metaData?.id) {
			return false
		}
		// For marketplace servers, check using the server name
		const checkKey = server.data.name
		return !!(
			marketplaceInstalledMetadata?.global[checkKey] || marketplaceInstalledMetadata?.project[checkKey]
		)
	}, [server, marketplaceInstalledMetadata])

	// Check if there are errors to display
	const hasErrors = server?.data.errorHistory && server.data.errorHistory.length > 0

	// Check if there are resources to display
	const hasResources =
		(server?.data.resources && server.data.resources.length > 0) ||
		(server?.data.resourceTemplates && server.data.resourceTemplates.length > 0)

	// Filter tools based on search query and enabled/disabled status
	const filteredTools = useMemo(() => {
		if (!server?.data.tools) return []

		let tools = server.data.tools

		// Apply enabled/disabled/alwaysAllowed filter
		if (toolFilterType === "enabled") {
			tools = tools.filter((tool: McpTool) => tool.enabledForPrompt ?? true)
		} else if (toolFilterType === "disabled") {
			tools = tools.filter((tool: McpTool) => !(tool.enabledForPrompt ?? true))
		} else if (toolFilterType === "alwaysAllowed") {
			tools = tools.filter((tool: McpTool) => tool.alwaysAllow === true)
		}

		// Apply search filter
		if (!toolSearchQuery.trim()) {
			return tools
		}

		const query = toolSearchQuery.toLowerCase()
		return tools.filter((tool: McpTool) => {
			// Search in tool name and description
			if (tool.name.toLowerCase().includes(query) ||
				(tool.description && tool.description.toLowerCase().includes(query))) {
				return true
			}

			// Search in parameter names and descriptions
			if (tool.inputSchema && "properties" in tool.inputSchema) {
				const properties = tool.inputSchema.properties as Record<string, any>
				return Object.entries(properties).some(([paramName, schema]) => {
					return paramName.toLowerCase().includes(query) ||
						(schema.description && schema.description.toLowerCase().includes(query))
				})
			}

			return false
		})
	}, [server?.data.tools, toolSearchQuery, toolFilterType])

	// Action handlers
	const handleDelete = () => {
		if (!server) return
		setIsDeleting(true)
		try {
			vscode.postMessage({
				type: "deleteMcpServer",
				serverName: server.data.name,
				source: server.data.source || "global",
			})
			// Wait a bit for the deletion to process, then go back
			setTimeout(() => {
				deleteConfirmModal.close()
				setIsDeleting(false)
				onBack()
			}, 500)
		} catch (error) {
			logger.error("Failed to delete MCP server:", error)
			setIsDeleting(false)
		}
	}

	// ibm_change: Use hook's handleInstall which opens the modal for parameter collection
	const handleInstall = () => {
		if (!server) {
			logger.error("Cannot install: server not found")
			return
		}
		handleInstallFromHook(server)
	}

	// ibm_change: Handler for editing parameters (marketplace) or opening mcp.json (custom)
	const handleEditParameters = () => {
		if (!server) {
			logger.error("Cannot edit: server not found")
			return
		}

		// For custom MCP servers, open the mcp.json file directly at the server definition
		if (!isMarketplaceMcpServer(server)) {
			const messageType = server.data.source === 'project' ? 'openProjectMcpSettings' : 'openMcpSettings'
			vscode.postMessage({
				type: messageType,
				serverName: server.data.name,
			})
			return
		}

		// For marketplace servers, open the install modal in edit mode
		if (!marketplaceItem) {
			logger.error("Cannot edit parameters: marketplace item not found")
			return
		}

		// Set edit mode and open modal
		setIsEditMode(true)

		// Open the install modal with the marketplace item
		installModal.open(marketplaceItem)
	}

	const handleUninstall = () => {
		if (!marketplaceItem || !server) {
			logger.error("Cannot uninstall: marketplace item not found")
			return
		}

		setIsDeleting(true)

		// Set up message listener for uninstall result
		createMessageListener({
			messageType: 'marketplaceRemoveResult',
			matchCondition: (message) => message.slug === server.data.name,
			onSuccess: () => {
				setIsDeleting(false)
				uninstallConfirmModal.close()
				onBack()
			},
			onError: (error) => {
				logger.error("Failed to uninstall MCP server:", error)
				setIsDeleting(false)
				// TODO: Show error notification to user
			},
			timeout: 30000
		})

		// Send uninstall message
		vscode.postMessage({
			type: "removeInstalledMarketplaceItem",
			mpItem: marketplaceItem,
			mpInstallOptions: { target: server.data.source || "global" },
		})
	}

	const handleRestart = () => {
		if (!server) return
		vscode.postMessage({
			type: "restartMcpServer",
			text: server.data.name,
			source: server.data.source || "global",
		})
	}

	const handleToggleEnabled = (checked: boolean) => {
		if (!server) return
		vscode.postMessage({
			type: "toggleMcpServer",
			serverName: server.data.name,
			source: server.data.source || "global",
			disabled: !checked,
		})
	}

	const handleTimeoutChange = (value: string) => {
		if (!server) return
		const newTimeout = parseInt(value, 10)
		setTimeoutValue(newTimeout)
		vscode.postMessage({
			type: "updateMcpTimeout",
			serverName: server.data.name,
			source: server.data.source || "global",
			timeout: newTimeout,
		})
	}

	if (!server) {
		return (
			<div className="flex flex-col items-center justify-center py-12 text-vscode-descriptionForeground">
				<p className="text-sm">{t("ibmSettings:mcp.no_servers")}</p>
				<Button variant="ghost" onClick={onBack} className="mt-4">
					{t("common:actions.go_back")}
				</Button>
			</div>
		)
	}

	// Determine which action buttons to show based on server type and installation status
	const actionButtons = server ? [
		// Restart button: Show for all installed/configured servers
		createActionButton({
			key: "restart",
			condition: !isMarketplaceMcpServer(server) || isInstalled,
			icon: RefreshCw,
			onClick: handleRestart,
			title: t("ibmSettings:mcp.actions.restart_server"),
			className: "text-vscode-foreground hover:text-vscode-foreground",
		}),
		// ibm_change: Edit button: Show for custom MCPs (opens mcp.json) and installed marketplace MCPs (opens modal)
		createActionButton({
			key: "edit",
			condition: !isMarketplaceMcpServer(server) || (isMarketplaceMcpServer(server) && isInstalled),
			icon: Edit,
			onClick: handleEditParameters,
			title: !isMarketplaceMcpServer(server)
				? t("ibmSettings:mcp.actions.edit_configuration")
				: t("ibmSettings:mcp.actions.edit_parameters"),
			className: "text-vscode-foreground hover:text-vscode-foreground",
		}),
		// Delete button: Show for custom/local MCPs AND installed marketplace MCPs
		createActionButton({
			key: "delete",
			condition: canDeleteMcpServer(server),
			icon: Trash2,
			onClick: () => deleteConfirmModal.open(),
			title: t("ibmSettings:mcp.actions.delete_server"),
			disabled: isDeleting,
			className: "text-vscode-foreground hover:text-vscode-foreground",
		}),
		// Uninstall button: Show only for installed marketplace MCPs
		createActionButton({
			key: "uninstall",
			condition: isMarketplaceMcpServer(server) && isInstalled,
			onClick: () => uninstallConfirmModal.open(),
			title: t("ibmSettings:mcp.actions.uninstall_server"),
			variant: "outline",
			size: "default",
			text: t("common:actions.uninstall"),
		}),
		// Install button: Show only for not-installed marketplace MCPs
		createActionButton({
			key: "install",
			condition: isMarketplaceMcpServer(server) && !isInstalled,
			onClick: handleInstall,
			title: t("ibmSettings:mcp.actions.install_server"),
			variant: "outline",
			size: "default",
			text: t("common:actions.install"),
		})
	] : []

	return (
		<>
			<ItemOverview
				header={
					<OverviewHeader
						title={server.data.name}
						onBack={onBack}
						actions={
							<>
								{/* Enable/Disable toggle: Show for all installed/configured servers - placed first */}
								{server && (!isMarketplaceMcpServer(server) || isInstalled) && (
									<StandardTooltip
										content={
											server.data.disabled
												? t("ibmSettings:mcp.actions.enable_server")
												: t("ibmSettings:mcp.actions.disable_server")
										}
									>
										<div>
											<ToggleButton
												checked={!server.data.disabled}
												onChange={handleToggleEnabled}
												noContainer={true}
											/>
										</div>
									</StandardTooltip>
								)}
								{actionButtons}
							</>
						}
					/>
				}
			>
				<Section>
					{
						server.metaData?.description && (
							<SectionRow
								title={t("ibmSettings:shared.details.description")}
								description={server.metaData.description}
							/>
						)
					}

					{server.metaData?.author && (
						<SectionRow title={t("ibmSettings:shared.details.author")} description={server.metaData.author} />
					)}

					<SectionRow
						title={t("ibmSettings:shared.details.scope")}
						description={server.data.source === "project" ? t("ibmSettings:shared.badges.project") : t("ibmSettings:shared.badges.global")}
					/>

					{/* Tags */}
					{server.metaData?.tags && server.metaData.tags.length > 0 && (
						<div className="p-2 pb-3">
							<label className="block text-sm font-medium text-vscode-foreground mb-1">{t("ibmSettings:shared.details.tags")}</label>
							<div className="flex flex-wrap gap-2">
								{server.metaData.tags.map((tag: string) => (
									<VSCodeBadge key={tag} className="capitalize">
										{tag}
									</VSCodeBadge>
								))}
							</div>
						</div>
					)}


				</Section>

				{/* Errors Section - Only show if there are errors */}
				{hasErrors && (
					<CollapsibleSection
						className="mt-4"
						title={t("ibmSettings:mcp.details.errors_heading")}
						description={
							server.data.errorHistory!.length === 1
								? t("ibmSettings:mcp.details.error_count_singular", { count: server.data.errorHistory!.length })
								: t("ibmSettings:mcp.details.error_count_plural", { count: server.data.errorHistory!.length })
						}
						defaultCollapsed={false}
					>
						{[...server.data.errorHistory!]
							.sort((a, b) => b.timestamp - a.timestamp)
							.map((error, index) => (
								<McpErrorSettingRow key={`${error.timestamp}-${index}`} error={error} />
							))}
					</CollapsibleSection>
				)}

				{/* Tools Section - Only show if not a marketplace server or if installed */}
				{(!isMarketplaceMcpServer(server) || isInstalled) && (
					<CollapsibleSection
						className="mt-4"
						title={t("ibmSettings:mcp.details.tools_tab")}
						description={t("ibmSettings:mcp.details.tools_description")}
						defaultCollapsed={false}
						headerContent={
							server.data.tools && server.data.tools.length > 0 ? (
								<div className="mb-2 pl-2 flex items-center gap-2">
									<SearchInput
										value={toolSearchQuery}
										onChange={setToolSearchQuery}
										placeholder={t("ibmSettings:mcp.search_tools_placeholder")}
										clearTooltip={t("ibmSettings:mcp.clear_search")}
										className="flex-1"
									/>

									{/* Filter Dropdown */}
									<Select value={toolFilterType} onValueChange={(value) => setToolFilterType(value as "all" | "enabled" | "disabled" | "alwaysAllowed")}>
										<SelectTrigger className="bg-vscode-dropdown-background border-vscode-dropdown-border text-[11px] min-w-[100px]">
											<SelectValue />
										</SelectTrigger>
										<SelectContent>
											<SelectItem value="all">{t("ibmSettings:shared.filters.all")}</SelectItem>
											<SelectItem value="enabled">{t("ibmSettings:mcp.filter_enabled")}</SelectItem>
											<SelectItem value="disabled">{t("ibmSettings:mcp.filter_disabled")}</SelectItem>
											<SelectItem value="alwaysAllowed">{t("ibmSettings:mcp.filter_always_allowed")}</SelectItem>
										</SelectContent>
									</Select>
								</div>
							) : undefined
						}
					>
						{server.data.tools && server.data.tools.length > 0 ? (
							<>
								{filteredTools.length > 0 ? (
									<>
										{filteredTools.map((tool: McpTool) => (
											<McpToolSettingRow
												key={`${tool.name}-${server.data.name}-${server.data.source || "global"}`}
												tool={tool}
												serverName={server.data.name}
												serverSource={server.data.source || "global"}
											/>
										))}
									</>
								) : (
									<div className="p-4 text-sm text-vscode-descriptionForeground">
										{t("common:status.no_results")}
									</div>
								)}

								{/* Network Timeout - always show when there are tools, regardless of filtering */}
								<SectionRow
									title={t("ibmSettings:mcp.details.network_timeout_label")}
									description={t("ibmSettings:mcp.details.network_timeout_description")}
									actionComponent={
										<Select value={timeoutValue.toString()} onValueChange={handleTimeoutChange}>
											<SelectTrigger className="w-[120px]">
												<SelectValue />
											</SelectTrigger>
											<SelectContent>
												{timeoutOptions.map((option) => (
													<SelectItem key={option.value} value={option.value.toString()}>
														{option.label}
													</SelectItem>
												))}
											</SelectContent>
										</Select>
									}
								/>
							</>
						) : (
							<div className="p-4 text-sm text-vscode-descriptionForeground">
								{t("ibmSettings:mcp.details.no_tools_available")}
							</div>
						)}
					</CollapsibleSection>
				)}

				{/* Resources Section - Only show if there are resources */}
				{hasResources && (
					<div className="mt-4">
						<SectionHeader
							title={t("ibmSettings:mcp.details.resources_tab")}
							description={t("ibmSettings:mcp.details.resources_description")}
						/>
						<Section>
							{[
								...(server.data.resourceTemplates || []),
								...(server.data.resources || []),
							].map((item) => (
								<McpResourceSetting
									key={"uriTemplate" in item ? item.uriTemplate : item.uri}
									item={item}
								/>
							))}
						</Section>
					</div>
				)}
			</ItemOverview>

			{/* Delete Confirmation Dialog */}
			<ConfirmationDialog
				isOpen={deleteConfirmModal.isOpen}
				title={t("ibmSettings:mcp.delete_confirm_title")}
				message={t("ibmSettings:mcp.delete_confirm_message")}
				confirmText={t("common:actions.delete")}
				cancelText={t("common:actions.cancel")}
				isLoading={isDeleting}
				onConfirm={handleDelete}
				onCancel={deleteConfirmModal.close}
				isDestructive
			/>

			{/* Uninstall Modal */}
			{uninstallConfirmModal.isOpen && marketplaceItem && marketplaceItem.type === "mcp" && (
				<McpUninstallModal
					item={marketplaceItem}
					isOpen={uninstallConfirmModal.isOpen}
					onClose={uninstallConfirmModal.close}
					onConfirm={handleUninstall}
					isLoading={isDeleting}
				/>
			)}

			{/* Install Modal - Support both install and edit modes */}
			{installModal.isOpen && installModal.data && installModal.data.type === "mcp" && (
				<McpInstallModal
					item={installModal.data}
					isOpen={installModal.isOpen}
					onClose={() => {
						installModal.close()
						setIsEditMode(false)
					}}
					hasWorkspace={!!cwd}
					isEditMode={isEditMode}
					currentTarget={currentTarget}
					currentParameters={currentParameters}
				/>
			)}
		</>
	)
}

