/**
 * This file defines the type structure for JSON-based settings definitions.
 * These types are designed to be serializable as pure JSON and used to generate
 * settings UI components programmatically.
 *
 * Note: Component prop types are defined in their respective component files
 * in webview-ui/src/ibm/components/settings/components/actions/
 */

import {
	ConditionOperator,
	ConditionDefinition,
	BindingConfig,
	ExtensionStateBinding,
	VSCodeSettingBinding,
	ToggleProps,
	CheckboxProps,
	NumberInputProps,
	TextInputProps,
	SliderProps,
	SelectProps,
	SelectOption,
	CustomComponentDefinition,
} from "./components/actions"

/**
 * Available action component types that can be used in settings rows
 */
export enum ActionComponentType {
	TOGGLE = "toggle",
	CHECKBOX = "checkbox",
	NUMBER_INPUT = "numberInput",
	TEXT_INPUT = "textInput",
	SLIDER = "slider",
	SELECT = "select",
	COMMAND_BUTTON = "commandButton",
	CUSTOM = "custom",
}

// Re-export types from components
export { ConditionOperator }
export type { ConditionDefinition, SelectOption, BindingConfig, ExtensionStateBinding, VSCodeSettingBinding }

/**
 * Union type for all action component props (excluding binding, value, and setValue)
 */
export type ActionComponentProps =
	| ToggleProps
	| CheckboxProps
	| NumberInputProps
	| TextInputProps
	| SliderProps
	| SelectProps
	| CustomComponentDefinition

/**
 * Defines an action component with its type, binding, and props
 * This structure must be serializable as pure JSON
 */
export interface ActionComponentDefinition {
	/** Type of action component */
	type: ActionComponentType
	/** Binding configuration (optional - not all components need binding) */
	binding?: BindingConfig
	/** Component-specific properties (excluding binding, value, and setValue) */
	props?: ActionComponentProps
	/** Condition to determine if this component should be rendered */
	condition?: ConditionDefinition
}

/**
 * Defines a child row within an expandable section
 * This structure must be serializable as pure JSON
 */
export interface ChildRowDefinition {
	/** Action component to display */
	actionComponent: ActionComponentDefinition
	/** CSS class name to apply to the row */
	className?: string
	/** Condition to determine if this row should be rendered */
	condition?: ConditionDefinition
}

/**
 * Defines a settings row with title, description, and action component
 * This structure must be serializable as pure JSON
 */
export interface SectionRowDefinition {
	/** Translation ID for row title */
	title: string
	/** Translation ID for row description */
	description?: string
	/** Action component to display on the right side */
	actionComponent?: ActionComponentDefinition
	/** Child components to display when expanded, also indicates if an expandable row is required */
	children?: (ActionComponentDefinition | ChildRowDefinition)[]
	/** CSS class name to apply to the row */
	className?: string
	/** Condition to determine if this row should be rendered */
	condition?: ConditionDefinition
}

/**
 * Defines a complete settings section with rows or a custom component
 * This structure must be serializable as pure JSON
 */
export interface SectionDefinition {
	/** Translation ID for section title */
	title?: string
	/** Translation ID for section description, or a custom component definition */
	description?: string | ActionComponentDefinition
	/** CSS class name to apply to the section */
	className?: string
	/** Array of row definitions (mutually exclusive with customComponent) */
	rows?: SectionRowDefinition[]
	/** Custom component to render instead of rows (mutually exclusive with rows) */
	customComponent?: ActionComponentDefinition
	/** Condition to determine if this section should be rendered */
	condition?: ConditionDefinition
}

/**
 * Defines a complete settings tab with header and sections
 * This structure must be serializable as pure JSON
 */
export interface SettingsTabDefinition {
	/** Array of section definitions */
	sections: SectionDefinition[]
}

