import React from "react"
import { Button } from "@/components/ui/button"
import { StandardTooltip } from "@/components/ui/standard-tooltip"
import { useAppTranslation } from "@/i18n/TranslationContext"

interface ModalFooterProps {
	onCancel: () => void
	onConfirm: () => void
	isLoading: boolean
	isEditMode?: boolean
}

/**
 * ModalFooter Component
 *
 * Shared component for modal footer buttons (Cancel and Install/Update).
 * Uses StandardTooltip and proper button variants to match EditModeModal pattern.
 */
export const ModalFooter: React.FC<ModalFooterProps> = ({
	onCancel,
	onConfirm,
	isLoading,
	isEditMode = false,
}) => {
	const { t } = useAppTranslation()

	return (
		<>
			<StandardTooltip content={t("ibmSettings:modes.edit_modal.cancel_button_tooltip")}>
				<Button
					variant="secondary"
					onClick={onCancel}
					disabled={isLoading}
				>
					{t("common:actions.cancel")}
				</Button>
			</StandardTooltip>
			<StandardTooltip content={isEditMode
				? t("ibmSettings:marketplace.install_modal.update_button_tooltip")
				: t("ibmSettings:marketplace.install_modal.install_button_tooltip")}>
				<Button
					variant="primary"
					onClick={onConfirm}
					disabled={isLoading}
				>
					{/* ibm_change: Show loading text when isLoading is true */}
					{isLoading
						? (isEditMode
							? t("marketplace:install.updating")
							: t("marketplace:install.installing"))
						: (isEditMode
							? t("marketplace:install.updateButton")
							: t("marketplace:install.button"))}
				</Button>
			</StandardTooltip>
		</>
	)
}

